def _normalize_directive_dossier_payload(
    self, payload: Dict[str, object], *, content=None, current_turn: int = 0,
) -> Dict[str, object]:
    """机械旨意的唯一结构边界；不完整载荷响亮拒绝。"""
    # #658：纯御笔强推不经 ordinary triad 归一（prepare/commit/ensure 共吃）。
    # text/actor 等会话字段须保留——pending payload 以它们为成案正文真源。
    if classify_directive_structured_kind(payload) == "push":
        push_id = imperial_push_target_dossier_id(payload)
        assert push_id is not None
        mode = self._normalize_dossier_mode(
            payload["mode"] if "mode" in payload else "ordinary"
        )
        out: Dict[str, object] = {
            "target_dossier_id": int(push_id), "mode": mode,
        }
        for key in ("text", "actor", "source_chat_turn_id"):
            if payload.get(key) not in (None, ""):
                out[key] = payload[key]
        return out
    normalized = dict(payload)
    normalized["mode"] = self._normalize_dossier_mode(
        normalized["mode"] if "mode" in normalized else "ordinary"
    )
    action = str(normalized.get("dossier_action_type") or "").strip()
    if action == "grant_allocation":
        grant_action = str(normalized.get("grant_action") or "").strip()
        if grant_action in {"加衔", "荫叙"}:
            normalized.pop("delta", None)
        elif self._is_army_pay_grant_payload(normalized):
            # #1503：协饷先且只经 require_explicit_xiexang_fields，不经 amount/account 首错。
            normalized = self._normalize_army_pay_grant_payload(normalized)
        else:
            from ming_sim.action_clusters import field_population_allowed
            from ming_sim.action_materialize import require_grant_allocation_shape
            purpose = str(normalized.get("purpose") or "").strip()
            if purpose and not field_population_allowed(
                "grant_allocation", "purpose", normalized,
            ):
                raise ValueError(f"非协饷拨帑不得夹带 purpose={purpose}")
            # #1716：amount/account 唯一验形；分类默认 grant_action=「无」时只借金钱动作过 shape，不回写。
            # 普通/legacy fallback（缺/空 grant_action）须显式非空 account，禁默认国库。
            shape_ga = grant_action if grant_action not in {"", "无"} else "赏赉"
            if grant_action in {"", "无"}:
                account_raw = normalized.get("account")
                if account_raw is None or not str(account_raw).strip():
                    raise ValueError("拨帑旨意缺少 account")
            shaped = require_grant_allocation_shape(
                grant_action=shape_ga,
                amount=normalized.get("amount"),
                account=normalized.get("account"),
            )
            normalized["amount"] = int(shaped["amount"])
            normalized["account"] = str(shaped["account"])
            surface = str(
                normalized.get("execution_surface") or "in_transit"
            ).strip()
            if surface not in {"immediate", "in_transit"}:
                raise ValueError("拨帑旨意 execution_surface 非法")
            normalized["execution_surface"] = surface
            normalized.pop("delta", None)
    elif action == "pay_order_override":
        # #653：结构化载荷 presence 在指令归一边界先验（键形/值域/幻影 region
        # 仍由成案点与物化点共 prepare_pay_order_entries 同一验形，不在此重复）。
        entries = normalized.get("entries")
        if not isinstance(entries, list) or not entries:
            raise ValueError("pay_order_override 旨意缺少 entries 结构化载荷")
    elif action in {
        "assignment", "authorization", "secret_authorization", "military_order",
    }:
        assignee = str(
            normalized.get("assignee_id")
            or normalized.get("assignee")
            or normalized.get("holder_id")
            or ""
        ).strip()
        if assignee and content is not None:
            from ming_sim.session import _find_existing_minister
            assignee = _find_existing_minister(content, assignee, self) or ""
        if not assignee and action in {"authorization", "secret_authorization"}:
            raise ValueError(f"{action} 旨意缺少 canonical assignee")

def settle_tick(
    st: Dict[str, Any], p: Dict[str, Any], actions: List[Dict[str, Any]]
) -> FiscalTickResult:
    """单省单月财政 tick。st=开账(CASH/CLAIM/官民田/隐田)，p=本月参数(率/额/Due)，
    actions=本月动作(玩家旨意/事件灌入)。返回新末态 + 流水分解；坏输入/守恒破一律 raise。"""
    # ── 容器型验形（最前置）：st/p 非 dict、actions 非 list/tuple → ValueError，否则下方
    #    `sk in st` / `rq in p` / `for a in actions` 抛 TypeError 逃逸调用方隔离（cmr R3 concur）──
    if not isinstance(st, dict):
        raise ValueError("st 非字典")
    if not isinstance(p, dict):
        raise ValueError("p 非字典")
    if not isinstance(actions, (list, tuple)):
        raise ValueError("actions 非 list/tuple")
    # ── 必填参数 presence（缺省不默认 0——火耗率缺省成 0 = 静默改经济学）──
    for rq in ("三饷应征", "火耗率", "逋赋率", "起运定额", "Due"):
        if rq not in p:
            raise ValueError(f"param {rq} 缺失")
    # ── 开账 stock 全面验形（前置于下方 float 构造：float([]) 等非数值会 TypeError 早于守门、
    #    逃逸调用方 (ValueError/守恒破) 隔离炸 pre_settle，cmr ship-pre R1/R2；CLAIM 也拦——
    #    负军饷欠→偿还环凭空生钱）──
    for sk in (*CASH_KEYS, *CLAIM_KEYS, "官民田", "隐田"):
        if sk in st and st[sk] is None:
            raise ValueError(f"开账 stock {sk} 为 None")
        _sraw = st.get(sk, 0)
        if isinstance(_sraw, bool) or not isinstance(_sraw, (int, float)):
            raise ValueError(f"开账 stock {sk} 非数值")
        if not math.isfinite(float(_sraw)):
            raise ValueError(f"开账 stock {sk} 非有限值(NaN/inf)")
        if float(_sraw) < 0:
            raise ValueError(f"开账 stock {sk} 为负")

    cash = {k: float(st.get(k, 0)) for k in CASH_KEYS}
    claim = {k: float(st.get(k, 0)) for k in CLAIM_KEYS}
    官民田 = float(st.get("官民田", 0))
    隐田 = float(st.get("隐田", 0))
    地0 = 官民田 + 隐田  # 土地守恒锚：清丈只重分类，总亩数不变
    cash0 = sum(cash.values())
    C0 = {k: cash[k] for k in CASH_KEYS if k.startswith("C_")}
    claim0 = dict(claim)
    cash_in = cash_out = 0.0
    # Due 在任何折算消费前验形，避免坏容器先逃成 TypeError/AttributeError。
    _due = p["Due"]
    if isinstance(_due, bool) or not isinstance(_due, dict):
        raise ValueError("Due 非字典")
    for hk, dv in _due.items():
        if hk not in _DUE_KEYS:
            raise ValueError(f"Due 含未知科目 {hk}")
        if isinstance(dv, bool) or not isinstance(dv, (int, float)):
            raise ValueError(f"Due[{hk}] 非数值")
        if not math.isfinite(float(dv)):
            raise ValueError(f"Due[{hk}] 非有限值(NaN/inf)")
        if float(dv) < 0:
            raise ValueError(f"Due[{hk}] 为负")

    # ── #653 偿还序 override ＋ Due 折发系数（ADR 0090）：缺省=祖制默认序、无折 ──
    due_order = _resolve_order_param(p, "due_order", _DUE_KEYS)
    arrears_order = _resolve_order_param(p, "arrears_order", _ARREARS_KEYS)
    _haircut_bp = _resolve_haircut_param(p)  # 验形 fail-loud；实际折算走 _effective_dues
    eff_due = _effective_dues(p)

    r: Dict[str, Any] = dict(
        实征=0, 火耗实收=0, 清欠=0, 拨付gross=0, 起运到京=0, 实付=0, 偿旧欠=0, 行政补饷=0,
        漂没=0, 中饱=0, 民欠新增=0, 蠲免=0, unmet_relief=0,
        NewDebt={"军饷欠": 0, "官俸欠": 0, "宗禄欠": 0},
        Repaid={"军饷欠": 0, "官俸欠": 0, "宗禄欠": 0},
        action还={"军饷欠": 0},
        # #653 流水分解新字段：per-科目实付分账（TSV 断言实付序）＋折发免除额
        实付分账={h: 0.0 for h in _DUE_KEYS},
        **{f"haircut_{h}": _raw_due(p, h) - eff_due[h] for h in _DUE_KEYS},
    )

    def xfer_internal(frm: str, to: str, amount: float, eff: float = 1.0) -> float:
        """CASH 内部 3-way 转移：source 减 = target 增 + C_eff损耗 增。"""
        actual = min(amount, cash[frm])
        cash[frm] -= actual
        got = actual * eff
        loss = actual * (1 - eff)
        cash[to] += got
        if loss > 0:
            cash["C_eff损耗"] += loss

def _eval_gate_key(key: str, metrics: Dict[str, int], db: GameDB) -> Optional[float]:
    """把 gate key 解析成一个数值。形式：
      - 'metric_name'                           → metrics[key]
      - 'region.<id>.<field>'                   → regions 表
      - 'region.<id1>|<id2>|.<field>.<agg>'     → 多省聚合 (max/min/avg/sum)
      - 'army.<id>.<field>' / 多军 + agg
      - 'building.<id>.<field>' / 多建筑 + agg
      - 'power.<id>.<field>' / 多 + agg
      - 'character.<name>.<field>' / 多人物 + agg
      - 'event.<id>.terminal_state'               → event_triggers 表文本门专用
      - 'class.<name>.<field>'                  → classes 表全国汇总 (region_id='')
      - 'class.<name>@<region>.<field>'         → classes 表省级
      - 'class.<name>@<r1>|<r2>|.<field>.<agg>' → 多省同阶级聚合
      - 'event.<id>.triggered'                  → event_triggers 账，已发=1 未发=0
    解析失败/数据缺失返回 None（gate 视为不通过，由调用方处理）。
    """
    if "." not in key:
        if key in metrics:
            try:
                return int(metrics[key])
            except (TypeError, ValueError):
                return None
        return None
    parts = key.split(".")
    table = parts[0]
    if table not in GATE_TABLES:
        return None
    # 末段可能是 agg，先抽出
    agg = None
    if parts[-1] in _GATE_AGG_FUNCS:
        agg = parts[-1]
        parts = parts[:-1]
    if len(parts) < 3:
        return None
    field = parts[-1]
    id_segment = ".".join(parts[1:-1])
    field = _gate_sql_field(table, field, key, kind="numeric")
    if table == "class" and "@" in id_segment and "|" in id_segment.split("@", 1)[1]:
        # 简写：class.<name>@<r1>|<r2>|<r3>.<field> → 展开成 [name@r1, name@r2, name@r3]
        cname, rest = id_segment.split("@", 1)
        ids = [f"{cname}@{r}" for r in rest.split("|") if r]
    else:
        ids = id_segment.split("|") if "|" in id_segment else [id_segment]
        ids = [x for x in ids if x]
    if not ids:
        return None
    # class 表的 id 是 name 或 name@region；其它表 id 就是行 id
    values: List[float] = []
    for cid in ids:
        row = None
        if table == "event":
            if cid not in db.content.event_by_id:
                return None
            values.append(1 if db.has_event_terminal_state(cid, "triggered") else 0)
            continue
        if table == "region":
            row = db.conn.execute(f"SELECT {field} FROM regions WHERE id = ?", (cid,)).fetchone()
        elif table == "army":
            row = db.conn.execute(f"SELECT {field} FROM armies WHERE id = ?", (cid,)).fetchone()
        elif table == "building":
            row = db.conn.execute(f"SELECT {field} FROM buildings WHERE id = ?", (cid,)).fetchone()
        elif table == "power":
            row = db.conn.execute(f"SELECT {field} FROM powers WHERE id = ?", (cid,)).fetchone()
        elif table == "faction":
            # factions 表主键是 name（中文，如 阉党），field 取 leverage/satisfaction
            row = db.conn.execute(f"SELECT {field} FROM factions WHERE name = ?", (cid,)).fetchone()
        elif table == "character":
            row = db.conn.execute(f"SELECT {field} FROM characters WHERE name = ?", (cid,)).fetchone()
        elif table == "class":
            if "@" in cid:
                cname, rid = cid.split("@", 1)
            else:
                cname, rid = cid, ""
            row = db.conn.execute(
                f"SELECT {field} FROM classes WHERE name = ? AND region_id = ?",
                (cname, rid),
            ).fetchone()
        if row is None:
