def _guess_caller_tag(kwargs: Dict[str, object]) -> str:
    """从 messages 的所有 system 段拼合后猜哪个 agent 在调用,用于 token 日志可读。"""
    messages = kwargs.get("messages") or []
    sys_text = ""
    for msg in messages:
        if not isinstance(msg, dict) or msg.get("role") != "system":
            continue
        c = msg.get("content")
        if isinstance(c, str):
            sys_text += c
        elif isinstance(c, list):
            for item in c:
                if isinstance(item, dict):
                    sys_text += str(item.get("text", ""))
    # minister 必须先判：大臣 system 末尾注入上月邸报全文(simulator 产出，含『日讲官』
    # 『档房书办』等词)，若先判 extractor/simulator 会把大臣对话误标成结算 agent。
    # 大臣自身开场白『扮演被皇帝召见』只在大臣 prompt 出现，且在邸报之前 → 用它先认。
    if "扮演被皇帝召见" in sys_text or "大臣扮演" in sys_text:
        return "minister"
    # 结算/写诏 agent 的 system = game_world_prompt(很长) + 自身 prompt，关键锚点在中后段，
    # 不能只看开头窗口。这几个 agent 不注入邸报，故全文搜各自唯一开场白即可。
    if "档房书办" in sys_text:
        return "extractor"
    if "日讲官兼推演官" in sys_text or "月末推演" in sys_text:
        return "simulator"
    if "诏书润色" in sys_text or "正式诏书" in sys_text:
        return "decree-writer"
    return "?"

def _humanize_condition(text: str) -> str:
    """Formal character-condition DSL → display labels; free prose passes through unchanged."""
    if not text:
        return text
    character_condition = re.fullmatch(
        r"\s*character\.([^.]+)\.([A-Za-z_]+)\s*(==|!=|>=|<=|>|<)\s*(.+?)\s*",
        text,
    )
    if not character_condition:
        # N6: no vocabulary replace on free prose / non-formal condition text in transport.
        return text
    name, field, op, value = character_condition.groups()
    if field == "loyalty" and re.fullmatch(r"\d+", value):
        if op in {">=", ">"}:
            return f"{name}忠诚回稳"
        if op in {"<=", "<"}:
            return f"{name}忠诚未稳"
        return f"{name}忠诚非通常取值"
    label = _CHARACTER_CONDITION_FIELD_LABELS.get(field, field)
    op_label = _CONDITION_OPERATOR_LABELS.get(op, op)
    value_label = _humanize_condition_value(field, value)
    return f"{name}{label}{op_label}{value_label}"

def assert_action_candidate_shape(obj: Any) -> Dict[str, Any]:
    ok, reason = validate_action_candidate_shape(obj)
    if not ok:
        raise ActionCandidateShapeError(reason)
    kind = _resolve_kind(obj)
    out = _blank_candidate(kind=kind)

    def _enum(value: object, allowed: FrozenSet[str], default: str) -> str:
        v = str(value if value is not None else default).strip()
        if not v:
            return default
        if v in allowed:
            return v
        raise ActionCandidateShapeError(f"value {v!r} not in {sorted(allowed)}")

    for name, spec in _field_specs().items():
        raw = _field_raw(obj, spec)
        if raw is None:
            raw = spec.default
        # #658：可选正整数 id（as_int + default None）禁 generic clamp；raw 直达严格写边界
        if spec.as_int and spec.default is None:
            out[name] = _field_raw(obj, spec)
            continue
        if spec.as_int:
            out[name] = _as_int(raw, lo=int(spec.int_lo), hi=int(spec.int_hi))
        elif spec.allowed is not None:
            out[name] = _enum(raw, spec.allowed, str(spec.default))
        else:
            # 容器值须 JSON 运输（stages/stop_condition/ongoing_effects 等）；
            # str(list/dict) 是 Python repr（单引号），下游 json.loads 会当坏形丢掉。
            if isinstance(raw, (dict, list, tuple)):
                s = json.dumps(raw, ensure_ascii=False, separators=(",", ":"))
            else:
                # Canonical generated body is transport, not user-entered metadata:
                # preserve the extractor's bytes (including edge whitespace).
                s = str(raw or "")
            if spec.max_len is not None:
                s = s[: spec.max_len]
            out[name] = s
    if "draft_text" in obj:
        out["draft_text"] = obj.get("draft_text")
    # #1509：confirmation 目标编号非 FieldSpec，须随 candidate 过缝。
    if "target_ids" in obj and obj.get("target_ids") is not None:
        out["target_ids"] = obj.get("target_ids")
    elif "目标编号" in obj and obj.get("目标编号") is not None:
        out["target_ids"] = obj.get("目标编号")
    # #1783+#1778：仅 grant 一件事一案可带承办人/名单过缝（assignment 承办人走后置抽取，
    # assignee 不得当改派入口——见 test_assignment_lead_from_extract_*）。
    if kind == "grant_allocation":
        for key in ("assignee", "assignee_id", "assignee_name", "participant_roster", "承办人"):
            if key in obj and obj.get(key) not in (None, ""):
                out[key if key != "承办人" else "assignee"] = obj.get(key)
    return out

