def record_monthly_grant_reconciliations(
    self, turn: int, generated: object = None, *,
    rejection_collector=None,
    source: object = None,
) -> List[Dict[str, object]]:
    """月度节拍：逐路软判实抵 → clamp → 落被护侧对账记录。

    无提案时用护行口径中位（无护行亦可机械落账，供 S10 结案合并）。
    不写 0058 进展、不二次扣库、不改原 economy_move。

    #1745 / ADR 0015-D6/D7：域级坏项逐项拒收；形状（非 list/非 dict 项）归
    sanitize_delta_shape 独家，本方法不平行净化。好项与未提案目标的中位落账
    仍在同一 atomic。拒收归属外层 RejectionCollector（flush/commit/mirror/
    rollback 由 settle 编排所有者负责；本方法不自建 collector）。
    """
    from ming_sim.applier import Provenance, RejectedItem

    targets = {
        int(item["dossier_id"]): item
        for item in self.list_monthly_grant_reconciliation_targets()
    }
    if generated is None:
        generated = []
    if not targets and generated in (None, []):
        return []

    # source 走 collector 归一；None 取 typed 默认 unknown（0008-D5）。
    if source is None:
        source = Provenance.unknown

    def _reject(raw_item: object, reason: str, category: str) -> None:
        # 无外层归属不得无痕继续（0150-D2/D3；#1745 删自有 collector 旁路）。
        if rejection_collector is None:
            from ming_sim.applier import RejectionCollectorRequired
            raise RejectionCollectorRequired(
                "dossier_reconciliations 拒收须由外层 RejectionCollector 归属"
            )
        # ADR 0015 F1：RejectedItem.item 恒 dict；非 dict 包装 raw_value。
        # 域级拒收的 item 已是 dict；形状级（非 list/非 dict 项）归 sanitize_delta_shape
        # 独家（0015-D6/F1，#1745 删双 producer）。
        if isinstance(raw_item, dict):
            payload = dict(raw_item)
        else:
            payload = {"raw_value": raw_item}
        rejection_collector.record(
            "dossier_reconciliations",
            RejectedItem(
                item=payload, reason=reason, category=category, source=source,
            ),
            int(turn),
        )

    # 形状净化归 sanitize_delta_shape 独家（0015-D6；#1745 删本段平行形状拒收）。
    # 非 list / 非 dict 项此处跳过域逻辑；settle 后半段 sanitize→collector 一次拒收。
    if not isinstance(generated, list):
        generated = []

    supplied: Dict[int, Tuple[object, str]] = {}
    for item in generated:
        if not isinstance(item, dict):
            continue
        try:
            dossier_id = strict_int(item.get("dossier_id", 0))
            if dossier_id <= 0:
                raise ValueError("not positive")
        except (TypeError, ValueError):
            _reject(item, "对账提案案卷编号无效", "invalid_enum")
            continue
        if dossier_id not in targets:
            _reject(
                item,
                f"对账提案指向非在途拨帑案卷：{dossier_id}",
                "missing_ref",
            )
            continue
        if dossier_id in supplied:
            _reject(item, "对账提案存在重复案卷", "invalid_enum")
            continue
        has_arrived = "arrived_amount" in item
        has_loss = "loss_amount" in item

def _apply_authority_change_item(
    db: GameDB, state: GameState, item: Dict[str, object],
) -> Dict[str, object]:
    """Apply one production-slot authority grant/revoke under the #611 contract."""
    if "dossier_id" not in item or item.get("dossier_id") in (None, ""):
        raise ValueError("missing_dossier_source")
    try:
        dossier_id = _parse_sqlite_id(item.get("dossier_id"))
    except (TypeError, ValueError):
        raise ValueError("missing_dossier_source") from None
    if dossier_id <= 0 or db.get_decree_dossier(dossier_id) is None:
        raise ValueError("missing_dossier_source")
    if not db.dossier_authorizes_effects(dossier_id):
        raise ValueError("dossier_not_effect_eligible")
    op = str(item.get("动作") or item.get("op") or "").strip()
    if op not in _AUTHORITY_GRANT_OPS | _AUTHORITY_REVOKE_OPS:
        raise ValueError("授权变更动作只收授予/收回")

    if op in _AUTHORITY_GRANT_OPS:
        holder_id = str(item.get("holder_id") or "").strip()
        privilege = str(item.get("privilege") or item.get("权项") or "").strip()
        scope = str(item.get("scope") or item.get("事域") or "").strip()
        if not holder_id or not privilege or not scope:
            raise ValueError("授予项必须含 holder_id/privilege/scope")
        if privilege not in AUTHORITY_PRIVILEGE_SET:
            raise ValueError("授权权项不在首批枚举")
        kind, separator, target_id = scope.partition(":")
        if not separator or not kind or not target_id:
            raise ValueError("invalid_authority_scope")
        if not db.conn.execute(
            "SELECT 1 FROM characters WHERE name=?", (holder_id,)
        ).fetchone():
            raise ValueError("授权对象不在人物档")
        origin = db.find_authority_by_origin(
            dossier_id, holder_id=holder_id, privilege=privilege, scope=scope,
        )
        if origin is not None:
            # Origin idempotency is independent of current applicability: a
            # revoked or expired grant remains the same durable authority row.
            return {
                "动作": "授予",
                "authority_id": int(origin["id"]),
                "dossier_id": dossier_id,
                "holder_id": holder_id,
                "privilege": privilege,
                "scope": scope,
                "reason": "same_dossier_replay",
            }
        effective_raw = item.get("effective_turn", item.get("生效回合"))
        expires_raw = item.get("expires_turn", item.get("失效回合"))
        effective_turn = (
            int(state.turn) if effective_raw in (None, "")
            else _parse_sqlite_id(effective_raw)
        )
        expires_turn = (
            None if expires_raw in (None, "")
            else _parse_sqlite_id(expires_raw)
        )
        if expires_turn is not None and expires_turn < effective_turn:
            raise ValueError("授权失效回合不得早于生效回合")
        existing = db.find_active_authority(
            state.turn, holder_id=holder_id, privilege=privilege, scope=scope,
        )
        if existing is not None:
            raise ValueError("duplicate_active_authority")
        cursor = db.conn.execute(
            "INSERT INTO authority_records "
            "(holder_id,privilege,scope,effective_turn,expires_turn,dossier_id) "
            "VALUES (?,?,?,?,?,?)",
            (
                holder_id, privilege, scope, effective_turn, expires_turn,
                dossier_id,
            ),
        )
        authority_id = int(cursor.lastrowid)
        return {
            "动作": "授予",
            "authority_id": authority_id,
            "dossier_id": dossier_id,
            "holder_id": holder_id,

def parse_agent_json(raw: str, stage: str) -> Dict[str, Any]:
    text = strip_json_fence(raw)
    # 试 1：原文直解
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        data = None
    # 试 2：截 {...} 最外层再解
    if data is None:
        start = text.find("{")
        end = text.rfind("}")
        if start < 0 or end <= start:
            abort_llm_contract(stage, "没有返回 JSON object", raw)
        snippet = text[start : end + 1]
        try:
            data = json.loads(snippet)
        except json.JSONDecodeError:
            data = None
        # 试 3：净化 control char（\r\v\f\x00-\x1f 等）后再解
        if data is None:
            cleaned = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", snippet)
            try:
                data = json.loads(cleaned)
            except json.JSONDecodeError:
                data = None
        # 试 4：截取首个合法平衡的 {...} 子串（防 LLM 重发拼接）
        if data is None:
            depth = 0
            in_str = False
            esc = False
            best_end = -1
            for i, ch in enumerate(snippet):
                if esc:
                    esc = False
                    continue
                if ch == "\\" and in_str:
                    esc = True
                    continue
                if ch == '"':
                    in_str = not in_str
                    continue
                if in_str:
                    continue
                if ch == "{":
                    depth += 1
                elif ch == "}":
                    depth -= 1
                    if depth == 0:
                        best_end = i
                        break
            if best_end > 0:
                first_block = snippet[: best_end + 1]
                first_block = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", first_block)
                try:
                    data = json.loads(first_block)
                except json.JSONDecodeError as error:
                    raise LLMContractError(
                        f"{stage} 输出不是合法 JSON：{error}\n原始输出：{raw[:800]}",
                        raw_value=raw,
                    ) from error
            else:
                raise LLMContractError(
                    f"{stage} 输出不是合法 JSON\n原始输出：{raw[:800]}",
                    raw_value=raw,
                )
    if not isinstance(data, dict):
        abort_llm_contract(stage, "顶层必须是 JSON object", raw)
    return data

def load_event_content(filename: str = "events.json") -> List[Event]:
    events: List[Event] = []
    for idx, raw in enumerate(require_list(load_json_asset(filename), filename), 1):
        item = require_dict(raw, f"{filename}[{idx}]")
        event_type = str(item.get("event_type") or "situation")
        if event_type not in ("situation", "node", "ending"):
            raise SystemExit(
                f"{filename}[{idx}] event_type 非法：{event_type!r}（仅 situation/node/ending）。"
            )
        trigger_class = str(item.get("trigger_class") or "").strip()
        if trigger_class not in ("", "strategic_foreign"):
            raise SystemExit(
                f"{filename}[{idx}] trigger_class 非法：{trigger_class!r}（仅 strategic_foreign 或空）。"
            )
        if trigger_class == "strategic_foreign" and event_type == "situation":
            raise SystemExit(
                f"{filename}[{idx}] trigger_class=strategic_foreign 仅适用于 node/ending，situation 不可声明。"
            )
        trigger_year = int(item.get("trigger_year") or 0)
        trigger_month = int(item.get("trigger_month") or 0)
        trigger_end_year = int(item.get("trigger_end_year") or 0)
        trigger_end_month = int(item.get("trigger_end_month") or 0)
        if not (0 <= trigger_month <= 12):
            raise SystemExit(f"{filename}[{idx}] trigger_month 必须在 0 到 12 之间。")
        if not (0 <= trigger_end_month <= 12):
            raise SystemExit(f"{filename}[{idx}] trigger_end_month 必须在 0 到 12 之间。")
        open_window_raw = item.get("open_window", False)
        if not isinstance(open_window_raw, bool):
            raise SystemExit(f"{filename}[{idx}] open_window 必须是 JSON boolean。")
        open_window = open_window_raw
        if trigger_year > 0 and trigger_end_year <= 0 and not open_window:
            raise SystemExit(
                f"{filename}[{idx}] 历史锚定事件必须显式声明 trigger_end_year 或 open_window。"
            )
        if trigger_year > 0 and trigger_end_year > 0 and not open_window:
            start = (trigger_year, trigger_month or 1)
            end = (trigger_end_year, trigger_end_month or 12)
            if end < start:
                raise SystemExit(f"{filename}[{idx}] 事件窗口非法：最晚时点早于最早时点。")
        terminal_reason_labels = (
            string_list(item["terminal_reason_labels"], f"{filename}[{idx}].terminal_reason_labels")
            if "terminal_reason_labels" in item else []
        )
        gate_raw = item.get("trigger_gate") or {}
        if not isinstance(gate_raw, dict):
            raise SystemExit(f"{filename}[{idx}] trigger_gate 必须是对象（key→比较式）。")
        trigger_gate: Dict[str, str] = {}
        # key 形式见 issues._eval_gate_key：metric 名、region.<id>.<field>、army.<id>.<field>、
        # building.<id>.<field>、power.<id>.<field>、class.<name>[@<region>].<field>，
        # 多 id 用 | 分隔时末段 .<agg>(max/min/avg/sum)。
        # load 校验 key 形态(metric/表名/结构)+比较式形态(数值/文本相等)，fail-loud（#12 Q3）；
        # 字段名(列)是否存在由求值器运行期对 DB schema 兜底（load 无 DB）。
        for mk, mv in gate_raw.items():
            cond = str(mv).strip()
            cond_err = gate_cond_form_error(cond)
            if cond_err:
                raise SystemExit(f"{filename}[{idx}] trigger_gate['{mk}'] 比较式非法：{cond_err}。")
            # 文本相等 cond 须配文本可求值的 key（单 id region/army/power 三段）；否则 runtime
            # 静默永不达标（cmr r2 codex）。数值 cond 走通用 key 形态校验。
            key_err = (gate_text_key_form_error(str(mk)) if gate_cond_is_text(cond)
                       else gate_key_form_error(str(mk)))
            if key_err:
                raise SystemExit(f"{filename}[{idx}] trigger_gate key「{mk}」非法：{key_err}。")
            trigger_gate[str(mk)] = cond
        events.append(
            Event(
                id=str_field(item, "id", f"{filename}[{idx}]"),
                title=str_field(item, "title", f"{filename}[{idx}]"),
                kind=str_field(item, "kind", f"{filename}[{idx}]"),
                summary=str_field(item, "summary", f"{filename}[{idx}]"),
                urgency=int_field(item, "urgency", f"{filename}[{idx}]"),
                severity=int_field(item, "severity", f"{filename}[{idx}]"),
                credibility=int_field(item, "credibility", f"{filename}[{idx}]"),
                interests=string_list(item.get("interests"), f"{filename}[{idx}].interests"),
                audiences=string_list(item.get("audiences"), f"{filename}[{idx}].audiences"),
                resolve_condition=str(item.get("resolve_condition") or ""),
                fail_condition=str(item.get("fail_condition") or ""),
                trigger_year=trigger_year,
                trigger_month=trigger_month,
                trigger_end_year=trigger_end_year,

def _investigation_declaration(
    sel: Mapping[str, object] | None,
) -> Dict[str, object]:
    """#1896 4a 对查案密令的声明读口：查法/投入强度/所查事实/传话/知情反应。

    形状（ADR 0120 后出查案修订）——按人物当月真实办事声明，不读自由文本：
    - effort:   0..1 的**投入强度**（敷衍/停办 → 0）。只是"下了多大劲"，
                引擎另按承办人真实处境（能力/是否到差/未结差务带宽）折算本月实投。
                缺声明或不是数字 = **无效声明**（invalid），不是合法的零投入——
                明确停办只有一种写法：effort: 0。
    - fact_key: str，本月下手的罪证；人物没下手处就不给，代码不代选。
    - method:   查法（人物本月怎么查，原样落账）
    - tip_off:  {source} 真实通风报信：确有人经关系网把话递到被查者
    - spoliation: {effect, fact_key} 被查者知情后的毁证选择
    - suppression: {form} 被查者知情后的压案（行贿说项之类）声明

    奏报（memorial_text）不在此读口内：谎奏不造罪、不抹证（P6 实况/奏报分轨）。
    """
    item = sel if isinstance(sel, Mapping) else {}
    out: Dict[str, object] = {}
    raw_effort = item.get("effort", item.get("投入"))
    if raw_effort is None:
        out["invalid"] = "查案密令缺少 effort 声明（敷衍/停办请显式给 0）"
    else:
        intensity = _declared_intensity(raw_effort)
        if intensity is None:
            out["invalid"] = "查案密令的 effort 不是 0..1 的有限数字"
        else:
            out["intensity"] = intensity
    fact = str(item.get("fact_key", item.get("所查事实")) or "").strip()
    if fact:
        out["fact_key"] = fact
    raw_method = item["method"] if "method" in item else item.get("查法")
    if raw_method is not None and not isinstance(raw_method, (Mapping, list)):
        method = str(raw_method)
        if method != "":
            out["method"] = method
    tip = item.get("tip_off", item.get("通风报信"))
    if isinstance(tip, Mapping):
        source = str(tip.get("source", tip.get("递话人")) or "").strip()
        if source:
            out["tip_off"] = {"source": source}
    spoil = item.get("spoliation", item.get("毁证"))
    if isinstance(spoil, Mapping):
        effect = str(spoil.get("effect") or "harder").strip()
        if effect in ("harder", "gone"):
            out["spoliation"] = {
                "effect": effect,
                "fact_key": str(spoil.get("fact_key") or fact or "").strip(),
                "knowledge_source": str(
                    spoil.get("knowledge_source", spoil.get("知情来源")) or ""
                ),
            }
    suppress = item.get("suppression", item.get("压案"))
    if isinstance(suppress, Mapping):
        raw_form = suppress["form"] if "form" in suppress else suppress.get("方式")
        if raw_form is not None and not isinstance(raw_form, (Mapping, list)):
            form = str(raw_form)
            if form != "":
                out["suppression"] = {"form": form}
    return out

def coerce_covert_task_contract(raw: object) -> Optional[Dict[str, object]]:
    """Validate a frozen contract without rebuilding or supplying read-time defaults."""
    if not isinstance(raw, Mapping) or raw.get("version") != CONTRACT_VERSION:
        return None
    delivery = raw.get("delivery")
    if not isinstance(delivery, Mapping):
        return None
    if not str(raw.get("kind") or "").strip() or not normalize_axes(raw.get("axes")):
        return None
    if raw.get("direction") not in (-1, 1):
        return None
    inv_target = str(
        raw.get("investigation_target") or delivery.get("investigation_target") or ""
    ).strip()
    if inv_target:
        try:
            qty = float(delivery.get("target_units"))
        except (TypeError, ValueError):
            return None
        if qty <= 0.0:
            return None
        if delivery.get("effect_sign") not in (-1, 1):
            return None
        if list(delivery.get("canonical_fields") or []):
            return None
        if str(delivery.get("investigation_target") or "").strip() != inv_target:
            return None
        return copy.deepcopy(dict(raw))
    try:
        unit, target = canonicalize_delivery_unit(
            delivery.get("unit"), delivery.get("target_units"),
        )
    except CovertContractError:
        return None
    if delivery.get("effect_sign") not in (-1, 1):
        return None
    if list(delivery.get("canonical_fields") or []) != canonical_fields_for_delivery(unit=unit):
        return None
    if float(delivery.get("target_units")) != target:
        return None
    if any(
        not delivery.get(key)
        for key in _identity_keys_for_unit(
            str(unit),
            effect_sign=int(delivery.get("effect_sign") or 0),
            purpose=delivery.get("purpose"),
        )
    ):
        return None
    return copy.deepcopy(dict(raw))

def originated_quantity_this_turn(
    db: Any,
    dossier_id: int,
    turn: int,
    contract: Mapping[str, object],
) -> float:
    """当月 origin-linked canonical 效果的可数实物量（与合同 unit 同量纲）。"""
    did = int(dossier_id)
    current = int(turn)
    origin = f"dossier:{did}"
    delivery = contract.get("delivery") if isinstance(contract.get("delivery"), Mapping) else {}
    unit = str(delivery.get("unit") or "")
    fields = canonical_fields_for_delivery(unit=unit)
    qty = 0.0
    if "economy_moves" in fields:
        for item in db.list_economy_moves_for_dossier(did):
            if int(item.get("turn") or 0) != current:
                continue
            if not _delivery_matches_economy(item, delivery):
                continue
            try:
                qty += abs(float(item.get("delta") or 0))
            except (TypeError, ValueError):
                continue
    if "人物变更" in fields:
        action = str(delivery.get("person_action") or "").strip()
        rows = db.conn.execute(
            "SELECT id FROM person_logs WHERE origin_ref=? AND turn=? AND action=?",
            (origin, current, action),
        ).fetchall()
        qty += float(len(rows))
    if "region_delta" in fields:
        rows = db.conn.execute(
            "SELECT region_id, field, new_value, delta FROM region_logs "
            "WHERE origin_ref=? AND turn=?",
            (origin, current),
        ).fetchall()
        for row in rows:
            if _delivery_matches_region(row, delivery):
                qty += abs(float(row["delta"] or 0))
    return qty

def _normalize_directive_dossier_payload(
    self, payload: Dict[str, object], *, content=None, current_turn: int = 0,
) -> Dict[str, object]:
    """机械旨意的唯一结构边界；不完整载荷响亮拒绝。"""
    # #658：纯御笔强推不经 ordinary triad 归一（prepare/commit/ensure 共吃）。
    # text/actor 等会话字段须保留——pending payload 以它们为成案正文真源。
    if classify_directive_structured_kind(payload) == "push":
        push_id = imperial_push_target_dossier_id(payload)
        assert push_id is not None
        mode = self._normalize_dossier_mode(
            payload["mode"] if "mode" in payload else "ordinary"
        )
        out: Dict[str, object] = {
            "target_dossier_id": int(push_id), "mode": mode,
        }
        for key in ("text", "actor", "source_chat_turn_id"):
            if payload.get(key) not in (None, ""):
                out[key] = payload[key]
        return out
    normalized = dict(payload)
    normalized["mode"] = self._normalize_dossier_mode(
        normalized["mode"] if "mode" in normalized else "ordinary"
    )
    action = str(normalized.get("dossier_action_type") or "").strip()
    if action == "grant_allocation":
        grant_action = str(normalized.get("grant_action") or "").strip()
        if grant_action in {"加衔", "荫叙"}:
            normalized.pop("delta", None)
        elif self._is_army_pay_grant_payload(normalized):
            # #1503：协饷先且只经 require_explicit_xiexang_fields，不经 amount/account 首错。
            normalized = self._normalize_army_pay_grant_payload(normalized)
        else:
            from ming_sim.action_clusters import field_population_allowed
            from ming_sim.action_materialize import require_grant_allocation_shape
            purpose = str(normalized.get("purpose") or "").strip()
            if purpose and not field_population_allowed(
                "grant_allocation", "purpose", normalized,
            ):
                raise ValueError(f"非协饷拨帑不得夹带 purpose={purpose}")
            # #1716：amount/account 唯一验形；分类默认 grant_action=「无」时只借金钱动作过 shape，不回写。
            # 普通/legacy fallback（缺/空 grant_action）须显式非空 account，禁默认国库。
            shape_ga = grant_action if grant_action not in {"", "无"} else "赏赉"
            if grant_action in {"", "无"}:
                account_raw = normalized.get("account")
                if account_raw is None or not str(account_raw).strip():
                    raise ValueError("拨帑旨意缺少 account")
            shaped = require_grant_allocation_shape(
                grant_action=shape_ga,
                amount=normalized.get("amount"),
                account=normalized.get("account"),
            )
            normalized["amount"] = int(shaped["amount"])
            normalized["account"] = str(shaped["account"])
            surface = str(
                normalized.get("execution_surface") or "in_transit"
            ).strip()
            if surface not in {"immediate", "in_transit"}:
                raise ValueError("拨帑旨意 execution_surface 非法")
            normalized["execution_surface"] = surface
            normalized.pop("delta", None)
    elif action == "pay_order_override":
        # #653：结构化载荷 presence 在指令归一边界先验（键形/值域/幻影 region
        # 仍由成案点与物化点共 prepare_pay_order_entries 同一验形，不在此重复）。
        entries = normalized.get("entries")
        if not isinstance(entries, list) or not entries:
            raise ValueError("pay_order_override 旨意缺少 entries 结构化载荷")
    elif action in {
        "assignment", "authorization", "secret_authorization", "military_order",
    }:
        assignee = str(
            normalized.get("assignee_id")
            or normalized.get("assignee")
            or normalized.get("holder_id")
            or ""
        ).strip()
        if assignee and content is not None:
            from ming_sim.session import _find_existing_minister
            assignee = _find_existing_minister(content, assignee, self) or ""
        if not assignee and action in {"authorization", "secret_authorization"}:
            raise ValueError(f"{action} 旨意缺少 canonical assignee")

def _attach_commission_staging_fields(
    payload: Dict[str, Any], item: Mapping[str, object], *, turn: int,
) -> None:
    """透传既有 staging 字段：assignee / participant_roster / due_turn。

    字段可在交办顶层，或挂在 grant 对象内（与 stage_grant_allocation_candidate
    kwargs 同口径）。期限单源＝due_turn；deadline_months / end_turn 仅作换算输入。
    """
    grant = item.get("grant") if isinstance(item.get("grant"), Mapping) else {}
    lead = str(
        item.get("assignee")
        or item.get("assignee_id")
        or item.get("assignee_name")
        or (grant.get("assignee") if grant else "")
        or (grant.get("assignee_id") if grant else "")
        or ""
    ).strip()
    if lead:
        payload["assignee"] = lead
    roster = item.get("participant_roster")
    if not isinstance(roster, list) and grant:
        roster = grant.get("participant_roster")
    if isinstance(roster, list) and roster:
        payload["participant_roster"] = list(roster)
    elif lead and not isinstance(payload.get("participant_roster"), list):
        payload["participant_roster"] = [{
            "character_id": lead, "tier": "主办", "role": "", "delegator_id": None,
        }]
    due_src = item if item.get("due_turn") not in (None, "", 0) else grant
    end_src = item if item.get("end_turn") not in (None, "", 0) else grant
    months_src = (
        item if item.get("deadline_months") not in (None, "", 0) else grant
    )
    # 与 stage_assignment / stage_grant 同缝：相对月数或绝对回合 → 绝对 due_turn。
    absolute_due = _assignment_absolute_end_turn(
        int(turn),
        end_turn=(due_src or item).get("due_turn") or (end_src or item).get("end_turn") or 0,
        deadline_months=(months_src or item).get("deadline_months") or 0,
    )
    if absolute_due > int(turn):
        payload["due_turn"] = absolute_due

