def _extract_ref_ids(items: object, *, prefixes: Sequence[str]) -> Set[int]:
    """统一 walker：从 list[dict] 抽 issue/dossier 引用 id。

    认 key 集合 + target_id 前缀 + origin_ref/来源引用；禁纯数字 target_id 误吞为 dossier。
    信用写端（#628）与哭谏识别共此单源，禁平行复制。
    """
    out: Set[int] = set()
    if not isinstance(items, list):
        return out
    id_keys_by_prefix = {
        "issue": ("issue_id", "id", "commitment_ref"),
        "dossier": ("dossier_id", "revoke_target_dossier_id"),
    }
    keys: Set[str] = set()
    for p in prefixes:
        keys.update(id_keys_by_prefix.get(p, ()))
    for it in items:
        if not isinstance(it, dict):
            continue
        for key in keys:
            raw = it.get(key)
            if raw in (None, ""):
                continue
            # issue walker 的裸 id 可能与 dossier_id 键冲突时仅在对应 prefix 下启用
            if key in {"id"} and "issue" not in prefixes:
                continue
            try:
                out.add(int(raw))
            except (TypeError, ValueError):
                continue
        tid = str(it.get("target_id") or "").strip()
        for p in prefixes:
            if tid.startswith(f"{p}:"):
                try:
                    out.add(int(tid.split(":", 1)[1]))
                except (TypeError, ValueError):
                    pass
        for key in ("origin_ref", "来源引用"):
            ref = str(it.get(key) or "").strip()
            for p in prefixes:
                if p == "issue":
                    m = _ISSUE_REF_RE.match(ref)
                    if m:
                        out.add(int(m.group(1)))
                elif p == "dossier":
                    m = _DOSSIER_REF_RE.match(ref)
                    if m:
                        out.add(int(m.group(1)))
    return out

def assess_foundation_tier(db: Any, commitment_ref: int) -> str:
    """根基三档：禁完成度数值列；读已过段数（实结算）/ 已投入 / 实际进度定性 band。"""
    row = _issue_row(db, int(commitment_ref))
    if row is None:
        return FOUNDATION_JUST_STARTED
    stages = normalize_commitment_stages(
        row["stages_json"] if "stages_json" in row.keys() else None
    )
    n_stages = len(stages)
    bar = int(row["bar_value"] or 0)
    stages_passed = _stages_passed_from_records(db, int(commitment_ref), n_stages)
    spent_amount, _fiscal_count = _spent_amount_and_fiscal_count(db, row)

    band = ""
    did = parse_dossier_id(row["origin_ref"] if "origin_ref" in row.keys() else "")
    if did is not None:
        progress = db.list_dossier_progress(int(did))
        if progress:
            band = str(progress[-1].get("progress_band") or "")

    rooted_bands = {"告成", "已成", "生根", "完工", "就绪"}
    mid_bands = {"在办", "过半", "在途", "推进"}

    if band in rooted_bands or bar >= _BAR_ROOTED:
        return FOUNDATION_ROOTED
    if n_stages >= 2 and stages_passed >= n_stages:
        return FOUNDATION_ROOTED
    if (
        band in mid_bands
        or (_BAR_MID_LOW <= bar < _BAR_ROOTED)
        or (n_stages >= 2 and 0 < stages_passed < n_stages)
        or (spent_amount >= _SPENT_AMOUNT_HALFWAY and bar >= _BAR_MID_LOW)
    ):
        return FOUNDATION_HALFWAY
    return FOUNDATION_JUST_STARTED

def _codex_final_text(obj: object) -> str:
    if not isinstance(obj, dict):
        return ""
    typ = str(obj.get("type") or obj.get("event") or "")
    if "delta" in typ:
        return ""
    # 防御性兼容 codex `--json` 的 item.* 形态（如 {"type":"item.completed",
    # "item":{"type":"agent_message","text":"…"}}）：最终 agent message 可能嵌在 item.text
    # 里。只取 agent_message 类 item，忽略 reasoning/tool/plan item，避免把真实邸报当成空
    # 输出误判失败（codex correctness）。与下面的顶层 message/text 形态并存，互不影响。
    item = obj.get("item")
    if isinstance(item, dict):
        item_type = str(item.get("type") or "")
        if item_type in ("", "agent_message") or "message" in item_type:
            value = item.get("text") or item.get("content") or item.get("message")
            if isinstance(value, str) and value:
                return value
    for key in ("message", "content", "text", "final", "last_message"):
        value = obj.get(key)
        if isinstance(value, str) and value:
            return value
        if isinstance(value, dict):
            nested = value.get("content") or value.get("text") or value.get("message")
            if isinstance(nested, str) and nested:
                return nested
    return ""

def _participant_fields_from_draft_obj(obj: Mapping[str, Any]) -> Dict[str, Any]:
    """从抽取原包收承办人/参与人——拟旨意图=无时仍可后置点将（#1778）。"""
    out: Dict[str, Any] = {}
    if "承办人" in obj or "assignee" in obj or "assignee_name" in obj:
        out["assignee"] = str(
            obj.get("承办人") or obj.get("assignee") or obj.get("assignee_name") or ""
        ).strip()
    if "参与人" in obj:
        out["participant_roster"] = obj.get("参与人") if obj.get("参与人") is not None else []
    elif "participant_roster" in obj:
        out["participant_roster"] = obj.get("participant_roster")
    return out

def _secret_metadata_from_command(text: str) -> Tuple[List[str], int]:
    tags: List[str] = []
    deadline = 0
    for raw_line in (text or "").splitlines():
        line = raw_line.strip()
        if not line:
            continue
        m_tags = re.match(r"^(?:标签|tag|tags)\s*[：:]\s*(.+)$", line, flags=re.IGNORECASE)
        if m_tags:
            for item in re.split(r"[,，、/;；\s]+", m_tags.group(1)):
                cleaned = item.strip()
                if cleaned and cleaned not in tags:
                    tags.append(cleaned)
            continue
        m_deadline = re.match(r"^(?:期限|限期|deadline)\s*[：:]\s*(.+)$", line, flags=re.IGNORECASE)
        if m_deadline:
            match = re.search(r"([+-]?\d+)\s*(?:个)?月", m_deadline.group(1))
            if match:
                deadline = max(0, min(int(match.group(1)), 36))
    return tags, deadline

def project_draft_extract_to_directive_payload(
    captured: Mapping[str, Any],
    *,
    decree_text: str = "",
    existing_mode: object = None,
    db: Any = None,
    content: Any = None,
) -> Dict[str, object]:
    """把 extract_draft_intent 结果投影为 turn_directives.dossier_payload（与手工 capture 同形）。"""
    declared_mode = resolve_directive_mode(
        extracted=captured.get("mode"), existing=existing_mode,
    )
    if captured.get("draft_action") != "拟旨":
        return _manual_special_decree_payload(declared_mode)
    payload: Dict[str, object] = {
        "dossier_action_type": captured.get("dossier_action_type"),
        "target_kind": captured.get("target_kind"),
        "target_id": captured.get("target_id"),
        "mode": declared_mode,
    }
    for field in (
        "amount", "account", "execution_surface", "assignee",
        "deadline_months", "participant_roster", "locality_scope", "entries",
        "target_dossier_id", "affair_declaration",
        "grant_action", "purpose", "cadence",
        "region_id", "transaction_category",
    ):
        if captured.get(field) not in (None, ""):
            payload[field] = captured[field]
    if (
        payload.get("dossier_action_type") == "grant_allocation"
        and payload.get("grant_action") == "协饷"
    ):
        xiexang_kwargs = dict(
            amount=payload.get("amount"),
            account=str(payload.get("account") or ""),
            purpose=str(payload.get("purpose") or ""),
            target_kind=str(payload.get("target_kind") or ""),
            target_id=str(payload.get("target_id") or ""),
            cadence=str(payload.get("cadence") or ""),
        )
        if db is not None:
            from ming_sim.action_materialize import require_materializable_xiexang_payload
            material = require_materializable_xiexang_payload(
                db, text=str(decree_text or ""), **xiexang_kwargs,
            )
            payload.update({k: v for k, v in material.items() if k != "text"})
        else:
            from ming_sim.action_materialize import require_explicit_xiexang_fields
            payload.update(require_explicit_xiexang_fields(**xiexang_kwargs))
    if payload.get("dossier_action_type") == "dismiss_assignment":
        payload["name"] = str(payload.get("target_id") or "").strip()
        payload["_office_action"] = "罢免"
    from ming_sim.db import (
        classify_directive_structured_kind,
        imperial_push_target_dossier_id,
    )
    # #1849：互斥违规（push 与 triad 并存）此前先被 except 洗成 "ordinary" 再走
    # 组装，报出的可能已是别的字段错；禁临时改判，直接响亮上抛（同一 classify
    # 在下方组装后还会再判一次，掩盖只会让真因被别的字段错顶替）。
    pre_kind = classify_directive_structured_kind(payload)
    if pre_kind not in {"push", "empty"} and payload.get("target_kind") not in (None, ""):
        regions_content = getattr(content, "regions", None) if content is not None else None
        conn = getattr(db, "conn", None) if db is not None else None
        assembled = assemble_structured_decree(
            payload,
            conn=conn,
            regions_content=regions_content,
            validate=True,
        )
        apply_assembled_to_payload(payload, assembled)
    kind = classify_directive_structured_kind(payload)
    if kind == "push":
        push_id = imperial_push_target_dossier_id(payload)
        assert push_id is not None
        push_payload: Dict[str, object] = {
            "target_dossier_id": push_id,
            "mode": declared_mode,
        }
        declaration = captured.get("affair_declaration")

def _appointment_slice_from_combined_payload(
    payload: Dict[str, object],
) -> Optional[Dict[str, object]]:
    """从组合 directive 载荷抽出任免字段；无任免声明返 None。

    只保留任免成案所需键，剥离 grant 的 execution_surface / amount 等，
    避免 appointment 案卷撞「execution_surface 与案卷动作策略不符」。
    """
    action = str(payload.get("appoint_action") or "").strip()
    name = str(payload.get("name") or "").strip()
    if action not in {"任命", "罢免"} or not name:
        return None
    office = str(payload.get("office") or "").strip()
    if action == "任命" and not office:
        return None
    sliced: Dict[str, object] = {
        "name": name, "office": office, "appoint_action": action,
    }
    for key in (
        "appointment_tenure", "任别", "faction", "summon_after",
        "text", "affair_id", "region_id", "endorsements", "reason", "recommendation",
    ):
        value = payload.get(key)
        if value not in (None, ""):
            sliced[key] = value
    return sliced

def _stage_office(shared_text: str) -> Dict[str, Any]:
    from ming_sim.action_materialize import (
        _apply_existing_appointment_hit, _same_direction_office_hits,
    )
    from types import SimpleNamespace
    hits = _same_direction_office_hits(
        db, int(state.turn), name=str(appointment_fields["name"]),
        office=str(appointment_fields["office"]),
        action=str(appointment_fields["appoint_action"]),
        region_id=str(appointment_fields.get("region_id") or ""),
    )
    if len(hits) > 1:
        _reject(rejected, item, "同向任免候选不唯一", "invalid_state", source)
        return None
    if hits:
        oid = _apply_existing_appointment_hit(
            SimpleNamespace(db=db), hits[0],
            extracted_mode=appointment_fields.get("mode"),
            region_id=str(appointment_fields.get("region_id") or ""),
            minister_name=minister_name, turn=int(state.turn),
            annotate=True,
            recommendation_fields={
                key: payload[key]
                for key in ("reason", "recommendation", "faction")
                if payload.get("recommendation") and key in payload
            },
        )
        return {"id": oid, "kind": "office"}
    if appointment_fields["appoint_action"] == "任命":
        from ming_sim.session import _appointment_intent_is_current_office_noop
        if _appointment_intent_is_current_office_noop(
            db, appointment_fields["name"], appointment_fields["office"],
            content=getattr(db, "content", None),
        ):
            return None
    # office 成案链只吃任免字段；禁把 grant 的 execution_surface 等带进
    # appointment 案卷（会撞「execution_surface 与案卷动作策略不符」）。
    office_payload = dict(appointment_fields or {})
    office_payload["text"] = shared_text
    if "affair_declaration" in payload:
        office_payload["affair_declaration"] = payload["affair_declaration"]
    for key in ("reason", "recommendation", "faction", "replaces"):
        if key in payload:
            office_payload[key] = payload[key]
    oid = db.stage_pending_action(
        int(state.turn),
        "office",
        str(office_payload["appoint_action"]),
        minister_name,
        office_payload,
        source_chat_turn_id=source_chat_turn_id,
    )
    return {"id": oid, "payload": office_payload, "kind": "office"}

def _apply_dossier_participant_items(
    db: GameDB,
    state: GameState,
    extracted: Dict[str, object],
    *,
    items_key: str,
    authority_set: set,
    not_in_batch_msg: str,
) -> List[Dict[str, object]]:
    """Shared control flow for public/secret roster apply; fields stay separate.

    items_key / authority_set / not_in_batch_msg stay caller-owned — never union
    the two closed authority sets, never share a field-name or result slot.
    Missing authority is an empty closed set; never reconstruct from live DB.
    """
    results: List[Dict[str, object]] = []
    if not isinstance(authority_set, set):
        authority_set = set()
    for item in extracted.get(items_key) or []:
        if not isinstance(item, dict):
            results.append({
                "rejected": True, "category": "invalid_shape", "item": item,
            })
            continue
        try:
            dossier_id = _parse_sqlite_id(item.get("dossier_id"))
            if dossier_id not in authority_set:
                raise ValueError(not_in_batch_msg)
            character_id = str(item.get("character_id") or "").strip()
            delegator_id = str(item.get("delegator_id") or "").strip()
            tier = str(item.get("tier") or "").strip()
            if not character_id:
                raise ValueError("追加参与人物不能为空")
            if tier not in {"主办", "协办", "知情"}:
                raise ValueError("追加参与层级必须为主办/协办/知情")
            if not delegator_id:
                raise ValueError("追加参与人必须注明委派人")
            added = db.append_decree_dossier_participants(dossier_id, [{
                "character_id": character_id,
                "tier": tier,
                "role": str(item.get("role") or ""),
                "delegator_id": delegator_id,
            }], state=state, commit=False)
            if not added:
                # Exact durable duplicate is the only no-write success case.
                existing = db.get_decree_dossier(dossier_id) or {}
                if not any(
                    row.get("character_id") == character_id
                    and row.get("tier") == tier
                    and row.get("role") == str(item.get("role") or "")
                    and row.get("delegator_id") == delegator_id
                    for row in existing.get("participant_roster", [])
                ):
                    raise ValueError("参与人未实际加入案卷")
            persisted = added[0] if added else {
                "character_id": character_id, "tier": tier,
            }
            results.append({
                "dossier_id": dossier_id,
                "character_id": persisted["character_id"], "tier": persisted["tier"],
            })
        except (TypeError, ValueError, KeyError) as exc:
            results.append({
                "rejected": True, "category": "invalid_participant_roster",
                "reason": str(exc), "item": item,
            })
    return results

def create_chat_model(
    llm_config: LLMConfig,
    temperature: float = 0.7,
    enable_thinking: bool = False,
    thinking_budget: Optional[int] = None,
    top_p: Optional[float] = None,
    force_json_output: bool = False,
) -> OpenAIChat:
    install_token_stats_patch()
    reasoning_strength = (getattr(llm_config, "reasoning_strength", "") or "").strip().lower()
    extra_body = provider_extra_body(llm_config.base_url, llm_config.model)
    wants_thinking = enable_thinking or reasoning_strength in {"low", "medium", "high"}
    disables_thinking = reasoning_strength == "off"
    # #1797 v7 1b：DeepSeek 系统一关闭压过 reasoning_strength / enable_thinking，
    # 保留 provider_extra_body 的端点关闭键；非 DeepSeek 仍走既有强度语义。
    if not is_deepseek_model(llm_config.model):
        if is_dashscope_base_url(llm_config.base_url) and (wants_thinking or disables_thinking):
            # 推演/评估类 agent 需要深思,开 qwen thinking
            extra_body = {"enable_thinking": not disables_thinking}
            budget = _THINKING_BUDGET_BY_STRENGTH.get(reasoning_strength)
            if budget is not None:
                extra_body["thinking_budget"] = budget
            elif thinking_budget is not None and not disables_thinking:
                extra_body["thinking_budget"] = int(thinking_budget)
        elif is_minimax_base_url(llm_config.base_url) and (wants_thinking or disables_thinking):
            # 统一推理强度优先：off→disabled、低/中/高→adaptive。仅在没有统一强度（遗留
            # enable_thinking 路）时才看旧 thinking_level，否则遗留 thinking_level=disabled 会作
            # 隐藏旋钮把用户选的「中/高」压回 disabled（#358 cmr）。
            if disables_thinking:
                thinking_type = "disabled"
            elif reasoning_strength in {"low", "medium", "high"}:
                thinking_type = "adaptive"
            else:
                thinking_type = (llm_config.thinking_level or "adaptive").strip().lower()
                if thinking_type not in {"adaptive", "disabled"}:
                    thinking_type = "adaptive"
            extra_body = {"thinking": {"type": thinking_type}, "reasoning_split": True}
    # #1465：create_chat_model 默认仍 timeout_seconds / max_retries=1。
    # 已迁移接缝（召对流、run_agent_text）用 bind_transport_sdk_budget 临时覆盖
    # （timeout←attempt_timeout + max_retries=0）。
    # 禁止在 create_chat_model 全局套 transport（CLI runner 等未迁移路径）。
    kwargs: Dict[str, object] = {
        "id": llm_config.model,
        "api_key": llm_config.api_key,
        "base_url": llm_config.base_url,
        "temperature": temperature,
        "timeout": llm_config.timeout_seconds,
        "max_retries": 1,
        "role_map": {"system": "system", "user": "user", "assistant": "assistant", "tool": "tool"},
        "extra_body": extra_body,
    }
    # #1794：API 附加请求头表整张透传 default_headers；空表不塞键＝现状。
    # 不解析、不校验、不按 base_url/模型分派、不内置任何 provider 专用头。
    headers = llm_config.default_headers or {}
    if headers:
        kwargs["default_headers"] = dict(headers)
    # OpenAI 推理族（gpt-5*/o*）拒 top_p：luna 回 HTTP 400 空 assistant → agno
    # "Unknown model error" / 流式空回（#1452）。temperature 仍可传。
    if top_p is not None and not supports_openai_reasoning_effort(llm_config.model):
        kwargs["top_p"] = top_p
    if force_json_output:
        # qwen / OpenAI 兼容协议：强制输出标准 JSON 字符串
        # 走 extra_body 透传给 dashscope；prompt 里必须含 "json" 字样
        if extra_body is None:
            extra_body = {}
        extra_body["response_format"] = {"type": "json_object"}
        kwargs["extra_body"] = extra_body
    if supports_openai_reasoning_effort(llm_config.model):
        effort = _openai_reasoning_effort(
            llm_config.model, reasoning_strength, llm_config.thinking_level, enable_thinking
        )
        if effort:
            kwargs["reasoning_effort"] = effort
    # 探针：新配置用 channel 显式选择执行通道；未声明 channel 的旧路径暂沿用 env fallback。
    # CliChat 继承 OpenAIChat，吃同一套 kwargs；reasoning_effort 等 CLI 无关字段被忽略。
    from ming_sim.cli_backend import (
        CliChat,
        cli_backend_from_env,
        is_supported_cli_runner,
        supported_cli_runners_text,

def _is_gazette_public_event(item: dict) -> bool:
    """Turn-report gazette rows have their own directory carrier; exclude from 公开说法."""
    source_id = str(item.get("source_id") or "")
    return (
        source_id.startswith("projection:turn_report:")
        or (source_id.startswith("turn_report:") and source_id.endswith(":public"))
        or (source_id.startswith("turn_report:") and not source_id.endswith(":public"))
    )

def _resolve_unique_active_authority(
    db: Any,
    turn: int,
    *,
    authority_id: object = 0,
    holder_id: object = "",
    privilege: object = "",
) -> Optional[Dict[str, Any]]:
    """候选层：自然语言/结构字段唯一解析到现存在持 authority_records 行。

    0/多条 → None（不得发生产项）。显式 authority_id 优先。
    """
    holder = str(holder_id or "").strip()
    priv = str(privilege or "").strip()
    if priv in {"", "无"}:
        priv = ""
    try:
        aid = int(authority_id or 0)
    except (TypeError, ValueError):
        aid = 0
    if aid > 0:
        rec = db.get_authority(aid)
        if rec is None or bool(rec.get("revoked")):
            return None
        try:
            effective = int(rec.get("effective_turn") or 0)
        except (TypeError, ValueError):
            effective = 0
        if effective > int(turn):
            return None
        exp = rec.get("expires_turn")
        if exp not in (None, ""):
            try:
                if int(exp) < int(turn):
                    return None
            except (TypeError, ValueError):
                return None
        if holder and str(rec.get("holder_id") or "") != holder:
            return None
        if priv and str(rec.get("privilege") or "") != priv:
            return None
        return rec
    if not holder:
        return None
    matches = list(db.list_active_authorities(int(turn), holder_id=holder))
    if priv:
        matches = [
            m for m in matches if str(m.get("privilege") or "") == priv
        ]
    if len(matches) != 1:
        return None
    return matches[0]

def commitment_natural_due_turn(row: Any) -> int:
    """承诺自身 due：段表 max due，否则 end_turn；0=无到期上限。"""
    try:
        keys = row.keys()  # sqlite3.Row
    except Exception:
        keys = list(row.keys()) if isinstance(row, dict) else []
    stages_raw = row["stages_json"] if "stages_json" in keys else (
        row.get("stages_json") if isinstance(row, dict) else None
    )
    stages = normalize_commitment_stages(stages_raw)
    if stages:
        return max(int(s["due_turn"]) for s in stages)
    try:
        end_turn = int(row["end_turn"] if "end_turn" in keys else (
            row.get("end_turn") if isinstance(row, dict) else 0
        ) or 0)
    except (TypeError, ValueError):
        end_turn = 0
    return end_turn if end_turn > 0 else 0

def _apply_validated_roster_to_extract_result(
    result: Dict[str, Any], *, db: Any, content: Any,
) -> Dict[str, Any]:
    """对单条/批抽结果的 participant_roster 做 normalize+validate（就地拷贝）。"""
    out = dict(result)
    if "participant_roster" in out and out.get("participant_roster") is not None:
        out["participant_roster"] = normalize_draft_person_roster(
            out.get("participant_roster"), db=db, content=content,
        )
    drafts = out.get("drafts")
    if isinstance(drafts, list):
        healed_drafts: List[Any] = []
        for draft in drafts:
            if not isinstance(draft, dict):
                healed_drafts.append(draft)
                continue
            item = dict(draft)
            if "participant_roster" in item and item.get("participant_roster") is not None:
                item["participant_roster"] = normalize_draft_person_roster(
                    item.get("participant_roster"), db=db, content=content,
                )
            healed_drafts.append(item)
        out["drafts"] = healed_drafts
    return out

def _count_failed_person_slots(
    result: Dict[str, Any], *, db: Any, content: Any,
) -> int:
    """首抽整个结果的人物失败槽数（顶层 roster + 全 drafts；机构/泛称排除）。"""
    n = 0
    if "participant_roster" in result:
        n += _count_failed_person_slots_in_roster(
            result.get("participant_roster"), db=db, content=content,
        )
    for draft in result.get("drafts") or []:
        if isinstance(draft, dict) and "participant_roster" in draft:
            n += _count_failed_person_slots_in_roster(
                draft.get("participant_roster"), db=db, content=content,
            )
    return n

def _normalize_grant_transport(value: Mapping[str, Any]) -> Dict[str, Any]:
    transport = dict(value)
    # Draft transport historically used 目标ID and Chinese mode labels;
    # canonical FieldSpec validation happens only after those aliases normalize.
    if "target_id" not in transport and "目标" not in transport and "目标ID" in transport:
        transport["target_id"] = transport["目标ID"]
    raw_mode = transport.get("mode", transport.get("颁布方式"))
    if raw_mode not in (None, ""):
        transport["mode"] = _directive_mode(raw_mode) or raw_mode
    normalized = assert_action_candidate_shape({**transport, "kind": "grant_allocation"})
    projected = project_cluster_fields("grant_allocation", normalized)
    if projected.get("grant_action") != "协饷" and not projected.get("target_kind"):
        projected["target_kind"] = "policy"
    return projected

def _person_grounded_in_source(
    person_id: str,
    source_text: str,
    *,
    db: Any,
    content: Any,
    roster_forms: Optional[Dict[str, List[str]]] = None,
) -> bool:
    """窄确定性同人接地：原文出现该人规范名/别名，或可截断前缀且唯一落此人。

    禁散文关键词/第二套抽取语义；只做名册事实上的子串与前缀机械判定。
    """
    text = str(source_text or "")
    if not text:
        return False
    canon = _canon_person_id_key(person_id, db=db, content=content)
    if not canon:
        return False
    forms_index = roster_forms if roster_forms is not None else _all_roster_identity_forms(
        content=content,
    )
    my_forms = forms_index.get(canon) or _roster_identity_forms(canon, content=content)
    for form in my_forms:
        if form and form in text:
            return True
    # 可截断前缀：form 的真前缀（长≥2）出现在原文，且全名册仅此人的 form 命中该前缀
    for form in my_forms:
        if len(form) <= _MIN_PERSON_PREFIX_LEN:
            continue
        for n in range(_MIN_PERSON_PREFIX_LEN, len(form)):
            prefix = form[:n]
            if prefix not in text:
                continue
            owners: set[str] = set()
            for other_canon, other_forms in forms_index.items():
                for other in other_forms:
                    if other == prefix or other.startswith(prefix):
                        owners.add(other_canon)
                        break
            if owners == {canon}:
                return True
    return False

def _person_ids_from_extract_result(result: Dict[str, Any]) -> List[str]:
    """单条/批抽结果中的人物键（character_id + delegator_id/delegator，保序去重）。

    除名闸 prior/new 同键空间：委派人与主办/协办同属人物参与侧，漏收会把
    「毕自」→「毕自严」的委派人自愈误判 removal_only，或丢合法委派人不触发
    lost_prior_valid。raw `delegator` 与 `delegator_id` 同收（与 normalize 接缝一致）。
    """
    ids: List[str] = []

    def _absorb(roster: Any) -> None:
        if not isinstance(roster, list):
            return
        for item in roster:
            if not isinstance(item, dict):
                continue
            for key in ("character_id", "delegator_id", "delegator"):
                cid = str(item.get(key) or "").strip()
                if cid and cid not in ids:
                    ids.append(cid)

    if "participant_roster" in result:
        _absorb(result.get("participant_roster"))
    for draft in result.get("drafts") or []:
        if isinstance(draft, dict) and "participant_roster" in draft:
            _absorb(draft.get("participant_roster"))
    return ids

def _strip_trailing_comma(t: str, i: int, out: List[str], n: int) -> int:
    if t[i] == ",":
        k = i + 1
        while k < n and t[k] in " \t\r\n":
            k += 1
        if k < n and t[k] in "}]":
            return i + 1  # 丢弃结构尾逗号
    out.append(t[i])
    return i + 1

def _normalize_settle_meta_defaults(
    fiscal_raw: Dict[str, object],
    settle_meta_defaults: Dict[str, object],
    ctx: str,
) -> Dict[str, object]:
    fiscal = dict(fiscal_raw)
    settle_raw = fiscal.get("settle")
    if not isinstance(settle_raw, dict):
        return fiscal

    meta_raw = settle_raw.get("_meta", {})
    if meta_raw is None:
        meta_raw = {}
    if not isinstance(meta_raw, dict):
        raise SystemExit(f"{ctx}.fiscal.settle._meta 必须是 JSON 对象。")

    if "_meta_defaults" not in settle_raw:
        if settle_raw.get("_meta") is None and "_meta" in settle_raw:
            settle = dict(settle_raw)
            settle["_meta"] = {}
            fiscal["settle"] = settle
        return fiscal

    default_name = settle_raw.get("_meta_defaults")
    if not isinstance(default_name, str) or not default_name.strip():
        raise SystemExit(f"{ctx}.fiscal.settle._meta_defaults 必须是非空字符串。")
    default_key = default_name.strip()
    if default_key not in settle_meta_defaults:
        raise SystemExit(f"{ctx}.fiscal.settle._meta_defaults 指向未知默认组：{default_name}。")
    defaults_raw = settle_meta_defaults[default_key]
    if not isinstance(defaults_raw, dict):
        raise SystemExit(f"content/regions.json.settle_meta_defaults.{default_key} 必须是 JSON 对象。")

    settle = dict(settle_raw)
    settle["_meta"] = _deep_merge_content_defaults(defaults_raw, meta_raw)
    settle.pop("_meta_defaults", None)
    fiscal["settle"] = settle
    return fiscal

def gate_cond_is_text(cond: str) -> bool:
    """cond 是否文本比较（==/!= 非数字 RHS，或 in=a|b）——与 runtime _gate_passed 文本分支同判。"""
    sm = re.match(r"^(==|!=|in=)\s*(.+)$", cond.strip())
    return bool(sm and (sm.group(1) == "in=" or not re.match(r"^-?\d+$", sm.group(2).strip())))

