def _authorization_privilege(raw: object) -> str:
    """公开委任默认 privilege=便宜行事；显式四闭集权项原样保留。"""
    from ming_sim.authority_privileges import AUTHORITY_PRIVILEGE_SET

    priv = str(raw or "").strip()
    if priv in {"", "无"}:
        return "便宜行事"
    if priv in AUTHORITY_PRIVILEGE_SET:
        return priv
    return ""

def strip_json_fence(text: str) -> str:
    match = re.search(r"```(?:json)?\s*(.*?)```", text, re.S)
    if match:
        return match.group(1).strip()
    return text.strip()

def recognize_audience_command(message: str) -> str:
    """收夜/留侍口令结构化判词（#526）。

    确定性封闭集（COURT_BREAK / AMBIGUOUS_CLOSE / STAY_ATTEND）；引擎不重解析散文。
    不进 ACTION_CLUSTERS；非第二 parser（无自由散文正则启发）。
    无耗时软判——同步直调即可；坏 shape 由 normalize 归一，不在此宽吞异常。
    """
    from ming_sim.constants import (
        AMBIGUOUS_CLOSE_COMMANDS,
        COURT_BREAK_COMMANDS,
        STAY_ATTEND_COMMANDS,
    )

    text = str(message or "").strip()
    if not text:
        return CMD_NONE
    lowered = text.lower()
    if text in STAY_ATTEND_COMMANDS or lowered in STAY_ATTEND_COMMANDS:
        return CMD_STAY_ATTEND
    if lowered in COURT_BREAK_COMMANDS or text in COURT_BREAK_COMMANDS:
        return CMD_CLOSE_NIGHT
    if text in AMBIGUOUS_CLOSE_COMMANDS or lowered in AMBIGUOUS_CLOSE_COMMANDS:
        return CMD_AMBIGUOUS_CLOSE
    return CMD_NONE

def normalize_audience_declaration(raw: object) -> Dict[str, object]:
    """转译 JSON → C0 声明形状；未知顶层键原样保留，交既有分派器 durable 拒收。

    不得在 normalize 静默删键——未知 section 的 ``invalid_shape`` 留痕是
    ``declaration_dispatch._record_unknown_sections`` 的唯一职责（ADR 0015）。
    """
    empty: Dict[str, object] = {k: [] for k in _ARRAY_SECTIONS}
    if not isinstance(raw, Mapping):
        return empty
    declaration: Dict[str, object] = {}
    for key in _DECLARATION_KEYS:
        if key not in raw:
            if key in _ARRAY_SECTIONS:
                declaration[key] = []
            elif key == "effects":
                declaration[key] = {}
            continue
        value = raw.get(key)
        if key == "effects":
            declaration[key] = {} if value is None else value
            continue
        if key == "protagonist":
            if value is None:
                continue
            declaration[key] = value
            continue
        if value is None:
            declaration[key] = []
        else:
            declaration[key] = value
    # 未知顶层键原样过手，供分派器逐项 invalid_shape；不在此过滤。
    for key, value in raw.items():
        sk = str(key)
        if sk in _DECLARATION_KEYS:
            continue
        declaration[sk] = value
    return declaration

def _merge_plea_kind_into_todo(
    db: Any,
    todo: Dict[str, object],
    *,
    breach_kind: str,
    reason: str,
    target_dossier_id: int,
    extra: Optional[Dict[str, object]],
) -> int:
    """同回合第二类松手：显式并入既有 pending，log+meta 记全被吞类。"""
    meta = decode_plea_meta(todo.get("origin_context"))
    primary = str(meta.get("breach_kind") or "")
    absorbed = meta.get("absorbed_breach_kinds")
    if not isinstance(absorbed, list):
        absorbed = []
    absorbed_list = [str(x) for x in absorbed if str(x or "").strip()]
    kind = str(breach_kind or "").strip()
    if kind and kind != primary and kind not in absorbed_list:
        absorbed_list.append(kind)
        logger.info(
            "breach_plea merge: commitment=%s turn_todo=%s primary=%s absorbed+=%s",
            todo.get("commitment_ref"), todo.get("id"), primary, kind,
        )
    meta["absorbed_breach_kinds"] = absorbed_list
    # 保留首类 primary；补充理由/案卷
    if reason and not str(meta.get("reason") or "").strip():
        meta["reason"] = str(reason)
    elif reason:
        prev = str(meta.get("reason") or "")
        add = str(reason)
        if add and add not in prev:
            meta["reason"] = f"{prev}；{add}"
    if int(target_dossier_id or 0) > 0 and int(meta.get("target_dossier_id") or 0) <= 0:
        meta["target_dossier_id"] = int(target_dossier_id)
    if extra:
        for k, v in extra.items():
            if k not in meta:
                meta[k] = v
    encoded = encode_plea_meta(meta)
    db.conn.execute(
        "UPDATE next_audience_todos SET origin_context=? WHERE id=?",
        (encoded, int(todo["id"])),
    )
    # criterion 保持首类标签；多类痕迹在 meta
    return int(todo["id"])

def _cli_stream_safe_prefix(text: str) -> tuple[str, str]:
    """Release text that cannot belong to a trailing recommendation envelope."""
    marker_at = text.rfind(_CLI_RECOMMENDATION_PREFIX)
    if marker_at >= 0:
        return text[:marker_at], text[marker_at:]
    keep = 0
    for length in range(1, min(len(text), len(_CLI_RECOMMENDATION_PREFIX) - 1) + 1):
        if text.endswith(_CLI_RECOMMENDATION_PREFIX[:length]):
            keep = length
    return (text[:-keep], text[-keep:]) if keep else (text, "")

def _ground_relative_pay_order_deadlines(result: Dict[str, Any], db: Any) -> Dict[str, Any]:
    """在既有抽取适配缝把结构化相对月数落成 active-through 绝对 turn。"""
    row = db.conn.execute("SELECT turn FROM game_state WHERE id=1").fetchone()
    if row is None:
        return result
    current_turn = int(row["turn"])
    drafts = result.get("drafts")
    items = drafts if isinstance(drafts, list) else [result]
    for item in items:
        if not isinstance(item, dict) or item.get("dossier_action_type") != "pay_order_override":
            continue
        for entry in item.get("entries") or []:
            if not isinstance(entry, dict):
                continue
            if "duration_months" in entry:
                duration = entry.pop("duration_months")
                if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
                    raise ValueError(f"override 相对期限 duration_months 须为正整数：{duration!r}")
                entry["until_turn"] = current_turn + duration - 1
            elif "until_turn" in entry and (
                isinstance(entry["until_turn"], bool)
                or not isinstance(entry["until_turn"], int)
                or entry["until_turn"] < current_turn
            ):
                raise ValueError(f"override until_turn 已过期或无效：{entry['until_turn']!r}")
    return result

def _loads_lenient(
    raw: str, *, accepted_types: tuple[type, ...] = (dict,),
) -> Optional[Any]:
    """容错解析 JSON：剥代码围栏并截取首个受理容器。失败返回 None。"""
    t = (raw or "").strip()
    if t.startswith("```"):
        t = re.sub(r"^```[a-zA-Z]*\s*", "", t)
        t = re.sub(r"\s*```$", "", t).strip()
    starts = []
    if dict in accepted_types:
        starts.append((t.find("{"), "}"))
    if list in accepted_types:
        starts.append((t.find("["), "]"))
    starts = [(index, closer) for index, closer in starts if index >= 0]
    if not starts:
        return None
    i, closer = min(starts, key=lambda item: item[0])
    j = t.rfind(closer)
    if j <= i:
        return None
    body = t[i:j + 1]
    try:
        obj = json.loads(body)
    except (ValueError, TypeError):
        # 严格解析失败才做 JSONC 容错（CMR F8）：模型照 prompt 模板回带 // 行注释或尾逗号时救回。
        # 先严格、失败才清洗 —— 合法 JSON 不经清洗器。清洗器 quote-aware：串值里的 //、,}、://
        # 一律不动（#6，旧裸正则会误伤 "x,}"→"x}"、"a//b"→截断）。
        try:
            obj = json.loads(_strip_jsonc(body))
        except (ValueError, TypeError):
            return None
    return obj if isinstance(obj, accepted_types) else None

def _seed_guilt_severity(db: Any, target: str) -> str:
    row = db.conn.execute(
        "SELECT seed_guilt FROM characters WHERE name=?",
        (str(target),),
    ).fetchone()
    if row is None:
        return ""
    raw = row["seed_guilt"]
    if isinstance(raw, Mapping):
        return str(raw.get("severity") or "").strip()
    text = str(raw or "").strip()
    if not text:
        return ""
    try:
        parsed = json.loads(text)
    except (TypeError, ValueError):
        return ""
    if isinstance(parsed, Mapping):
        return str(parsed.get("severity") or "").strip()
    return ""

def apply_monthly_covert_actual_progress(
    db: Any,
    state: Any,
    *,
    selections: object = None,
    commit: bool = False,
    only_supplied: bool = False,
) -> List[Dict[str, object]]:
    """当月实况轨落笔：推演者声明的真实投入/效果 → dossier_actual_progress。

    不发明人物/钱粮/地区固定套餐；奏报永不入 apply。
    ``only_supplied``：过月分段只落本段交代的执行态，不把其余未提及的在办密令误判为缺执行态。

    #1896：查案密令改走逐证核算——4a 声明的 effort 记到指定事实，累计到该证难度
    才记已掌握；不再由执行态折固定增量、满统一阈自动坐实。执行态枚举对查案
    不再是必填（#1895 同批废旧查案的意愿底档），缺省只落事实投入。
    """
    orders = list(db.list_secret_orders(status="active"))
    by_sel = _selection_map(selections)
    applied: List[Dict[str, object]] = []
    turn = int(state.turn)
    for order in orders:
        oid = int(order["id"])
        if _is_issuance_turn(order, turn):
            continue
        if only_supplied and oid not in by_sel:
            continue
        minister = str(order.get("minister_name") or "")
        if not minister_eligible_for_monthly_covert(db, minister):
            applied.append({
                "order_id": oid,
                "skipped": True,
                "reason": "承办人不在场或非 active",
            })
            continue
        dossier = db.get_dossier_for_secret_order(oid)
        if dossier is None:
            applied.append({
                "order_id": oid, "rejected": True, "reason": "密令缺少案卷",
            })
            continue
        if str(dossier.get("status") or "") == "closed":
