def is_stream_activity_event(event: Any) -> bool:
    """空转活动唯一权威（召对 web 流 / run_agent_text 同用；禁平行分叉）。

    活动：RunContent 有正文、reasoning 增量、工具生命周期、终包到达。
    终包计入活动：本 attempt 已完成产出，不得在 RunOutput/RunCompleted 边界空转误杀。
    活动 ≠ 已呈现正文；不据此禁止重试。
    """
    name = type(event).__name__
    if name in ("RunOutput", "RunCompletedEvent"):
        return True
    if getattr(event, "event", "") == "RunContent" and getattr(event, "content", None):
        return True
    rdelta = getattr(event, "reasoning_content", None)
    if isinstance(rdelta, str) and bool(rdelta):
        return True
    return name in (
        "ToolCallStartedEvent",
        "ToolCallCompletedEvent",
    )

def _character_gazette_rows(public_events: Sequence[dict]) -> list[dict[str, object]]:
    """Person gazette rows come only from that person's typed public projection.

    Raw ``turn_reports`` aggregates are not an authorization boundary (#883 / #1832).
    """
    rows: list[dict[str, object]] = []
    for item in public_events or []:
        source_id = str(item.get("source_id") or "")
        if not (
            source_id.startswith("projection:turn_report:")
            or (source_id.startswith("turn_report:") and source_id.endswith(":public"))
        ):
            continue
        body = str(item.get("body") or "")
        if not body.strip():
            continue
        rows.append({
            "year": int(item.get("year") or 0),
            "period": int(item.get("period") or 0),
            "turn": int(item.get("turn") or 0),
            "body": body,
        })
    return rows

def project_execution_liability_parties(
    roster: object,
) -> List[Dict[str, object]]:
    """#565 连坐责任投影：主办→primary；主办/协办行 delegator_id 一级→secondary。

    同构 breach_decree_dossier 双处收集：协办本人零机械只作戏源，
    但其委派人仍次责（ADR 0053：大臣遣学生为协办办砸→全权者背锅）。
    先定档后去重：同一人 primary 胜 secondary；知情永不入。
    写路与 list_execution_liability_parties 共用本函数，禁止第二份 roster 遍历。
    """
    if not isinstance(roster, list):
        return []

    primary_ids: List[str] = []
    seen_primary: set[str] = set()
    for item in roster:
        if not isinstance(item, dict) or item.get("tier") != "主办":
            continue
        lead = str(item.get("character_id") or "").strip()
        if lead and lead not in seen_primary:
            seen_primary.add(lead)
            primary_ids.append(lead)

    secondary_ids: List[str] = []
    seen_secondary: set[str] = set()
    for item in roster:
        if not isinstance(item, dict) or item.get("tier") not in {"主办", "协办"}:
            continue
        delegator = str(item.get("delegator_id") or "").strip()
        if (
            delegator
            and delegator not in seen_primary
            and delegator not in seen_secondary
        ):
            seen_secondary.add(delegator)
            secondary_ids.append(delegator)

    parties: List[Dict[str, object]] = [
        {
            "character_id": lead,
            "responsibility": "primary",
            "tier": "主办",
        }
        for lead in primary_ids
    ]
    parties.extend(
        {
            "character_id": delegator,
            "responsibility": "secondary",
            "tier": "delegator",
        }
        for delegator in secondary_ids
    )
    return parties

def format_army_changes(changes: List[Dict[str, object]]) -> str:
    # 拒收项(ADR 0008 决定 1)与 applied 项同列，但不是盘面变化，先滤掉。
    changes = [c for c in (changes or []) if not (isinstance(c, dict) and c.get("rejected"))]
    if not changes:
        return f"本{TURN_UNIT}未见明确军队盘面变化。"
    parts = []
    for change in changes:
        delta = change["delta"]
        field = str(change["field"])
        if delta is None:
            parts.append(f"{change['army']}{change['label']}改为{change['new']}（{change['reason']}）")
        elif field == "manpower":
            sign = "+" if int(delta) > 0 else ""
            parts.append(f"{change['army']}{change['label']}{sign}{int(delta)}人（{change['reason']}）")
        else:
            sign = "+" if int(delta) > 0 else ""
            parts.append(f"{change['army']}{change['label']}{sign}{int(delta)}（{change['reason']}）")
    return "；".join(parts) + "。"

def apply_assembled_to_payload(
    payload: MutableMapping[str, object],
    assembled: Mapping[str, object],
) -> None:
    """把 assemble 结果写回 directive/rescript payload 核心字段。"""
    for key in _CORE_KEYS:
        if key not in assembled:
            payload.pop(key, None)
            continue
        val = assembled[key]
        if val in (None, ""):
            payload.pop(key, None)
        else:
            payload[key] = val

def main() -> int:
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s %(levelname)s %(name)s: %(message)s",
    )
    args = _args()
    content = GameContent.load()
    bind_content(content)
    bind_issue_content(content)
    bind_agent_content(content)
    cfg = _config(args)
    trace_path = require_fresh_cli_trace(cfg)

    with tempfile.TemporaryDirectory(prefix="ming-570-accept-") as tmp:
        workers = min(4, args.samples)
        with ThreadPoolExecutor(max_workers=workers) as executor:
            futures = [
                executor.submit(_run_sample, i, tmp, content, cfg)
                for i in range(args.samples)
            ]
            samples = sorted(
                (future.result() for future in as_completed(futures)),
                key=lambda row: row["sample"],
            )

    if trace_path is not None:
        trace_records = [
            json.loads(line)
            for line in trace_path.read_text(encoding="utf-8").splitlines()
            if line.strip()
        ]
        # 首月结算中的其他模型调用也可能留下 TRACE，不要求总条数等于样本数。
        # 仍钉：全部无 error；颁布判官每 sample 恰 1 条。
        errored = [r for r in trace_records if r.get("error") is not None]
        if errored:
            raise RuntimeError(
                f"raw trace has {len(errored)} error record(s) "
                f"(total={len(trace_records)})"
            )
        judge_traces = [
            r for r in trace_records
            if "颁布判官" in str(r.get("prompt") or "")
            or str(r.get("tag") or "") in {"promulgation-judge", "promulgation_judge"}
        ]
        if len(judge_traces) != args.samples:
            raise RuntimeError(
                f"expected {args.samples} promulgation-judge trace(s); "
                f"got {len(judge_traces)} (total traces={len(trace_records)})"
            )
    else:
        trace_records = []

    # Aggregate checks: every sample must pass every check.
    check_names = sorted(samples[0]["checks"])
    aggregate = {
        name: all(bool(s["checks"][name]) for s in samples)
        for name in check_names
    }
    failed = [name for name, ok in aggregate.items() if not ok]
    artifact = {
        "gate": "issue-570-family-tail-acceptance-anchors",
        "method": {
            "design": (
                "Live production promulgation Judge on isolated DBs; "
                "P-3 structured-field anchors for 破格授阁臣 / 白身破格授巡抚 / 中旨强授; "
                "force three-cost legs assert signed direction×intensity; "
                "P4: live 邸报/密奏/召对 "
                "captured as evidence only — no LLM-output regex P4 gate."
            ),
            "samples": args.samples,
            "config": gate_evidence_config(args, cfg),
            "assertion_targets": {
                "cabinet": (
                    "rejected ∧ blocked_layer∈cabinet_drafting|palace_rescript|six_offices "
                    "∨ execution_outcome∈{degraded,failed}"
                ),
                "bare_body": (
                    "rejected ∧ (force attempted → authority-5 + signed satisfaction "
                    "direction×intensity exact match + midzhi stigma; zero reaction ∉ list)"
                ),

  let event = "message";
  const dataLines: string[] = [];
  for (const line of lines) {
    if (line.startsWith("event:")) {
      event = line.slice(6).trim();
    } else if (line.startsWith("data:")) {
      dataLines.push(line.slice(5).trimStart());
    }
  }
  if (!dataLines.length) return null;
  return { event, data: dataLines.join("\n") };
};

def _field_raw(obj: Mapping[str, Any], spec: FieldSpec) -> Any:
    if spec.name in obj:
        return obj.get(spec.name)
    if spec.zh in obj:
        return obj.get(spec.zh)
    return None

def _render_field_specs(
    specs: Sequence[Tuple[str, FieldSpec]],
) -> Tuple[List[str], List[str]]:
    """Render transport examples and action-scoped constraints from catalog rows."""
    lines: List[str] = []
    notes: List[str] = []
    seen_zh: set = set()
    for action, spec in specs:
        prefix = f"{action}·" if action else ""
        if spec.allowed is not None:
            values = sorted(spec.allowed, key=lambda value: (value != "无", value))
            example = f'"{"|".join(values)}"'
        elif spec.as_int:
            example = "null" if spec.default is None else "0"
            if spec.int_lo > 0 or spec.quantity_unit:
                constraint = (
                    f"可null；命中 JSON integer>={spec.int_lo}；禁数字字符串"
                    if spec.default is None
                    else f"JSON integer>={spec.int_lo}"
                )
                if spec.quantity_unit:
                    constraint += f"；单位={spec.quantity_unit}"
                notes.append(f"{prefix}{spec.zh}：{constraint}")
        else:
            example = '""'
        if spec.zh not in seen_zh:
            seen_zh.add(spec.zh)
            lines.append(f'  "{spec.zh}": {example},')
        if spec.populated_when is not None:
            controller_name, controller_values = spec.populated_when
            controller = _field_specs()[controller_name]
            values = "|".join(sorted(controller_values))
            notes.append(
                f"{prefix}{spec.zh}：仅{controller.zh}={values}时填写；其它留空"
            )
    return lines, notes

def parse_responsible_bodies(raw: object) -> List[str]:
    """下议 responsible_bodies 唯一解析（暂存/admission/判后共用）。

    承 list/tuple，或 JSON 数组串，或「吏部、户部」类分隔串；空/不可用 → []。
    不在此做人物档语义；机关/职司个人名策略见 assert_responsible_bodies_org_only。
    """
    value = _parse_json_field(raw)
    if value is None:
        return []
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return []
        parts = [p.strip() for p in re_split_bodies(text) if p.strip()]
        out: List[str] = []
        for name in parts:
            if name not in out:
                out.append(name)
        return out
    if not isinstance(value, (list, tuple)):
        return []
    out = []
    for item in value:
        name = str(item or "").strip()
        if name and name not in out:
            out.append(name)
    return out

def require_explicit_xiexang_fields(
    *,
    amount: object = 0,
    account: str = "",
    purpose: str = "",
    target_kind: str = "",
    target_id: str = "",
    cadence: str = "",
) -> Dict[str, Any]:
    """#1503 单一权威接缝：严格验形并归一 typed 字段。"""
    from ming_sim.strict_types import strict_int

    facts: list = []

    def _note(field: str, *, current: object, expected: object) -> None:
        facts.append({"field": field, "current": current, "expected": expected})

    try:
        n = strict_int(amount, accept_numeric_strings=False)
    except ValueError:
        n = 0
    if n <= 0:
        _note("amount", current=amount, expected={"type": "positive_int"})
    # #1620：太仓→国库唯一权威 resolve_grant_account；此处不再平行 if。
    canonical_account = resolve_grant_account(grant_action="协饷", account=account)
    if canonical_account not in {"国库", "内库"}:
        _note("account", current=account, expected=["国库", "内库"])
    purpose_cur = str(purpose or "").strip()
    if purpose_cur != "补饷":
        _note("purpose", current=purpose_cur or purpose, expected="补饷")
    canonical_target_kind = str(target_kind or "").strip()
    if canonical_target_kind not in XIEXIANG_TARGET_KINDS:
        _note(
            "target_kind",
            current=canonical_target_kind or target_kind,
            expected=sorted(XIEXIANG_TARGET_KINDS),
        )
    target_id_cur = str(target_id or "").strip()
    if not target_id_cur:
        _note("target_id", current=target_id, expected={"nonempty_str": True})
    cadence_value = str(cadence or "").strip()
    if cadence_value and cadence_value not in {"一次性", "每月"}:
        _note(
            "cadence",
            current=cadence_value,
            expected=["一次性", "每月", ""],
        )
    if facts:
        raise IncompleteXiexangPayloadError(field_failures=facts)
    return {
        "amount": n,
        "account": canonical_account,
        "purpose": "补饷",
        "target_kind": canonical_target_kind,
        "target_id": target_id_cur,
    }

