def night_archive_metadata(
    ledgers: List[Dict[str, Any]], turns: List[Dict[str, Any]],
) -> Dict[str, Any]:
    """Purely derive archive labels from already-loaded durable-store rows."""
    summon_methods = [
        method
        for entry in ledgers if _is_command_entry(entry)
        for method in SUMMON_METHODS if method in (entry.get("tags") or [])
    ]
    # #1331/#1339：involved_people 投影缝复用 raw 非人判定（DRY 单真源）；
    # 禁 canon 后再滤（司礼监→王承恩）。写入侧 ledger 保留原文，投影侧只列真人。
    people: List[str] = []
    candidate_groups = [entry.get("person_names") or [] for entry in ledgers]
    candidate_groups.extend([turn.get("minister_name")] for turn in turns)
    for names in candidate_groups:
        for raw_name in names:
            name = str(raw_name or "").strip()
            if not name or name in people:
                continue
            if is_non_person_participant_name(name):
                continue
            people.append(name)
    summon_method = summon_methods[0] if summon_methods else ""
    return {
        # Summon methods remain machine tags; the container contract exposes the
        # player-facing audience type from this single production source.
        "audience_type": "越次召对" if summon_method == METHOD_YUECI else "召对",
        "involved_people": people,
    }

def person_night_experience(
    db: Any, night_id: int, person_name: str,
) -> List[Dict[str, Any]]:
    """人物经历：在场公开所闻，加本人说出的私密条目。

    只有大臣／近臣分段的首位人名是说话人；场景分段仅列涉及人。
    """
    name = str(person_name or "").strip()
    if not name:
        return []
    audible_ids = {entry["id"] for entry in audible_entries_for(db, int(night_id), name)}
    return [
        entry for entry in list_ledger(db, int(night_id))
        if entry["id"] in audible_ids
        or (entry.get("audibility") == AUDIBILITY_PRIVATE
            and any(tag in {"scroll_role:minister", "scroll_role:attendant"}
                    for tag in entry.get("tags", []))
            and (entry.get("person_names") or [None])[0] == name)
    ]

def build_night_said_so_far(
    db: Any, night_id: int, *, until_chat_turn_id: int = 0,
) -> List[str]:
    """本场已说的话：按夜持久化对话轮 + 故事账，正文从 chat_messages 取。

    chat_turns 只有 user_message_id / minister_message_id，没有 user_text 列；
    与 materials._scene_spoken_text / read_night_scroll 同口径，不另造假键。

    ``until_chat_turn_id``（ADR 0155）：按源轮 night_seq/id 截止——只含严格早于
    该轮的已说；本轮正文只走【本轮皇帝】【本轮回话】，不在此重复；亦不读后续
    已持久化轮（下一句不等转译时可能已落库）。
    """
    if int(night_id or 0) <= 0 or not hasattr(db, "conn"):
        return []
    from ming_sim.audience_night import list_chat_turns_for_night, list_ledger

    cutoff_id = int(until_chat_turn_id or 0)
    cutoff_seq: Optional[int] = None
    if cutoff_id > 0:
        crow = db.conn.execute(
            "SELECT night_seq FROM chat_turns WHERE id=?", (cutoff_id,),
        ).fetchone()
        if crow is not None:
            cutoff_seq = int(crow["night_seq"] or 0)

    def _before_cutoff(seq: int, turn_id: int) -> bool:
        if cutoff_id <= 0 or cutoff_seq is None:
            return True
        if int(seq) < int(cutoff_seq):
            return True
        if int(seq) > int(cutoff_seq):
            return False
        return int(turn_id) < int(cutoff_id)

    lines: List[str] = []
    # 故事账（入殿等）按夜序；对话轮按 night_seq。两者分列后按既有材料口径
    # 先对话再穿插非必要——转译只要「已说」截止集，顺序以对话轮为主、账文附后。
    prior_turn_ids: set[int] = set()
    for turn in list_chat_turns_for_night(db, int(night_id)):
        tid = int(turn.get("id") or 0)
        tseq = int(turn.get("night_seq") or 0)
        if not _before_cutoff(tseq, tid):
            continue
        if tid > 0:
            prior_turn_ids.add(tid)
        minister = str(turn.get("minister_name") or "").strip() or "殿上"
        for mid, role_label in (
            (turn.get("user_message_id"), "皇帝"),
            (turn.get("minister_message_id"), minister),
        ):
            if not mid:
                continue
            row = db.conn.execute(
                "SELECT content FROM chat_messages WHERE id=?", (int(mid),),
            ).fetchone()
            if row is None:
                continue
            body = str(row["content"] or "")
            if not body.strip():
                continue
            lines.append(f"[chat_turn_id={tid}] {role_label}：{body}")
    for entry in list_ledger(db, int(night_id)):
        src = int(entry.get("source_chat_turn_id") or 0)
        origin = int(entry.get("origin_chat_turn_id") or 0)
        if cutoff_id > 0 and cutoff_seq is not None:
            # 本轮/后续轮声明账不入；框架账（双 0）按 seq 截止到本轮之前。
            if src == cutoff_id or origin == cutoff_id:
                continue
            if src > 0 and src not in prior_turn_ids:
                continue
            if src <= 0 and origin > 0 and origin not in prior_turn_ids:
                continue
            if src <= 0 and origin <= 0:
                entry_seq = entry.get("order_key")
                if entry_seq is None:
                    entry_seq = entry.get("seq") or 0
                if float(entry_seq) >= float(cutoff_seq):
                    continue
        body = str(entry.get("body") or "")
        if body.strip():

def _note_funding_item(it: Dict[str, object]) -> None:
