def power_report(
    self, exclude_self: bool = True, kinds: Optional[Iterable[str]] = None,
    *, audience: bool = False,
) -> str:
    rows = self.power_rows(exclude_self=exclude_self)
    if kinds is not None:
        allowed = {str(kind).strip().lower() for kind in kinds}
        # Callers may hold canonical power ids (the content contract) or
        # display kinds (the presentation contract); both denote the same
        # filtered report set.
        rows = [row for row in rows if (
            str(row["kind"] or "").strip().lower() in allowed
            or str(row["id"] or "").strip().lower() in allowed
        )]
    if not rows:
        return "势力未建档。"
    if audience:
        return "；".join(
            f"{row['name']}（{row['leader']}）：{row['stance']}，"
            f"威望{power_band(row['leverage'])}、"
            f"实力{power_band(row['military_strength'])}、"
            f"经济{qualitative_band(row['supply'], ('匮乏', '吃紧', '尚可', '充足', '丰裕'))}，"
            f"{row['status']}；近动：{row['last_action'] or '尚无新动'}"
            for row in rows
        )
    return "；".join(
        f"{row['name']}（{row['leader']}）：{row['stance']}，威望{row['leverage']}、"
        f"实力{row['military_strength']}、经济{row['supply']}，"
        f"{row['status']}；近动：{row['last_action'] or '尚无新动'}"
        for row in rows
    )

def _commission_appointment_fields(
    appointment: object, *, source: Provenance,
) -> Tuple[Optional[Dict[str, Any]], Optional[RejectedItem]]:
    """交办上的任免载荷；缺 name/office（任命）→ invalid_shape。"""
    if not appointment:
        return None, None
    if not isinstance(appointment, Mapping):
        return None, RejectedItem(
            item={"raw_value": appointment}, reason="任免载荷须为对象",
            category="invalid_shape", source=source,
        )
    action = str(
        appointment.get("appoint_action") or appointment.get("action") or "任命"
    ).strip() or "任命"
    if action not in {"任命", "罢免"}:
        return None, RejectedItem(
            item=dict(appointment), reason=f"任免动作非法：{action}",
            category="invalid_enum", source=source,
        )
    name = str(appointment.get("name") or "").strip()
    office = str(appointment.get("office") or appointment.get("new_office") or "").strip()
    if not name:
        return None, RejectedItem(
            item=dict(appointment), reason="任免声明缺 name",
            category="invalid_shape", source=source,
        )
    if action == "任命" and not office:
        return None, RejectedItem(
            item=dict(appointment), reason="任命声明缺 office",
            category="invalid_shape", source=source,
        )
    payload: Dict[str, Any] = {"name": name, "office": office, "appoint_action": action}
    mode = appointment.get("mode")
    if mode is not None:
        if not isinstance(mode, str) or mode not in {"ordinary", "midzhi"}:
            return None, RejectedItem(
                item=dict(appointment), reason=f"任免模式非法：{mode}",
                category="invalid_enum", source=source,
            )
        payload["mode"] = mode
    tenure = str(
        appointment.get("appointment_tenure") or appointment.get("任别") or ""
    ).strip()
    if tenure:
        payload["appointment_tenure"] = tenure
    # Typed 任所原样透传；不从官名推断（地方/督抚/边镇任命必填；中央可空）。
    seat = str(
        appointment.get("region_id") or appointment.get("任所") or ""
    ).strip()
    if seat:
        payload["region_id"] = seat
    return payload, None

def _dispatch_endorsements(
    db: Any, state: Any, raw: object, *, night_id: int,
    chat_turn_id: int, source: Provenance,
) -> SectionResult:
    """#1842：每轮转译声明对暂存交办的会签/当面站台/御笔手敕。

    挂在 pending_actions.payload_json["endorsements"]，成案时继承到案卷；
    目标已成案（迟到转译）则按 pending_action_id 直写案卷背书。来源为本轮。
    """
    from ming_sim.strict_types import strict_int

    items, rejected = _section_items(raw, label="背书声明", source=source)
    applied: List[Any] = []
    ctid = int(chat_turn_id or 0)
    if ctid <= 0 and items:
        for item in items:
            _reject(
                rejected, item, "背书须绑定本轮对话源", "missing_ref", source,
            )
        return SectionResult(applied=applied, rejected=rejected)
    for item in items:
        try:
            action_id = strict_int(
                item.get("action_id"), accept_numeric_strings=False,
            )
        except (TypeError, ValueError):
            action_id = 0
        form = str(item.get("form") or "").strip()
        endorser_id = str(item.get("endorser_id") or "").strip()
        if action_id <= 0 or form not in {"会签", "当面站台", "御笔手敕"}:
            _reject(
                rejected, item,
                "背书须含正 action_id 与 会签|当面站台|御笔手敕",
                "invalid_shape", source,
            )
            continue
        imperial = form == "御笔手敕"
        if imperial:
            endorser_id = ""
        elif not endorser_id:
            _reject(
                rejected, item, "会签/当面站台必须具名背书人",
                "invalid_shape", source,
            )
            continue
        row = db.conn.execute(
            "SELECT id, night_id, status, payload_json FROM pending_actions "
            "WHERE id=? AND turn=?",
            (action_id, int(state.turn)),
        ).fetchone()
        if row is None or int(row["night_id"] or 0) != int(night_id):
            _reject(
                rejected, item, f"暂存动作不属本夜暂存清单：{action_id}",
                "missing_ref", source,
            )
            continue
        entry = {
            "form": form,
            "endorser_id": endorser_id,
            "imperial": imperial,
            "source_chat_turn_id": ctid,
        }
        status = str(row["status"] or "")
        if status == "pending":
            try:
                db.attach_pending_action_endorsement(
                    action_id, entry, commit=False,
                )
            except (TypeError, ValueError, KeyError) as exc:
                _reject(rejected, item, str(exc), "invalid_item", source)
                continue
        elif status == "committed":
            drow = db.conn.execute(
                "SELECT id FROM decree_dossiers WHERE pending_action_id=? "
                "ORDER BY id", (action_id,),
            ).fetchall()
            if not drow:
                _reject(
                    rejected, item,
                    f"已成案暂存无对应案卷：{action_id}",

def _effect_extraction_from_clean(
    clean: Mapping[str, object],
    event_id: str,
    *,
    empty_extraction: Mapping[str, object],
) -> tuple[dict[str, object], dict[str, list[tuple[str, object]]], dict[str, list[str]], list[dict[str, object]]]:
    """Build one apply_score_extraction payload from a single effect envelope."""
    extraction = copy.deepcopy(dict(empty_extraction))
    ordered_deltas = {field: [] for field in _ORDERED_DELTA_FIELDS}
    ordered_effect_event_ids = {field: [] for field in empty_extraction}
    unowned_outcomes: list[dict[str, object]] = []
    for field, value in clean.items():
        if field not in empty_extraction:
            continue
        if isinstance(value, list):
            extraction[field].extend(value)
            ordered_effect_event_ids[field].extend([event_id] * len(value))
        elif isinstance(value, dict):
            if field == "事件结局":
                from ming_sim.issues import _merge_first_event_outcome
                unowned_outcomes.extend(
                    _merge_first_event_outcome(extraction[field], value, event_id)
                )
            else:
                extraction[field].update(value)
            if field in ordered_deltas:
                ordered_deltas[field].extend(value.items())
                ordered_effect_event_ids[field].extend([event_id] * len(value))
        elif value is not None:
            extraction[field] = value
    return extraction, ordered_deltas, ordered_effect_event_ids, unowned_outcomes

def _collect_compliant_promulgation_items(
    batch: object,
    db: GameDB,
    *,
    proposed_modes: Dict[int, str],
    prepared_context: Optional[Dict[str, object]],
    reviewed_dossier_ids: Optional[set[int]],
) -> List[Dict[str, object]]:
    """从不合规整批中收集单项已过闸的判决（证据保留，不落判、不伪造缺案）。"""
    if not isinstance(batch, list):
        return []
    good: List[Dict[str, object]] = []
    seen: set[int] = set()
    for candidate in batch:
        try:
            valid = _validate_promulgation_verdict_item(
                candidate, db,
                proposed_modes=proposed_modes,
                prepared_context=prepared_context,
            )
        except LLMContractError:
            continue
        dossier_id = int(valid["dossier_id"])
        if reviewed_dossier_ids is not None and dossier_id not in reviewed_dossier_ids:
            continue
        if dossier_id in seen:
            continue
        seen.add(dossier_id)
        good.append(valid)
    return good

def _provenance_from_stored(value: object) -> Provenance:
    """从 ctx 持久值还原 Provenance（#146 恢复路）：兼容 Provenance 实例、已存的字符串值、
    历史误序列化的 'Provenance.<name>' 字面串、及非法/缺失值。非法/缺失回落 system_simulation。

    防静默丢源（Sourcery + gemini + coderabbit #175 concur）：Provenance 是 (str, Enum)，
    若曾把枚举实例 str() 落库会得到 'Provenance.player_decree'（而非值 'player_decree'），
    Provenance(...) 不匹配 → ValueError → 丢源退回 system_simulation。故分三层：
    ① 实例直接返回；② 纯值走 Provenance(value)；③ 'Provenance.<name>' 旧脏串剥前缀按成员名查回；
    仍无法识别才回落 system_simulation。"""
    if isinstance(value, Provenance):
        return value
    text = str(value or "system_simulation")
    try:
        return Provenance(text)
    except ValueError:
        pass
    # 历史误序列化：str(枚举实例) 落库的 'Provenance.player_decree' 脏串——剥前缀按成员名查回，
    # 不让旧档玩家来源静默退化成 system_simulation。
    if text.startswith("Provenance."):
        try:
            return Provenance[text.split(".", 1)[1]]
        except KeyError:
            pass
    return Provenance.system_simulation

def _scan(section: str, items: list) -> None:
    for item in items:
        if not isinstance(item, dict):
            continue
        if item.get("rejected"):
            report_section = str(item.get("report_section") or section)
            collector.record(report_section, RejectedItem(
                # item_json = 原始 delta 项（ADR 决定 5「原 item 原样保留」）：迁约
                # producer 在 wrapper 里带原件（'item' 键）则解包,否则兜底存 wrapper
                # （ship-pre r3——存整个 wrapper 会让重放分析消费到嵌套形状）。
                # 按 'item' 键**存在性**解包（非值类型）：原 isinstance(dict/list/str) 判会把
                # 标量/null 原件（如 close_issues:[null]/[42] 的非 dict 拒收）误存成 wrapper、
                # 丢原件保真——key 在即解包，覆盖标量原件（cmr close-issues r5 codex）。
                item=item["item"] if "item" in item else item,
                # ADR「拒收行必带人读原因」在此集中守门：producer 漏给则合成非空兜底
                # ——规则写一处，新 section 免疫同类缺陷（fix-coverage 处方，cmr S0 r3）。
                reason=str(item.get("reason") or "") or f"拒收（{report_section} 未注明原因）",
                category=str(item.get("report_category") or item.get("category") or "legacy_inline"),
                source=source,
            ), turn)
        for subkey, subvalue in item.items():
            if isinstance(subvalue, list):
                nested_section = f"{section}.{subkey}"
                if nested_section == "issue_summary.closes.applied_person_changes":
                    continue
                _scan(nested_section, subvalue)

def _payload_dict(candidate: Dict[str, Any]) -> Dict[str, Any]:
    payload = candidate.get("payload")
    if isinstance(payload, dict):
        return payload
    raw = candidate.get("payload_json")
    if raw in (None, ""):
        return {}
    loaded = json.loads(str(raw))
    return loaded if isinstance(loaded, dict) else {}

def bake_distance_matrix(graph: Mapping[str, object]) -> dict[str, dict[str, float | int]]:
    """Bake all-pairs shortest travel times from a weighted region graph.

    Node weights are the cost of crossing a region.  The first and last node
    count half, while intermediate nodes count in full.  A node-to-itself
    route is explicitly zero because the graph is province-granularity data.
    """

    raw_nodes = graph.get("nodes")
    if not isinstance(raw_nodes, Mapping) or not raw_nodes:
        raise ValueError("distance graph must contain a non-empty nodes object")
    node_weights = {
        node: _number(config.get("weight") if isinstance(config, Mapping) else None, f"nodes.{node}.weight")
        for node, config in raw_nodes.items()
        if isinstance(node, str)
    }
    if len(node_weights) != len(raw_nodes):
        raise ValueError("distance graph node ids must be strings")
    adjacency = _graph_edges(graph)
    matrix: dict[str, dict[str, float | int]] = {}

    for source in node_weights:
        distances = {source: 0.0}
        queue: list[tuple[float, str]] = [(0.0, source)]
        while queue:
            cost_so_far, current = heapq.heappop(queue)
            if cost_so_far != distances[current]:
                continue
            for neighbor, edge_cost in adjacency[current]:
                # The source endpoint is half-weighted immediately.  An
                # intermediate node is full-weighted; the destination half is
                # corrected when the candidate is read into the matrix.
                node_cost = node_weights[current] if current != source else node_weights[source] / 2
                candidate = cost_so_far + edge_cost + node_cost
                if neighbor not in distances or candidate < distances[neighbor]:
                    distances[neighbor] = candidate
                    heapq.heappush(queue, (candidate, neighbor))

        row: dict[str, float | int] = {}
        for destination in node_weights:
            if destination == source:
                row[destination] = 0
                continue
            if destination not in distances:
                raise ValueError(f"distance graph is disconnected: {source} -> {destination}")
            row[destination] = distances[destination] + node_weights[destination] / 2
        matrix[source] = row

    # Dijkstra is run once per source, so mathematically identical routes can
    # still accumulate binary floating-point values in a different order.  The
    # asset models an undirected graph: choose one canonical calculation for
    # each pair, normalize it for JSON, then mirror that exact value.
    for source in sorted(node_weights):
        for destination in sorted(node_weights):
            if source >= destination:
                continue
            distance = round(float(matrix[source][destination]), 10)
            matrix[source][destination] = distance
            matrix[destination][source] = distance

    return matrix

def _next_attempt(turn: int) -> int:
    """同 turn 的下一个 attempt 序号：既有目录数字后缀 max+1（决定 5，不从 DB 取）。

    len+1 在非连续目录（玩家发包后删过早期 attempt）下会撞既有名而静默覆盖诊断孤本；
    不可解析的后缀忽略。
    """
    root = error_packs_root()
    if not root.exists():
        return 1
    prefix = f"turn{int(turn)}_attempt"
    highest = 0
    for p in root.iterdir():
        if not (p.is_dir() and p.name.startswith(prefix)):
            continue
        try:
            highest = max(highest, int(p.name[len(prefix):]))
        except ValueError:
            continue
    return highest + 1

def latest_error_pack_for_turn(db_path: object, turn: int) -> Optional[str]:
    """同 DB + turn 最新完整错误包绝对路径；无则 None（ADR 0008 决定 7 恢复面）。

    身份取 manifest.db_path + turn，
    禁跨存档串包（同 user-data 下另一 DB 的更高 attempt 不得入选）。
    目录扫描/条目 stat 的 OSError 视为无诊断包——不得拖垮 settling 恢复面。
    """
    root = error_packs_root()
    try:
        if not root.exists():
            return None
        entries = list(root.iterdir())
    except OSError:
        return None
    expected_db_path = str(db_path)
    prefix = f"turn{int(turn)}_attempt"
    best: Optional[Path] = None
    best_n = -1
    for path in entries:
        try:
            if not (path.is_dir() and path.name.startswith(prefix)):
                continue
            n = int(path.name[len(prefix):])
        except (OSError, ValueError):
            continue
        manifest = _read_complete_pack_manifest(path)
        if manifest is None:
            continue
        if (
            str(manifest.get("db_path")) != expected_db_path
            or manifest.get("turn") != int(turn)
        ):
            continue
        if n > best_n:
            best_n = n
            best = path
    if best is None:
        return None
    try:
        return str(best.resolve())
    except OSError:
        return None

def normalize_locality_scope(raw: object) -> str:
    """{'全国'/'单省'/'无'/缺省 → national/single/none}；枚举外 fail-loud。"""
    if raw is None:
        return "none"
    text = str(raw).strip()
    if not text:
        return "none"
    if text in _SCOPE_ALIASES:
        scope = _SCOPE_ALIASES[text]
    else:
        scope = text
    if scope not in LOCALITY_SCOPES:
        raise ValueError(f"locality_scope 非法：{raw!r}")
    return scope

def _arrears_order_displacement_entries(
    db: Any, config: Dict[str, int], region_id: str, st: Dict[str, Any], turn: int,
) -> List[Dict[str, Any]]:
    """以当月 Repaid/省池旧欠流量反演实偿，再按同一总实偿重放祖制旧欠序，投影让位。

    F1.6-③ / F2.2：只报因 arrears_priority 让位新增受损与胜出旨 origin_ref。
    不扩 schema、不新表；复用 region_logs Repaid 与 army_logs 省池旧欠流量。
    """
    from ming_sim.pay_order import (
        ARREARS_SUBJECTS, DEFAULT_ARREARS_PRIORITY, resolve_pay_order_overrides,
    )

    resolved = resolve_pay_order_overrides(config, region_id, turn)
    default_order = tuple(sorted(ARREARS_SUBJECTS, key=DEFAULT_ARREARS_PRIORITY.__getitem__))
    if resolved is None or resolved.arrears_order == default_order:
        return []

    actual_repaid = {s: 0.0 for s in ARREARS_SUBJECTS}
    rows = db.conn.execute(
        "SELECT field, delta FROM region_logs WHERE turn=? AND region_id=? "
        "AND field IN ('settle_官俸欠_Repaid','settle_宗禄欠_Repaid')",
        (turn, region_id),
    ).fetchall()
    for row in rows:
        subject = "官俸欠" if "官俸欠" in str(row["field"]) else "宗禄欠"
        # Repaid 留痕 delta 为负；取绝对值作实偿流量
        actual_repaid[subject] += max(0.0, -float(row["delta"] or 0))
    army = db.conn.execute(
        "SELECT COALESCE(SUM(CASE WHEN CAST(old_value AS REAL)>CAST(new_value AS REAL) "
        "THEN CAST(old_value AS REAL)-CAST(new_value AS REAL) ELSE 0 END),0) AS v "
        "FROM army_logs WHERE turn=? AND field='province_pay_arrears' AND army_id IN "
        "(SELECT id FROM armies WHERE pay_source_region=?)", (turn, region_id),
    ).fetchone()
    actual_repaid["军饷欠"] = float(army["v"] or 0)

    # 偿前 CLAIM = 月末存量 + 当月实偿（action 补饷已在 settle 前扣，不入本瀑布）
    claims = {
        s: max(0.0, float(st.get(s, 0) or 0) + actual_repaid[s])
        for s in ARREARS_SUBJECTS
    }
    pool = sum(actual_repaid.values())
    if pool <= 1e-9:
        return []
    default_repaid = _waterfall_allocate(default_order, claims, pool)

    arrears_class = {"军饷欠": "军户", "官俸欠": "官僚", "宗禄欠": "宗藩"}
    out: List[Dict[str, Any]] = []
    for subject in default_order:
        displaced = default_repaid[subject] - actual_repaid[subject]
        if displaced <= 1e-9:
            continue
        origin = _priority_override_origin_for(
            db, config, region_id, turn, subject, displaced, claims, pool,
            subjects=ARREARS_SUBJECTS,
            default_priority=DEFAULT_ARREARS_PRIORITY,
            key_prefix="arrears_priority",
            order_of=lambda resolved: resolved.arrears_order,
        )
        if origin:
            out.append({
                "subject_kind": "region", "subject_id": region_id, "region": region_id,
                "metric": "欠禄额", "window_turns": 1, "value": displaced,
                "origin_ref": origin, "affected_class": arrears_class[subject],
                "detail": f"旧欠序让位_{subject}",
            })
    return out

def _due_order_displacement_entries(
    db: Any, config: Dict[str, int], region_id: str, st: Dict[str, Any],
    p: Dict[str, Any], turn: int,
) -> List[Dict[str, Any]]:
    """以既有当月欠流量反演实付，再按同一总实付重放祖制序，投影旨序新增受损。"""
    from ming_sim.pay_order import DEFAULT_DUE_PRIORITY, DUE_SUBJECTS, haircut_due, resolve_pay_order_overrides

    resolved = resolve_pay_order_overrides(config, region_id, turn)
    default_order = tuple(sorted(DUE_SUBJECTS, key=DEFAULT_DUE_PRIORITY.__getitem__))
    if resolved is None or resolved.due_order == default_order:
        return []
    due_map = p.get("Due") if isinstance(p.get("Due"), dict) else {}
    dues = {s: max(0.0, float(due_map.get(s, 0) or 0)) for s in DUE_SUBJECTS}
    for subject, bp in resolved.haircut_bp.items():
        dues[subject] = haircut_due(dues[subject], int(bp))[0]
    unpaid = {s: 0.0 for s in DUE_SUBJECTS}
    rows = db.conn.execute(
        "SELECT field, delta FROM region_logs WHERE turn=? AND region_id=? "
        "AND field IN ('settle_官俸欠_NewDebt','settle_宗禄欠_NewDebt')",
        (turn, region_id),
    ).fetchall()
    for row in rows:
        subject = "官俸" if "官俸欠" in str(row["field"]) else "宗禄"
        unpaid[subject] += max(0.0, float(row["delta"] or 0))
    army = db.conn.execute(
        "SELECT COALESCE(SUM(CASE WHEN CAST(new_value AS REAL)>CAST(old_value AS REAL) "
        "THEN CAST(new_value AS REAL)-CAST(old_value AS REAL) ELSE 0 END),0) AS v "
        "FROM army_logs WHERE turn=? AND field='province_pay_arrears' AND army_id IN "
        "(SELECT id FROM armies WHERE pay_source_region=?)", (turn, region_id),
    ).fetchone()
    unpaid["军饷"] = float(army["v"] or 0)
    unpaid["赈济"] = max(0.0, float(st.get("unmet_relief", 0) or 0))
    actual_paid = {s: max(0.0, dues[s] - min(dues[s], unpaid[s])) for s in DUE_SUBJECTS}
    pool = sum(actual_paid.values())
    default_paid = _waterfall_allocate(default_order, dues, pool)
    out: List[Dict[str, Any]] = []
    for subject in default_order:
        displaced = default_paid[subject] - actual_paid[subject]
        if displaced <= 1e-9:
            continue
        origin = _priority_override_origin(
            db, config, region_id, turn, subject, displaced, dues,
            sum(actual_paid.values()),
        )
        if origin:
            out.append({
                "subject_kind": "region", "subject_id": region_id, "region": region_id,
                "metric": "欠禄额", "window_turns": 1, "value": displaced,
                "origin_ref": origin, "affected_class": FACT_CLASS_MAP[subject],
                "detail": f"旨序让位_{subject}",
            })
    return out

def _ming_settle_bases(db: Any) -> List[Tuple[str, Dict[str, Any], Dict[str, Any]]]:
    """① 明控且有 settle key 的省级基座；缺 key 出列，坏 JSON/现存坏结构响亮失败。"""
    out: List[Tuple[str, Dict[str, Any], Dict[str, Any]]] = []
    rows = db.conn.execute(
        "SELECT id, fiscal FROM regions WHERE controlled_by = 'ming' ORDER BY id"
    ).fetchall()
    for row in rows:
        region_id = str(row["id"])
        try:
            fiscal = json.loads(str(row["fiscal"] or "{}"))
        except (TypeError, ValueError) as exc:
            raise ValueError(
                f"fiscal_fact_brief：region {region_id} fiscal JSON 非法：{exc}"
            ) from exc
        if not isinstance(fiscal, dict):
            raise ValueError(f"fiscal_fact_brief：region {region_id} fiscal 非字典")
        if "settle" not in fiscal:
            continue
        settle = fiscal["settle"]
        if not isinstance(settle, dict):
            raise ValueError(f"fiscal_fact_brief：region {region_id} settle 非字典")
        st = settle.get("st")
        p = settle.get("p")
        if not isinstance(st, dict) or not isinstance(p, dict):
            raise ValueError(
                f"fiscal_fact_brief：region {region_id} settle.st/p 非字典"
            )
        out.append((region_id, st, p))
    return out

def _apply_class_dict(
    db: GameDB,
    class_delta: Dict[str, object],
    *,
    commit: bool = True,
) -> DeltaApplyResult:
    """class_delta 结构：{ '农民@shaanxi': {'satisfaction': -5, 'leverage': +3}, '士绅': {...} }
    key 不带 @ 默认全国汇总。字段只接 satisfaction / leverage 增量。

    逐项拒收契约（ADR 0008 决定 1，#14/#63）：字段值非整数（含 bool/float）→
    invalid_enum 逐项拒收；查无此阶级名由 db.adjust_classes 返 missing_ref。
    #649 §1.4 升格：value 内出现 population 键 → 该 item 整项以 invalid_enum 拒收
    留痕（原为静默忽略；合法转移入口开通后，静默通道不得存活），其余 sat/lev 合法
    item 不受累——一切人口变化走 population_transfers 守恒原语。二级真值非 dict
    （如 {"农民": 0}）同样逐项拒收。
    返回 (已落 delta dict, 拒收项列表)：前者供 web 「阶级变化」面板，后者由顶层置于
    "class_delta_rejections" 段、桥接自动收。
    """
    # #649 C3/C4：字段名先经 ITEM_FIELD_ALIASES 单一真源 canonical 化（满意→satisfaction、
    # 人口→population），使 population guard 对中英文拼写统一整项拒收，不在本层手抄别名分支。
    from ming_sim.simulation import _canonical_item_fields

    cleaned: Dict[str, Dict[str, int]] = {}
    rejected: List[Dict[str, object]] = []
    class_delta = class_delta if isinstance(class_delta, dict) else {}  # #117 同类：真值非 dict 守卫
    for key, fields in class_delta.items():
        if isinstance(fields, dict):
            fields = _canonical_item_fields(fields)
        if not isinstance(fields, dict):
            rejected.append({
                "name": str(key), "rejected": True, "category": "invalid_enum",
                "reason": f"「{key}」阶级变化须为对象：{fields!r}",
                "item": {str(key): fields},
            })
            continue
        if "population" in fields:
            rejected.append({
                "name": str(key), "rejected": True, "category": "invalid_enum",
                "reason": (
                    f"「{key}」class_delta 无 population 更新面：写 population 整项拒收，"
                    "人口只经 population_transfers 守恒转移变动（#649/0087，单记录双写）"
                ),
                "item": {str(key): fields},
            })
            continue
        entry: Dict[str, int] = {}
        for fname in ("satisfaction", "leverage"):
            raw = fields.get(fname)
            if raw is None:
                continue
            try:
                d = _strict_int(raw)
            except (TypeError, ValueError):
                rejected.append(_value_reject(key, raw, fields, fname))
                continue
            if d == 0:
                continue
            entry[fname] = d
        if entry:
            cleaned[str(key)] = entry
    if cleaned:
        # 同 faction：db 层未知名 missing_ref 拒收未写库，从 cleaned 剔除防面板误显（cmr r3 codex）。
        for _rej in db.adjust_classes(cleaned, commit=commit):
            cleaned.pop(str(_rej.get("name", "")), None)
            rejected.append(_rej)
    return DeltaApplyResult(cleaned, rejected)

def _apply_metric_dict(
    state: GameState, metric_delta: Dict[str, object], caps: Optional[Dict[str, int]] = None,
    db: Optional[GameDB] = None,
) -> Dict[str, int]:
    # 传 db 时，民心/皇威 增量先过帝国修正 %（base>=0 ×(1+net/100)，base<0 ×(1-net/100)），再夹 cap。
    mods = db.legacy_modifiers(state) if db is not None else {}
    applied: Dict[str, int] = {}
    # isinstance 守卫：issue-effect 路径（enrich/stored，未过 validate_delta_shape）的 metrics 可能
    # 被 LLM 给成真值非 dict，`or {}` 兜不住→.items() 抛 AttributeError 崩回合（#117 同类，顶层 delta
    # 已由 validate_delta_shape 保 dict，此守卫只对未验证的 issue-effect 调用点生效、不误伤）。
    metric_delta = metric_delta if isinstance(metric_delta, dict) else {}
    for key, val in metric_delta.items():
        if key not in ISSUE_METRIC_KEYS:
            continue
        try:
            d = int(val)
        except (TypeError, ValueError):
            continue
        net_pct = int(mods.get(key, 0) or 0)
        if net_pct and db is not None:
            d = db.apply_legacy_pct(d, net_pct)
        if caps and key in caps:
            cap = caps[key]
            if d > cap:
                d = cap
            elif d < -cap:
                d = -cap
        if d == 0:
            continue
        state.metrics[key] = int(state.metrics.get(key, 0)) + d
        applied[key] = applied.get(key, 0) + d
    return applied

def _as_finite_nonnegative_float(label: str, value: object) -> float:
    if isinstance(value, bool):
        raise ValueError(f"{label} 非数值：{value!r}")
    if value in (None, ""):
        return 0.0
    try:
        amount = float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{label} 非数值：{value!r}") from exc
    if not math.isfinite(amount) or amount < 0:
        raise ValueError(f"{label} 非法：{value!r}")
    return amount

def derive_army_mutiny_state(army) -> str:
    """实时派生哗变状态；持久 latch 与察看期优先覆盖 loyalty 档。"""
    if bool(army["is_mutinied"]):
        return "哗变"
    loyalty = int(army["loyalty"])
    probation = int(army["mutiny_probation"]) if "mutiny_probation" in army.keys() else 0
    if loyalty >= 60 and probation <= 0:
        return "正常"
    if loyalty >= 40:
        return "不满"
    return "鼓噪"

def _apply_extracted_army_delta(
    db: GameDB, state: GameState, pseudo_event: Event, army_id: str,
    raw_changes: Dict[str, object], *, commit_now: bool,
) -> List[Dict[str, object]]:
    """Apply one extracted army item, including an explicit paired cannon transfer."""
    army_changes: List[Dict[str, object]] = []
    origin_ref = str(raw_changes.get("origin_ref") or "").strip()
    payload = {k: v for k, v in raw_changes.items() if k != "origin_ref"}
    if "cannon_transfer_to" in payload:
        target_id = payload.pop("cannon_transfer_to")
        cannon_keys = [k for k in payload if ARMY_FIELD_ALIASES.get(k, k) == "cannon_equipment"]
        try:
            requested = _strict_int(payload[cannon_keys[0]]) if len(cannon_keys) == 1 else 0
        except (TypeError, ValueError):
            requested = 0
        source = db.conn.execute(
            "SELECT cannon_equipment, is_mutinied FROM armies WHERE id=?", (army_id,)
        ).fetchone()
        origin_error = db.effect_origin_rejection(origin_ref)
        if origin_error:
            army_changes.append({"army_id": army_id, **origin_error,
                                 "item": {"army_id": army_id, "changes": raw_changes}})
            return army_changes
        target = (db.conn.execute(
            "SELECT cannon_equipment, is_mutinied FROM armies WHERE id=?", (target_id,)
        ).fetchone() if isinstance(target_id, str) and target_id else None)
        if (len(cannon_keys) != 1 or requested >= 0 or source is None
                or target is None or target_id == army_id):
            army_changes.append({
                "army_id": army_id, "rejected": True,
                "category": "missing_ref" if source is None or target is None else "invalid_enum",
                "reason": "随军炮转移须指定在册来源、去向及负数拟转量",
                "item": {"army_id": army_id, "changes": raw_changes},
            })
            return army_changes
        for key in cannon_keys:
            payload.pop(key)
        writable = all(
            not bool(row["is_mutinied"]) or latched_army_field_effect_permitted(
                "cannon_equipment", delta,
            )
            for row, delta in ((source, requested), (target, -requested))
        )
        actual = (min(-requested, int(source["cannon_equipment"]),
                      12 - int(target["cannon_equipment"])) if writable else 0)
        if actual > 0:
            db.conn.execute("SAVEPOINT cannon_transfer")
            try:
                transfer_changes: List[Dict[str, object]] = []
                for leg_id, leg_delta in ((army_id, -actual), (target_id, actual)):
                    leg_changes = db.apply_army_deltas(
                        state, pseudo_event, None, "档房",
                        {leg_id: {"随军大炮": leg_delta, "reason": raw_changes.get("reason")}},
                        commit=False, origin_ref=origin_ref, require_origin=True,
                    )
                    if len(leg_changes) != 1 or leg_changes[0].get("delta") != leg_delta:
                        raise RuntimeError("随军炮转移双边实数不等")
                    transfer_changes.extend(leg_changes)
                db.conn.execute("RELEASE SAVEPOINT cannon_transfer")
            except Exception:
                db.conn.execute("ROLLBACK TO SAVEPOINT cannon_transfer")
                db.conn.execute("RELEASE SAVEPOINT cannon_transfer")
                raise
            army_changes.extend(transfer_changes)
            if commit_now:
                db.conn.commit()
        else:
            for leg_id in (army_id, target_id):
                army_changes.append({
                    "army_id": leg_id, "field": "cannon_equipment",
                    "delta": 0, "applied": False, "reason": raw_changes.get("reason"),
                })
    army_changes.extend(db.apply_army_deltas(
        state, pseudo_event, None, "档房", {army_id: payload}, commit=commit_now, origin_ref=origin_ref, require_origin=True,
    ))

    return army_changes

def _commitment_bar_value(progress: Dict[str, object]) -> Optional[int]:
    if "remaining_arrears" not in progress:
        return None
    paid = max(0, int(progress.get("paid_total") or 0))
    try:
        remaining = max(0.0, float(progress.get("remaining_arrears") or 0))
    except (TypeError, ValueError):
        remaining = 0.0
    total = paid + remaining
    if total <= 0:
        return 100
    return max(0, min(100, int(round(paid * 100 / total))))

def _commitment_ongoing_effects_for_settlement(row: sqlite3.Row, ongoing: Dict[str, object]) -> Dict[str, object]:
    if not _commitment_gate_references_arrears(row):
        return ongoing
    gate_army_ids = _commitment_arrears_gate_army_ids(row)
    normalized = dict(ongoing)
    for key in ("economy", "economy_moves"):
        economy = ongoing.get(key)
        if not isinstance(economy, list):
            continue
        normalized_economy: List[object] = []
        for move in economy:
            if not isinstance(move, dict):
                normalized_economy.append(move)
                continue
            item = dict(move)
            try:
                delta = _strict_int(item.get("delta"))
            except (TypeError, ValueError):
                delta = 0
            if delta < 0:
                item["purpose"] = "补饷"
                if (
                    len(gate_army_ids) == 1
                    and not str(item.get("target_id") or "").strip()
                    and not str(item.get("目标编号") or "").strip()
                    and not str(item.get("target_kind") or item.get("目标类型") or "").strip()
                ):
                    item["target_kind"] = "army"
                    item["target_id"] = gate_army_ids[0]
            normalized_economy.append(item)
        normalized[key] = normalized_economy
    return normalized

def _commitment_remaining_from_gate(
    gate: Dict[str, str],
    state: GameState,
    db: GameDB,
) -> Optional[float]:
    remaining = 0.0
    found = False
    for key, cond in gate.items():
        cond_text = str(cond or "").strip()
        m = re.match(r"^(>=|<=|>|<|==)\s*(-?\d+)$", cond_text)
        if not m:
            continue
        val = _eval_gate_key(str(key), state.metrics, db)
        if val is None:
            continue
        try:
            val_num = float(val)
        except (TypeError, ValueError):
            continue
        op, target = m.group(1), int(m.group(2))
        if op == "<=":
            need = max(0.0, val_num - target)
        elif op == "<":
            need = 0.0 if val_num < target else float(int(val_num - target) + 1)
        elif op == ">=":
            need = max(0.0, target - val_num)
        elif op == ">":
            need = 0.0 if val_num > target else float(int(target - val_num) + 1)
        else:
            need = abs(val_num - target)
        remaining += need
        found = True
    return remaining if found else None

def _content_population_effect_for_save(
    db: GameDB, effect: Dict[str, object]
) -> Dict[str, object]:
    """#648（ADR 0088/F4）：content 静态人口量已全线「人」，落本档前按存档口径换算。

    新档（人）原样；无标旧档（万人）region_delta.population ÷10⁴（迁移后 content
    人口值均为 10⁴ 整倍数，整除无损）。只换算 region_delta.*.population，其余段浅拷贝透传。
    只用于 content 事件真源（effect_on_trigger / event_to_issue 持久化）；LLM 产 delta
    已按本档口径写，不得经此换算。"""
    region_delta = effect.get("region_delta")
    if not isinstance(region_delta, dict) or not region_delta:
        return effect
    if db.population_unit == POPULATION_UNIT_PERSONS:
        return effect
    scaled: Dict[str, object] = {**effect}
    scaled_region_delta: Dict[str, object] = {}
    for rid, fields in region_delta.items():
        if isinstance(fields, dict) and "population" in fields:
            scaled_fields = {**fields}
            try:
                scaled_fields["population"] = db.scale_content_population_to_save_unit(
                    fields["population"]
                )
            except (TypeError, ValueError):
                pass  # 非整人口值交由下游 apply_region_deltas 既有拒收留痕，不在此静默改写
            scaled_region_delta[rid] = scaled_fields
        else:
            scaled_region_delta[rid] = fields
    scaled["region_delta"] = scaled_region_delta
    return scaled

