def classify_transport_failure(error: BaseException) -> ClassifiedFailure:
    """先分类后重试。只认 typed 信号；不从错误散文猜语义（ADR 0142）。

    可重试：瞬断/空转/5xx/408/429/空输出；召对 429 例外在调用策略落实。
    不可重试：其余确定性 4xx（#1452 Unknown model 等带 4xx status）。
    未知（无 status 的笼统 stream/run error）→ 不洗成瞬断，立即上浮。

    本函数是 APITimeout/Connection/Status/空输出/RunError → code/retryable/status 的唯一权威
    （llm_unavailable_from_error / run_error_event_failure / empty_output_failure 委派或同构）。
    """
    if isinstance(error, TransportIdleTimeout):
        return ClassifiedFailure(
            retryable=True,
            code="llm_idle_timeout",
            status_code=None,
            provider_message=str(error) or "idle timeout",
            message="LLM 调用空转超时。",
        )
    if isinstance(error, APITimeoutError):
        return ClassifiedFailure(
            retryable=True,
            code="llm_timeout",
            status_code=None,
            provider_message=str(error),
            message="LLM 调用超时。",
        )
    if isinstance(error, APIConnectionError):
        return ClassifiedFailure(
            retryable=True,
            code="llm_connection_error",
            status_code=None,
            provider_message=str(error),
            message="LLM 连接失败。",
        )
    if isinstance(error, APIStatusError):
        status_i = _coerce_status(getattr(error, "status_code", None))
        code = f"llm_http_{status_i}" if status_i is not None else "llm_http_error"
        return ClassifiedFailure(
            retryable=_status_retryable(status_i),
            code=code,
            status_code=status_i,
            provider_message=str(error),
            message=f"LLM 调用失败（HTTP {status_i}）。" if status_i else "LLM 调用失败。",
        )
    if isinstance(error, LLMUnavailable):
        status = error.status_code
        code = str(error.code or "llm_unavailable")
        pmsg = str(error.provider_message or error.message or "")
        status_i = _coerce_status(status)
        if status_i is not None:
            return ClassifiedFailure(
                retryable=_status_retryable(status_i),
                code=code,
                status_code=status_i,
                provider_message=pmsg,
                message=str(error.message or pmsg or "LLM 调用失败。"),
            )
        if code in {
            "llm_timeout",
            "llm_connection_error",
            "llm_idle_timeout",
            "llm_empty_output",
        }:
            return ClassifiedFailure(
                retryable=True,
                code=code,
                status_code=None,
                provider_message=pmsg,
                message=str(error.message or pmsg or "LLM 调用失败。"),
            )
        if code.startswith("llm_http_"):
            tail = code[len("llm_http_") :]
            status_from_code = _coerce_status(tail)
            if status_from_code is not None:
                return ClassifiedFailure(
                    retryable=_status_retryable(status_from_code),
                    code=code,
                    status_code=status_from_code,
                    provider_message=pmsg,
                    message=str(error.message or pmsg or "LLM 调用失败。"),

def _strip_controlled_namespace(text: str, namespace: str) -> str:
    """Strip only the extractor's exact namespace wrappers, never prose."""
    if text.startswith("@"):
        return text[1:]
    prefix = f"{namespace}."
    if text.startswith(prefix):
        return text[len(prefix):]
    return text

def army_identity_aliases(army: Army) -> List[str]:
    """军队身份别名：id / 军名 / 受控别名。不含驻地/战区/将领上下文。"""
    aliases = [army.id, army.name, compact_name(army.name)]
    for part in re.split(r"\s*/\s*|\s*／\s*", army.name):
        if part.strip():
            aliases.append(part.strip())
    aliases.extend(ARMY_SPECIAL_ALIASES.get(army.id, ()))
    return _unique_aliases(aliases)

def region_aliases(region: Region) -> List[str]:
    aliases = [region.id, region.name, compact_name(region.name)]
    for part in re.split(r"\s*/\s*|\s*／\s*", region.name):
        if part.strip():
            aliases.append(part.strip())
    aliases.extend(REGION_SPECIAL_ALIASES.get(region.id, ()))
    unique: List[str] = []
    seen: set = set()
    for alias in aliases:
        key = compact_name(alias)
        if not key or key in seen:
            continue
        seen.add(key)
        unique.append(alias)
    return unique

def resolve_special_region_alias(token: str) -> Optional[str]:
    """Exact id or special-alias token → region_id；未知返回 None（不模糊匹配）。"""
    raw = str(token or "").strip()
    if not raw:
        return None
    if raw in REGION_SPECIAL_ALIASES:
        return raw
    key = compact_name(raw)
    if not key:
        return None
    if key in REGION_SPECIAL_ALIASES:
        return key
    for region_id, aliases in REGION_SPECIAL_ALIASES.items():
        if key == compact_name(region_id):
            return region_id
        for alias in aliases:
            if key == compact_name(alias):
                return region_id
    return None

def _resolve_inside(root: Path, rel: str) -> Path:
    root_r = root.resolve()
    raw = str(rel or "").strip()
    if not raw or raw in {".", "./"}:
        return root_r
    if Path(raw).is_absolute() or raw.startswith("~"):
        raise ValueError("材料路径越出目录")
    candidate = (root_r / raw).resolve()
    try:
        candidate.relative_to(root_r)
    except ValueError as exc:
        raise ValueError("材料路径越出目录") from exc
    return candidate

