def _nonzero_int(raw: object) -> bool:
    if raw in (None, "") or isinstance(raw, (bool, float)):
        return False
    try:
        return int(raw) != 0  # type: ignore[arg-type]
    except (TypeError, ValueError, OverflowError):
        return False

def _question_as_decision(question: Dict[str, object], *, event_id: str) -> Dict[str, object]:
    options = question.get("options") if isinstance(question.get("options"), list) else []
    cleaned = []
    for opt in options:
        if not isinstance(opt, dict):
            continue
        label = str(opt.get("label") or "")
        if not label.strip():
            continue
        cleaned.append({
            "label": label,
            "hint": str(opt.get("hint") or ""),
            **{
                key: opt[key] for key in opt
                if key not in {"label", "hint"} and opt[key] is not None
            },
        })
    return {
        "event_id": event_id,
        "title": str(question.get("title") or "") or "请旨",
        "context": str(question.get("context") or ""),
        "options": cleaned,
    }

def _match_rank_rule(
    title: str, table: dict[str, Any], required_field: str
) -> Optional[dict[str, Any]]:
    """Return the longest matching stem that defines the requested behavior."""
    text = str(title or "").strip()
    if not text:
        return None
    best: Optional[dict[str, Any]] = None
    best_score = (-1, -1)
    for rule in _iter_rank_rules(table):
        if required_field not in rule:
            continue
        # Leverage-bearing rules describe substantive titles.  Rank-only rules also
        # contain institutional/category fallbacks such as 翰林院 and 锦衣卫.
        title_specific = int(
            required_field == "rank_band" and "leverage_multiplier" in rule
        )
        for stem in rule.get("stems") or []:
            token = str(stem or "").strip()
            if not token or token not in text:
                continue
            score = (title_specific, len(token))
            if score > best_score:
                best = rule
                best_score = score
    return best

