    return ni.get("stages_json")

def stages_to_json(stages: object) -> str:
    """Serialize stages for durable DB write.

    Designed string surface: JSON array string is parsed, not char-iterated.
    Invalid non-empty strings raise ValueError (never silently store ``[]``).
    ``None`` / empty / ``[]`` → ``"[]"``.
    """
    if stages is None:
        return "[]"
    if isinstance(stages, str):
        text = stages.strip()
        if not text or text in ("[]", "{}"):
            return "[]"
        try:
            data = json.loads(text)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                f"stages_json 须为 JSON 数组字符串，解析失败：{text[:80]!r}"
            ) from exc
        if not isinstance(data, (list, tuple)):
            raise ValueError(
                f"stages_json 须为 JSON 数组，得 {type(data).__name__}"
            )
        if len(data) == 0:
            return "[]"
        normalized = normalize_commitment_stages(data)
        if not normalized:
            raise ValueError(
                "stages_json 无有效段（每段须 due_turn>0 与 criterion_text）"
            )
        return json.dumps(normalized, ensure_ascii=False, separators=(",", ":"))
    if isinstance(stages, (list, tuple)):
        if not stages:
            return "[]"
        normalized = normalize_commitment_stages(list(stages))
        # 非空 list 归一后无有效段：与 str 支同响亮拒绝，禁静默存 []
        if not normalized:
            raise ValueError(
                "stages_json 无有效段（每段须 due_turn>0 与 criterion_text）"
            )
        return json.dumps(normalized, ensure_ascii=False, separators=(",", ":"))
    raise ValueError(f"stages_json 类型非法：{type(stages).__name__}")

def transport_keys_to_canonical(raw: Mapping[str, object]) -> Dict[str, object]:
    """运输键归一；同义键合并，后写不覆盖已有非空 canonical。"""
    if not isinstance(raw, Mapping):
        raise ValueError("structured decree raw 须为 object")
    out: Dict[str, object] = dict(raw)
    for src, dest in _TRANSPORT_KEY_ALIASES.items():
        if src not in raw:
            continue
        if dest in out and _as_str(out.get(dest)).strip():
            continue
        out[dest] = raw[src]
    if not _as_str(out.get("action_type")).strip():
        for key in ("dossier_action_type", "动作类型"):
            if _as_str(out.get(key)).strip():
                out["action_type"] = out[key]
                break
    return out

def build_transformation_tendency_facts(
    *,
    supervision_history: Sequence[Mapping[str, object]],
    loophole_exposures: Sequence[Mapping[str, object]],
) -> Dict[str, object]:
    """观察槽用定性事实包——禁数值钝化分。"""
    longest = 0
    upright_hit = False
    mediocre_hit = False
    relations: List[str] = []
    auditors: List[str] = []
    for row in supervision_history:
        months = int(row.get("consecutive_months") or 0)
        if months > longest:
            longest = months
        band = str(row.get("auditor_integrity_band") or "")
        if band in INTEGRITY_UPRIGHT_BANDS:
            upright_hit = True
        if band in INTEGRITY_MEDIOCRE_BANDS:
            mediocre_hit = True
        rel = str(row.get("faction_relation") or "")
        if rel:
            relations.append(rel)
        name = str(row.get("auditor_name") or "")
        if name:
            auditors.append(name)
    exposure_classes = sorted({
        f"{row.get('action_type')}+{row.get('execution_form')}"
        for row in loophole_exposures
        if row.get("action_type") and row.get("execution_form")
    })
    out = dict(EMPTY_TRANSFORMATION_TENDENCY_FACTS)
    out.update({
        "longest_consecutive_presence_months": longest,
        "has_upright_auditor": upright_hit,
        "has_mediocre_auditor": mediocre_hit,
        "faction_relations": sorted(set(relations)),
        "auditor_names": sorted(set(auditors)),
        "exposure_classes": exposure_classes,
        "exposure_count": len(list(loophole_exposures)),
    })
    return out

