def cutout_white(im: Image.Image, threshold: int, soft: int) -> Image.Image:
    im = im.convert("RGBA")
    w, h = im.size
    pix = im.load()
    bg = set()
    q = deque()

    def push(x: int, y: int) -> None:
        if (x, y) in bg:
            return
        r, g, b, a = pix[x, y]
        if a == 0 or is_bg(r, g, b, threshold):
            bg.add((x, y))
            q.append((x, y))

    for x in range(w):
        push(x, 0)
        push(x, h - 1)
    for y in range(h):
        push(0, y)
        push(w - 1, y)

    while q:
        x, y = q.popleft()
        for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
            if 0 <= nx < w and 0 <= ny < h:
                push(nx, ny)

    # Soften only pixels adjacent to connected background; do not remove internal whites.
    edge_pixels = {}
    for x, y in bg:
        pix[x, y] = (*pix[x, y][:3], 0)
        for nx in range(max(0, x - 1), min(w, x + 2)):
            for ny in range(max(0, y - 1), min(h, y + 2)):
                if (nx, ny) not in bg:
                    r, g, b, a = pix[nx, ny]
                    edge_alpha = alpha_for_pixel(r, g, b, threshold, soft)
                    if edge_alpha < a:
                        edge_pixels[(nx, ny)] = min(edge_pixels.get((nx, ny), a), edge_alpha)
    for (x, y), a in edge_pixels.items():
        r, g, b, old_a = pix[x, y]
        pix[x, y] = (r, g, b, max(32, a))
    return im

def push(x: int, y: int) -> None:
    if (x, y) in bg:
        return
    r, g, b, a = pix[x, y]
    if a == 0 or is_bg(r, g, b, threshold):
        bg.add((x, y))
        q.append((x, y))

def _judge_payload_from_prompt(prompt: object) -> dict:
    """Decode the user JSON exactly as serialized into the real CLI prompt."""
    if not isinstance(prompt, str):
        raise RuntimeError("CLI judge trace has no prompt")
    marker = "【皇帝/输入】\n"
    positions = [index for index in range(len(prompt)) if prompt.startswith(marker, index)]
    if len(positions) != 1:
        raise RuntimeError(f"CLI judge prompt must have one user payload; got {len(positions)}")
    start = positions[0] + len(marker)
    try:
        payload, consumed = json.JSONDecoder().raw_decode(prompt[start:])
    except json.JSONDecodeError as exc:
        raise RuntimeError("CLI judge prompt user payload is not complete JSON") from exc
    remainder = prompt[start + consumed:]
    if not remainder.startswith("\n\n【") or not isinstance(payload, dict):
        raise RuntimeError("CLI judge prompt user payload boundary is invalid")
    return payload

def _judge_payload_from_prompt(prompt: object) -> dict:
    """Decode the user JSON exactly as serialized into the real CLI prompt."""
    if not isinstance(prompt, str):
        raise RuntimeError("CLI judge trace has no prompt")
    marker = "【皇帝/输入】\n"
    positions = [index for index in range(len(prompt)) if prompt.startswith(marker, index)]
    if len(positions) != 1:
        raise RuntimeError(f"CLI judge prompt must have one user payload; got {len(positions)}")
    start = positions[0] + len(marker)
    try:
        payload, consumed = json.JSONDecoder().raw_decode(prompt[start:])
    except json.JSONDecodeError as exc:
        raise RuntimeError("CLI judge prompt user payload is not complete JSON") from exc
    remainder = prompt[start + consumed:]
    if not remainder.startswith("\n\n【") or not isinstance(payload, dict):
        raise RuntimeError("CLI judge prompt user payload boundary is invalid")
    return payload

