def normalize_audience_command_verdict(raw: Any) -> str:
    """判词缝归一：只放行封闭判词，其余 → none（毒化/坏 shape 零机械面）。"""
    if isinstance(raw, str) and raw in _CMD_VERDICTS:
        return raw
    return CMD_NONE

def presence_roster(db: Any, night_id: int) -> List[Dict[str, Any]]:
    """Project everyone who entered this night, in first-entry order, with current presence."""
    present: set[str] = set()
    ordered: List[str] = []
    seen: set[str] = set()
    for entry in list_ledger(db, int(night_id)):
        delta = _presence_delta(entry)
        names = [str(name) for name in entry.get("person_names") or []]
        if delta == PRESENCE_ENTER:
            for name in names:
                if name not in seen:
                    seen.add(name)
                    ordered.append(name)
        _apply_presence(present, entry)
    return [{"name": name, "present": name in present} for name in ordered]

def recognize_audience_command(message: str) -> str:
    """收夜/留侍口令结构化判词（#526）。

    确定性封闭集（COURT_BREAK / AMBIGUOUS_CLOSE / STAY_ATTEND）；引擎不重解析散文。
    不进 ACTION_CLUSTERS；非第二 parser（无自由散文正则启发）。
    无耗时软判——同步直调即可；坏 shape 由 normalize 归一，不在此宽吞异常。
    """
    from ming_sim.constants import (
        AMBIGUOUS_CLOSE_COMMANDS,
        COURT_BREAK_COMMANDS,
        STAY_ATTEND_COMMANDS,
    )

    text = str(message or "").strip()
    if not text:
        return CMD_NONE
    lowered = text.lower()
    if text in STAY_ATTEND_COMMANDS or lowered in STAY_ATTEND_COMMANDS:
        return CMD_STAY_ATTEND
    if lowered in COURT_BREAK_COMMANDS or text in COURT_BREAK_COMMANDS:
        return CMD_CLOSE_NIGHT
    if text in AMBIGUOUS_CLOSE_COMMANDS or lowered in AMBIGUOUS_CLOSE_COMMANDS:
        return CMD_AMBIGUOUS_CLOSE
    return CMD_NONE

def settle_applied_arrived_summons(
    db: Any, applied: Dict[str, Any],
) -> List[str]:
    """结清已由 canonical applier 成功续启赴京的在途召旨。

    只认 applied_person_changes 中未拒收且 transit_to=beizhili 的成功行止；
    同人全部 kind=in_transit 未结 origin 一并结清。失败/空 applied 为 no-op。
    外层 settle atomic 使行止与结清同成同败（_should_commit 已为 False）。
    """
    accepted = {
        str(item.get("name") or item.get("人物") or "").strip()
        for item in (applied.get("applied_person_changes") or [])
        if isinstance(item, dict)
        and not item.get("rejected")
        and str(item.get("transit_to") or item.get("去向") or "").strip() == "beizhili"
    }
    accepted.discard("")
    if not accepted:
        return []
    settled: List[str] = []
    for item in list_unsettled_summons(db):
        # 月度判官只收 in_transit origin；成功续启后 transit_to 已变，
        # 后置投影不再是 arrived，故按 person∈accepted 结清。
        if item["kind"] != "in_transit" or item["person_name"] not in accepted:
            continue
        origin = str(item["origin_id"])
        if settle_summon_origin(db, origin):
            settled.append(origin)
    return settled

def _dedicated_accounts(row: Any) -> List[str]:
    """专款账户读口（真实 producer 可达）：

    1. tags 含「专款:X」——承诺立项 new_issues.tags 既有写口（prompt 钉专款标签）
    2. ongoing_effects.economy[].account——承诺月供账户即专款流向
    """
    accounts: List[str] = []
    seen: Set[str] = set()

    def _add(raw: object) -> None:
        acc = str(raw or "").strip()
        if acc and acc not in seen:
            seen.add(acc)
            accounts.append(acc)

    try:
        keys = row.keys()
    except Exception:
        keys = []

    tags_raw = row["tags"] if "tags" in keys else "[]"
    try:
        tags = json.loads(tags_raw or "[]")
    except (TypeError, ValueError):
        tags = []
    if isinstance(tags, list):
        for tag in tags:
            t = str(tag or "").strip()
            if t.startswith("专款:"):
                _add(t.split(":", 1)[1].strip())

    ongoing_raw = row["ongoing_effects"] if "ongoing_effects" in keys else "{}"
    ongoing = loads_effect_dict(ongoing_raw or "{}")
    economy = ongoing.get("economy") if isinstance(ongoing, dict) else None
    if isinstance(economy, list):
        for item in economy:
            if isinstance(item, dict):
                _add(item.get("account"))
    return accounts

def _extract_ref_ids(items: object, *, prefixes: Sequence[str]) -> Set[int]:
    """统一 walker：从 list[dict] 抽 issue/dossier 引用 id。

    认 key 集合 + target_id 前缀 + origin_ref/来源引用；禁纯数字 target_id 误吞为 dossier。
    信用写端（#628）与哭谏识别共此单源，禁平行复制。
    """
    out: Set[int] = set()
    if not isinstance(items, list):
        return out
    id_keys_by_prefix = {
        "issue": ("issue_id", "id", "commitment_ref"),
        "dossier": ("dossier_id", "revoke_target_dossier_id"),
    }
    keys: Set[str] = set()
    for p in prefixes:
        keys.update(id_keys_by_prefix.get(p, ()))
    for it in items:
        if not isinstance(it, dict):
            continue
        for key in keys:
            raw = it.get(key)
            if raw in (None, ""):
                continue
            # issue walker 的裸 id 可能与 dossier_id 键冲突时仅在对应 prefix 下启用
            if key in {"id"} and "issue" not in prefixes:
                continue
            try:
                out.add(int(raw))
            except (TypeError, ValueError):
                continue
        tid = str(it.get("target_id") or "").strip()
        for p in prefixes:
            if tid.startswith(f"{p}:"):
                try:
                    out.add(int(tid.split(":", 1)[1]))
                except (TypeError, ValueError):
                    pass
        for key in ("origin_ref", "来源引用"):
            ref = str(it.get(key) or "").strip()
            for p in prefixes:
                if p == "issue":
                    m = _ISSUE_REF_RE.match(ref)
                    if m:
                        out.add(int(m.group(1)))
                elif p == "dossier":
                    m = _DOSSIER_REF_RE.match(ref)
                    if m:
                        out.add(int(m.group(1)))
    return out

def _note_funding_item(it: Dict[str, object]) -> None:
    oref = str(it.get("origin_ref") or "").strip()
    if oref:
        fund_origins.add(oref)
        m = _ISSUE_REF_RE.match(oref)
        if m:
            fund_issue_ids.add(int(m.group(1)))
    tid = str(it.get("target_id") or "")
    if tid.startswith("issue:"):
        try:
            fund_issue_ids.add(int(tid.split(":", 1)[1]))
        except (TypeError, ValueError):
            pass
    for key in ("issue_id", "commitment_ref"):
        raw = it.get(key)
        if raw in (None, ""):
            continue
        try:
            fund_issue_ids.add(int(raw))
        except (TypeError, ValueError):
            pass

def find_pending_plea(
    db: Any,
    commitment_ref: int,
    *,
    breach_kind: str = "",
) -> Optional[Dict[str, object]]:
    """返回匹配的 pending 哭谏条；breach_kind 非空时按 primary∪absorbed 认。"""
    want = str(breach_kind or "").strip()
    for todo in db.list_next_audience_todos(status=TODO_STATUS_PENDING):
        if str(todo.get("entry_kind") or "") != ENTRY_KIND_BREACH_PLEA:
            continue
        if int(todo.get("commitment_ref") or 0) != int(commitment_ref):
            continue
        if want:
            meta = decode_plea_meta(todo.get("origin_context"))
            if want not in plea_kind_set(meta):
                continue
        return todo
    return None

def plea_kind_set(meta: Dict[str, object]) -> Set[str]:
    """merged 条所载松手类 = primary ∪ absorbed（persist 链统一读口）。"""
    kinds: Set[str] = set()
    primary = str(meta.get("breach_kind") or "").strip()
    if primary:
        kinds.add(primary)
    absorbed = meta.get("absorbed_breach_kinds") or []
    if isinstance(absorbed, list):
        for raw in absorbed:
            kind = str(raw or "").strip()
            if kind:
                kinds.add(kind)
    return kinds

