def resolve_disposition_credit_from_extraction(
    db: Any, state: Any, extracted: Dict[str, object],
) -> List[Dict[str, object]]:
    """处置映射：丢卒保车 / 包庇 / 查办(不记)。对象须为已暴露变形案卷。"""
    if not isinstance(extracted, dict):
        return []
    items = _person_change_items(extracted)
    if not items:
        return []

    by_dossier: Dict[int, List[Dict[str, object]]] = {}
    for it in items:
        did = _item_dossier_id(it)
        if did is None:
            continue
        by_dossier.setdefault(did, []).append(it)

    out: List[Dict[str, object]] = []
    for did, group in by_dossier.items():
        dossier = db.get_decree_dossier(int(did))
        if not isinstance(dossier, dict) or not _is_exposed_transformed(dossier):
            continue
        roster = _roster_entries(dossier)
        parties = project_execution_liability_parties(roster)
        primary_ids = {
            str(p["character_id"])
            for p in parties
            if str(p.get("responsibility") or "") == "primary"
            and str(p.get("character_id") or "").strip()
        }
        liability_ids = {
            str(p["character_id"])
            for p in parties
            if str(p.get("character_id") or "").strip()
        }

        punitive, covered, by_person_ctx, group_ctx = _group_person_sets(group)

        # 1) 丢卒保车：卒受惩、委派人未惩 → 两笔弃卒保车
        scapegoat_hit = False
        for pawn, car in _pawn_car_pairs(roster):
            if pawn in punitive and car not in punitive:
                scapegoat_hit = True
                ctx = by_person_ctx.get(pawn) or group_ctx
                out.extend(_write_scapegoat_pair(
                    db, state, did=did, pawn=pawn, car=car, context=ctx,
                ))
        if scapegoat_hit:
            continue

        # 2) 查办：惩处落在连坐责任面（主办/委派）→ 不记事件
        if punitive & liability_ids:
            out.append({
                "kind": None,
                "disposition": "查办",
                "dossier_id": did,
                "punitive": sorted(punitive & liability_ids),
                "edge_id": None,
            })
            continue

        # 3) 包庇：责任面求交（删 or covered 兜底逸出）
        cover_targets = (covered & liability_ids) or (covered & primary_ids)
        out.extend(_write_cover_backs(
            db, state,
            did=did,
            targets=cover_targets,
            punitive=punitive,
            by_person_ctx=by_person_ctx,
            group_ctx=group_ctx,
        ))
    return out

def resolve_fulfillment_credit_from_extraction(
    db: Any, state: Any, extracted: Dict[str, object],
) -> List[Dict[str, object]]:
    """dossier_executions outcome=fulfilled → 兑付/撑完。

    消费调用方已滤 rejected 的落格项；本轴不再二次闸（单一保护点在
    apply_score_extraction 的 minus-rejections）。fulfilled 仍以 DB 终值为门。
    """
    if not isinstance(extracted, dict):
        return []
    out: List[Dict[str, object]] = []
    seen: Set[int] = set()
    for it in extracted.get("dossier_executions") or []:
        if not isinstance(it, dict):
            continue
        if str(it.get("outcome") or "").strip() != "fulfilled":
            continue
        try:
            did = int(it.get("dossier_id"))
        except (TypeError, ValueError):
            continue
        if did in seen:
            continue
        seen.add(did)
        out.extend(
            record_fulfillment_credit(
                db, state,
                dossier_id=did,
                context=_narrative_context(it.get("note"), it.get("reason")),
            )
        )
    return out

def _apply_military_order_office_effect(
    self, state, payload, *, actor: str, reason: str, origin_ref: str,
    content=None,
) -> None:
    """军令职守面：payload.office / office_changes → 人物变更唯一核。"""
    office_items: List[Dict[str, object]] = []
    raw_changes = payload.get("office_changes")
    if isinstance(raw_changes, list):
        for raw in raw_changes:
            if isinstance(raw, dict):
                office_items.append(dict(raw))
    office_title = str(payload.get("office") or "").strip()
    if office_title and actor:
        if not any(
            str(i.get("name") or "").strip() == actor
            and str(i.get("new_office") or i.get("office") or "").strip()
            for i in office_items
        ):
            office_item: Dict[str, object] = {
                "name": actor,
                "动作": "调任",
                "new_office": office_title,
                "office": office_title,
                "reason": reason,
            }
            # Preserve typed 任所 from dossier/pending payload; do not invent.
            seat = str(
                payload.get("region_id")
                or payload.get("任所")
                or payload.get("辖区")
                or ""
            ).strip()
            if seat:
                office_item["region_id"] = seat
            office_items.append(office_item)
    if not office_items:
        return
    from ming_sim.issues import _apply_person_changes
    prepared: List[Dict[str, object]] = []
    for item in office_items:
        entry = dict(item)
        entry.setdefault("origin_ref", origin_ref)
        entry.setdefault("动作", "调任")
        if not entry.get("new_office") and entry.get("office"):
            entry["new_office"] = entry["office"]
        prepared.append(entry)
    results = _apply_person_changes(
        self,
        state,
        prepared,
        content=content,
        origin_ref=origin_ref,
        require_origin=True,
        external_transaction=True,
    )
    accepted_p = [
        r for r in results
        if isinstance(r, dict) and not r.get("rejected")
    ]
    if not accepted_p:
        fail_reason = ""
        if results and isinstance(results[0], dict):
            fail_reason = str(results[0].get("reason") or "")
        raise ValueError(fail_reason or "军令职守变更物化失败")

def _apply_military_order_station_effect(
    self, state, *, army_id: str, station: str, actor: str, reason: str,
    origin_ref: str, station_region: str = "",
) -> None:
    """军令调驻面：既有军 station(+可选 station_region) → army 写核；不得 new_armies。

    #659：只改人读驻地/结构化驻地；不触 pay_source_region。仅 station 无 region
    时只改人读字段，region 保持原值（禁止从 station 文本反推）。
    """
    dest = str(station or "").strip()
    dest_region = str(station_region or "").strip()
    if not dest and not dest_region:
        return
    if not army_id:
        raise ValueError("军令调驻缺少军队 target")
    existing = self.conn.execute(
        "SELECT id FROM armies WHERE id = ?", (army_id,),
    ).fetchone()
    if existing is None:
        raise ValueError(
            f"军令调驻引用未入库军队 '{army_id}'（既有军调驻不得 new_armies）"
        )
    from ming_sim.models import Event
    pseudo = Event(
        id="military_order", title="军令调遣", kind="圣旨", summary="",
        urgency=0, severity=0, credibility=100, interests=[], audiences=[],
    )
    delta: Dict[str, object] = {"reason": reason}
    if dest:
        delta["station"] = dest
    if dest_region:
        delta["station_region"] = dest_region
    changes = self.apply_army_deltas(
        state, pseudo, None, actor or "军令",
        {army_id: delta},
        commit=False,
        origin_ref=origin_ref,
        require_origin=True,
    )
    # #521 r1：目标 station=当前站时 army 写核空接受=幂等 noop 成功，
    # 不得当硬失败以致同批职守变更回滚。
    rejected = [
        c for c in changes
        if isinstance(c, dict) and c.get("rejected")
    ]
    if rejected:
        fail_reason = str(rejected[0].get("reason") or "")
        raise ValueError(fail_reason or "军令调驻物化失败")

def _apply_punishment_verdict_effect(
    self, state, row, payload, dossier_id, *, content=None,
) -> None:
    """#517：惩处案卷顺颁后的结构化效果（受判类，打回不进此函数）。"""
    target = str(
