def normalize_office(office: str) -> str:
    """官职多职统一为半角逗号分隔：旧「兼/兼掌/兼署」与全角「，」「、」一律归一逗号，
    去空分项、去重、保序。是 office 字段落库的唯一规范化入口——所有写 characters.office
    的路径都过它，保证去重/顶缺时能按逗号分项匹配。"""
    s = (office or "").strip()
    if not s:
        return ""
    s = s.replace("兼掌", ",").replace("兼署", ",").replace("兼", ",")
    s = s.replace("，", ",").replace("、", ",")
    seen: set = set()
    parts: List[str] = []
    for p in (x.strip() for x in s.split(",")):
        if p and p not in seen:
            seen.add(p)
            parts.append(p)
    return ",".join(parts)

def transition_decree_dossier(
    self, dossier_id: int, new_status: str, *, commit: bool = True,
) -> None:
    row = self.conn.execute(
        "SELECT status,action_type,payload_json,execution_outcome FROM decree_dossiers WHERE id=?",
        (int(dossier_id),),
    ).fetchone()
    if row is None:
        raise KeyError(f"案卷不存在：{dossier_id}")
    old_status = str(row["status"])
    if new_status == old_status:
        return
    if new_status not in self._DOSSIER_TRANSITIONS[old_status]:
        raise ValueError(f"案卷非法迁移：{old_status} -> {new_status}")
    if old_status == "promulgated" and new_status == "closed":
        payload = json.loads(str(row["payload_json"] or "{}"))
        if self._dossier_has_execution_surface(row["action_type"], payload):
            raise ValueError("带执行判定面的案卷不得从 promulgated 直接 closed")
        if not str(row["execution_outcome"] or ""):
            raise ValueError("直达结案仍须填写执行格")
    closed_sql = ", closed_at=CURRENT_TIMESTAMP" if new_status == "closed" else ""
    self.conn.execute(
        f"UPDATE decree_dossiers SET status=?,updated_at=CURRENT_TIMESTAMP{closed_sql} "
        "WHERE id=?",
        (new_status, int(dossier_id)),
    )
    self._commit_dossier_write(commit)

def validate_fiscal_config_values(self, values: Dict[str, int]) -> None:
    if not values:
        return
    cfg = self.get_fiscal_config()
    overlay = dict(cfg)
    normalized: Dict[str, int] = {}
    for raw_key, raw_value in values.items():
        key = str(raw_key or "").strip()
        value = int(raw_value)
        minimum = self.fiscal_config_minimum_value(key)
        if minimum is not None and value < minimum:
            raise ValueError(f"fiscal_config.{key} 不得低于结构地板 {minimum}")
        pair = _CENTRAL_LOSS_RATE_PAIRS.get(key)
        if pair is not None and (value < 0 or value > 100):
            raise ValueError(f"fiscal_config.{key} 须在 0..100")
        normalized[key] = value
        overlay[key] = value

    checked_pairs = set()
    for key in normalized:
        pair = _CENTRAL_LOSS_RATE_PAIRS.get(key)
        if pair is None or pair in checked_pairs:
            continue
        checked_pairs.add(pair)
        human_key, sink_key = pair
        human = int(overlay.get(human_key, 0) or 0)
        sink = int(overlay.get(sink_key, 0) or 0)
        if human + sink > 100:
            raise ValueError(f"{human_key}+{sink_key} 不得超过 100%")

def _dispatch_effects(
    db: Any,
    state: Any,
    raw: object,
    *,
    night_id: int,
    collector: RejectionCollector,
    turn: int,
    source: Provenance,
    visible_refs: Optional[Mapping[str, object]] = None,
    defer_disclosure: bool = False,
) -> SectionResult:
    """把过月 C0 效果 envelope 交既有月末效果核算口，不复制领域适配器。

    召对夜里的 effects 表示旨意办理结果，仍只是预推候选；当场实况由各自
    section 承接，不能借 effects 绕过 ADR 0157 的过月落账边界。

    #1844：effects 数组按交代先后逐笔落账——后来的效果读到先前实际落账后的
    存量；不按实体段固定类别顺序重排跨类因果。一次 apply 内按旨序交错字段，
    批次性副作用（回流等）仍只核算一次。
    """
    if raw is None or raw == {}:
        return SectionResult(applied=[], rejected=[])
    if int(night_id or 0) > 0:
        return SectionResult(applied=[], rejected=[RejectedItem(
            item={"raw_value": raw}, reason="召对夜不能落旨意办理效果，须待过月核算",
            category="invalid_state", source=source,
        )])
    if not isinstance(raw, Mapping) and not isinstance(raw, list):
        return SectionResult(applied=[], rejected=[RejectedItem(
            item={"raw_value": raw}, reason="effects 须为对象或有序对象数组",
            category="invalid_shape", source=source,
        )])

    from ming_sim.simulation import EMPTY_EXTRACTION
    from ming_sim.issues import (
        _merge_first_event_outcome,
        apply_score_extraction,
        preflight_declared_event_effects,
        sanitize_delta_shape,
    )
    from ming_sim.decree import _collect_inline_rejections
    from ming_sim.person_delta_adapter import normalize_person_changes

    shape_rejections = []
    rejected = []
    has_effect = False
    clean_items = []
    for item in raw if isinstance(raw, list) else [raw]:
        if not isinstance(item, Mapping):
            rejected.append(RejectedItem(
                item={"raw_value": item}, reason="effects 单项须为对象",
                category="invalid_shape", source=source,
            ))
            continue
        has_effect = True
        # 归属是效果 envelope 的声明，不属于旧 extractor delta 的字段。
        event_id = str(item.get("event_id") or "").strip()
        clean, invalid = sanitize_delta_shape({k: v for k, v in item.items() if k != "event_id"})
        shape_rejections.extend(invalid)
        person_changes = normalize_person_changes(clean)
        if person_changes:
            clean["人物变更"] = person_changes
            for field in ("appointments", "character_status_changes", "character_power_changes", "office_changes"):
                clean[field] = []
        clean_items.append((item, event_id, clean))
    if not has_effect:
        return SectionResult(applied=[], rejected=rejected)

    refs = visible_refs or {}
    rejected_events = preflight_declared_event_effects(
        db, state, [(event_id, clean) for _, event_id, clean in clean_items],
        open_affair_ids=set(refs.get("affairs", ())),
    )
    extraction = copy.deepcopy(EMPTY_EXTRACTION)
    ordered_deltas = {field: [] for field in _ORDERED_DELTA_FIELDS}
    ordered_effect_event_ids = {field: [] for field in EMPTY_EXTRACTION}
    effect_sequence: list[tuple[dict[str, object], dict[str, list[tuple[str, object]]], dict[str, list[str]]]] = []
    accepted_effect = False
    accepted_event_ids: list[str] = []

def _dispatch_promises(
    db: Any, state: Any, raw: object, *, night_id: int,
    chat_turn_id: int, source: Provenance,
    preexisting_pending_ids: set[int],
) -> SectionResult:
    from ming_sim.strict_types import strict_int

    items, rejected = _section_items(raw, label="应允/拒绝/修改声明", source=source)
    applied: List[Any] = []
    for item in items:
        try:
            # Strict positive int only — bool/float/numeric strings must not
            # coerce via bare int() into another night's pending id.
            action_id = strict_int(
                item.get("action_id"), accept_numeric_strings=False,
            )
        except (TypeError, ValueError):
            action_id = 0
        decision = str(item.get("decision") or "").strip()
        if action_id <= 0 or decision not in {"应允", "拒绝", "修改", "留中"}:
            _reject(
                rejected, item, "判词声明须含正 action_id 与 应允/拒绝/修改/留中",
                "invalid_shape", source,
            )
            continue
        # 只认本夜（或本次无夜上下文）暂存清单里的动作：id 真实存在但挂在
        # 另一夜，声明也不得应允/拒绝它——同样按「不存在实体」拒收（不静默
        # 误批，也不当真拒收物理删除他夜暂存）。
        row = db.conn.execute(
            "SELECT night_id, kind, action, minister_name, night_approved, payload_json FROM pending_actions "
            "WHERE id=? AND turn=? AND status='pending'",
            (action_id, int(state.turn)),
        ).fetchone()
        if (
            row is None or action_id not in preexisting_pending_ids
            or int(row["night_id"] or 0) != int(night_id)
        ):
            _reject(
                rejected, item, f"暂存动作不属本夜暂存清单：{action_id}",
                "missing_ref", source,
            )
            continue
        kind = str(row["kind"] or "")
        action = str(row["action"] or "")
        declared_mode = item.get("mode")
        if declared_mode is not None and (
            kind != "directive" or decision != "应允"
            or not isinstance(declared_mode, str)
            or declared_mode not in {"ordinary", "midzhi"}
        ):
            _reject(rejected, item, "应允模式仅可指定普通/中旨拟旨", "invalid_shape", source)
            continue
        applied_row: Dict[str, Any] = {
            "action_id": action_id, "decision": decision, "kind": kind, "action": action,
        }
        if decision == "留中":
            if kind != "directive":
                _reject(rejected, item, "仅拟旨候选可留中", "invalid_shape", source)
                continue
            db.hold_over_pending_actions(
                int(state.turn), str(row["minister_name"]), [action_id],
            )
        elif decision == "修改":
            new_content = item.get("new_content")
            if (
                kind != "secret_order" or action != "新建"
                or not isinstance(new_content, str) or not new_content.strip()
            ):
                _reject(rejected, item, "只有新建密令可用非空 typed new_content 修改", "invalid_shape", source)
                continue
            payload = json.loads(row["payload_json"] or "{}")
            if not isinstance(payload, dict):
                raise ValueError("密令候选载荷损坏")
            payload["content"] = new_content
            db.conn.execute(
                "UPDATE pending_actions SET payload_json=?, night_approved=0 WHERE id=?",
                (json.dumps(payload, ensure_ascii=False), action_id),
            )
        elif decision == "应允":
            # ADR 0038：密令应允即落地（夜内直写白名单）；任免/拟旨只标

def _dispatch_textual_facts(
    db: Any, state: Any, raw: object, *, source: Provenance,
    source_turn_error: Optional[str] = None,
) -> SectionResult:
    items, rejected = _section_items(raw, label="文字事实声明", source=source)
    applied: List[Any] = []
    for item in items:
        if source_turn_error is not None:
            _reject(rejected, item, source_turn_error, "missing_ref", source)
            continue
        subject_kind = str(item.get("subject_kind") or "").strip()
        subject_id = str(item.get("subject_id") or "").strip()
        try:
            _assert_textual_fact_subject_exists(db, subject_kind, subject_id)
        except KeyError as exc:
            _reject(rejected, item, str(exc), "hallucinated_id", source)
            continue
        except ValueError as exc:
            _reject(rejected, item, str(exc), "invalid_shape", source)
            continue
        origin_ref, error_category = _resolve_affair_origin_ref(db, item)
        if error_category is not None:
            _reject(rejected, item, "事务声明未指向已开事务", error_category, source)
            continue
        try:
            fact = db.textual_facts.append(
                subject_kind=subject_kind, subject_id=subject_id,
                body=item.get("body"), year=state.year, period=state.period,
                turn=state.turn, origin_ref=origin_ref,
            )
        except ValueError as exc:
            _reject(rejected, item, str(exc), "invalid_shape", source)
            continue
        applied.append({
            "id": fact.id, "subject_kind": fact.subject_kind, "subject_id": fact.subject_id,
        })
    return SectionResult(applied=applied, rejected=rejected)

def _record_unknown_sections(
    collector: RejectionCollector, declaration: Mapping[str, object], turn: int,
    source: Provenance,
) -> None:
    """顶层键不在已知 section 之列（拼错字段名等）→ 逐个记一条
    ``invalid_shape`` 拒收，不静默漏项（ADR 0015 决定 7 / 票面 AC1，J2）。"""
    for key in declaration.keys():
        if key in _KNOWN_SECTIONS:
            continue
        collector.record(str(key), RejectedItem(
            item={"raw_value": declaration[key]}, reason=f"未知 section：{key}",
            category="invalid_shape", source=source,
        ), turn)

def _merge_compliant_promulgation_items(
    accumulated: List[Dict[str, object]],
    fresh: Sequence[Dict[str, object]],
) -> List[Dict[str, object]]:
    """跨补交轮次并集保留已合规判决：先到先留，后轮不得冲掉前轮好判（#1753）。

    输入仅来自 _collect_compliant_promulgation_items 已过闸项，不再二次类型过滤。
    """
    by_id: Dict[int, Dict[str, object]] = {}
    order: List[int] = []
    for row in list(accumulated) + list(fresh):
        dossier_id = int(row["dossier_id"])
        if dossier_id in by_id:
            continue
        by_id[dossier_id] = row
        order.append(dossier_id)
    return [by_id[item] for item in order]

def _provenance_from_stored(value: object) -> Provenance:
    """从 ctx 持久值还原 Provenance（#146 恢复路）：兼容 Provenance 实例、已存的字符串值、
    历史误序列化的 'Provenance.<name>' 字面串、及非法/缺失值。非法/缺失回落 system_simulation。

    防静默丢源（Sourcery + gemini + coderabbit #175 concur）：Provenance 是 (str, Enum)，
    若曾把枚举实例 str() 落库会得到 'Provenance.player_decree'（而非值 'player_decree'），
    Provenance(...) 不匹配 → ValueError → 丢源退回 system_simulation。故分三层：
    ① 实例直接返回；② 纯值走 Provenance(value)；③ 'Provenance.<name>' 旧脏串剥前缀按成员名查回；
    仍无法识别才回落 system_simulation。"""
    if isinstance(value, Provenance):
        return value
    text = str(value or "system_simulation")
    try:
        return Provenance(text)
    except ValueError:
        pass
    # 历史误序列化：str(枚举实例) 落库的 'Provenance.player_decree' 脏串——剥前缀按成员名查回，
    # 不让旧档玩家来源静默退化成 system_simulation。
    if text.startswith("Provenance."):
        try:
            return Provenance[text.split(".", 1)[1]]
        except KeyError:
            pass
    return Provenance.system_simulation

def _validate_promulgation_verdict_item(
    row: object, db: GameDB,
    *,
    proposed_modes: Optional[Dict[int, str]] = None,
    prepared_context: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """The single shape/identity authority for one provider verdict."""
    if not isinstance(row, dict):
        raise LLMContractError("颁布判决须为对象")
    if str(row.get("decision") or "") not in {"promulgated", "rejected"}:
        raise LLMContractError("颁布判决 decision 只能为 promulgated 或 rejected")
    dossier_id = row.get("dossier_id")
    if (isinstance(dossier_id, bool) or not isinstance(dossier_id, int)
            or not 0 < dossier_id <= 2 ** 63 - 1):
        raise LLMContractError("颁布判决 dossier_id 必须为有效 SQLite 正整数")

    context = prepared_context or {}
    if prepared_context is not None:
        faction_names = {
            str(item["name"]) for item in context.get("factions", [])
            if isinstance(item, dict)
        }
        class_names = {str(item) for item in context.get("classes", [])}
        gatekeeper_ids = {
            str(item["name"]) for item in context.get("gatekeepers", [])
            if isinstance(item, dict) and isinstance(item.get("name"), str)
        }
        context_dossiers = {
            int(item["id"]): item for item in context.get("dossiers", [])
            if isinstance(item, dict) and isinstance(item.get("id"), int)
        }
    else:
        faction_names = {
            str(item["name"]) for item in db.conn.execute("SELECT name FROM factions")
        }
        class_names = {
            str(item["name"])
            for item in db.conn.execute("SELECT DISTINCT name FROM classes")
        }
        gatekeeper_ids = {
            str(item["name"])
            for item in db.conn.execute("SELECT name FROM characters")
        }
        context_dossiers = {}

    modes = proposed_modes or {}
    rejection_only_fields = {
        "blocked_layer", "primary_opponents", "gatekeeper_id", "reason",
        "criteria_snapshot", "midzhi_unpromulgatable",
    }
    try:
        decision = row.get("decision")
        mode = modes.get(dossier_id) if isinstance(dossier_id, int) else None
        # Work on a shallow copy: 顺颁 may strip LLM noise without mutating caller input.
        item: Dict[str, object] = dict(row)
        if decision == "promulgated":
            # #1397 / r6: 颁布判官 LLM 常在 decision=promulgated 上夹带打回形解释字段
            # （reason/gatekeeper_id/primary_opponents/criteria_snapshot 等）。decision 已
            # 钉顺颁，这些字段是产出噪声而非语义；硬拒会在 pre_settle 落 settling 后
            # SettlementAbort 卡死整月。剥离已知噪声， downstream 按干净顺颁继续。
            # 真正未知键与打回契约仍硬拒（见下方 exact-key / rejection 校验）。
            for key in rejection_only_fields:
                item.pop(key, None)
            item.pop("legal_reason_code", None)
            # ordinary/midzhi 顺颁均省略 affected_parties（#657 §C.8 later-wins：中旨不猜派）。
            item.pop("affected_parties", None)
        elif mode == "midzhi" and decision == "rejected":
            # 中旨打回：剥离猜派字段；正式离心归 M12。
            item.pop("affected_parties", None)
        marker = item.get("midzhi_unpromulgatable", False)
        if not isinstance(marker, bool):
            raise ValueError("中旨亦不可颁标记必须为 bool")
        if marker:
            if mode is not None:
                if decision != "rejected" or mode != "midzhi":
                    raise ValueError("中旨亦不可颁只能标记中旨打回判决")
            elif decision != "rejected":
                raise ValueError("中旨亦不可颁只能标记打回判决")
        if any(isinstance(key, str) and key.startswith("resistance_") for key in item):
            raise ValueError("颁布判决不得携带阻力数值字段")

