def normalize_locality_scope(raw: object) -> str:
    """{'全国'/'单省'/'无'/缺省 → national/single/none}；枚举外 fail-loud。"""
    if raw is None:
        return "none"
    text = str(raw).strip()
    if not text:
        return "none"
    if text in _SCOPE_ALIASES:
        scope = _SCOPE_ALIASES[text]
    else:
        scope = text
    if scope not in LOCALITY_SCOPES:
        raise ValueError(f"locality_scope 非法：{raw!r}")
    return scope

def project_target_locality_matrix_prompt() -> str:
    """由 TARGET_KIND_LOCALITY_SCOPES 投影可接受面（供共同 prompt 消费；禁手抄）。"""
    groups: Dict[frozenset[str], list[str]] = {}
    for kind, scopes in TARGET_KIND_LOCALITY_SCOPES.items():
        groups.setdefault(scopes, []).append(kind)
    parts: list[str] = []
    for scopes in sorted(groups, key=lambda s: (sorted(s), len(s))):
        kinds = "|".join(sorted(groups[scopes]))
        if len(scopes) == 1:
            only = next(iter(scopes))
            parts.append(f"{kinds}仅{only}")
        else:
            parts.append(f"{kinds}∈{'|'.join(sorted(scopes))}")
    return (
        "target_kind×locality_scope 可接受面（" + "；".join(parts) + "）"
    )

def classify_execution_coverage(
    action_type: object, payload: Optional[Mapping[str, object]] = None,
) -> Optional[str]:
    """只读 canonical 动作及结构化细类判别执行覆盖域，不解析旨文。"""
    action = str(action_type or "").strip()
    if action in _COVERAGE_APPOINTMENT:
        return "appointment"
    if action in _COVERAGE_MULTI_MONTH:
        return "multi_month"
    if action == "punishment":
        from ming_sim.action_clusters import cluster_by_kind

        punish_action = str((payload or {}).get("punish_action") or "").strip()
        cluster = cluster_by_kind("punishment")
        field = next((f for f in cluster.fields if f.name == "punish_action"), None) if cluster else None
        if field is not None and field.execution_coverage is not None:
            return field.execution_coverage.get(punish_action)
    return None

def resolve_lead_executors(
    *,
    action_type: object = "",
    target_id: object = "",
    payload: Optional[Mapping[str, object]] = None,
    participant_roster: object = None,
) -> Dict[str, object]:
    """确定性点将路由（ADR 0117 净新契约 a）：返回结构化路由结果。

    leads 有序去重；signal.code='idle_start'＝怠办起步（任免无被任命者）。
    #1778 决定 3：没点将时代码不配人——名单由拟票大臣写在票拟里，
    空 leads 即空，不查职司表、不走降档链。
    """
    canonical_payload = payload or {}
    coverage = classify_execution_coverage(action_type, canonical_payload)
    if coverage is None:
        return {
            "coverage": None, "route": "excluded", "leads": [], "signal": None,
        }

    # ① 任免：执行主体＝被任命者本人
    if coverage == "appointment":
        who = str(target_id or "").strip()
        if who:
            return {
                "coverage": coverage,
                "route": "appointment_self",
                "leads": [who],
                "signal": None,
            }
        return {
            "coverage": coverage,
            "route": "appointment_self",
            "leads": [],
            "signal": {"code": "idle_start", "reason": "appointment_without_target"},
        }

    # ② 点将优先：规范化 assignee 是生产点将；0053 roster 是同义结构入口。
    assignee = str(canonical_payload.get("assignee_id") or "").strip()
    if assignee:
        return {
            "coverage": coverage, "route": "named",
            "leads": [assignee], "signal": None,
        }
    roster = participant_roster if isinstance(participant_roster, list) else []
    named: List[str] = []
    seen: set = set()
    for entry in roster:
        if not isinstance(entry, dict):
            continue
        if str(entry.get("tier") or "").strip() != "主办":
            continue
        name = str(entry.get("character_id") or "").strip()
        if name and not str(entry.get("delegator_id") or "").strip() and name not in seen:
            seen.add(name)
            named.append(name)
    return {
        "coverage": coverage,
        "route": "named" if named else "unassigned",
        "leads": named,
        "signal": None,
    }

def project_character_factions(db: Any) -> Dict[str, str]:
    """canonical 党籍投影（庭裁 r1 F1，纯投影、不持久化任何映射表）。

    characters.faction ∩ factions 表现存派系集合：命中者入映射；表外党籍
    （中宫/后金/嫔妃等真实种子）与皇帝节点不入。每次现算——党籍/派系集合
    随引擎演化，投影永远对表当前态。"""
    in_table = {
        row["name"] for row in db.conn.execute("SELECT name FROM factions").fetchall()
    }
    projection: Dict[str, str] = {}
    for row in db.conn.execute("SELECT name, faction FROM characters").fetchall():
        faction = row["faction"]
        if faction in in_table:
            projection[row["name"]] = faction
    return projection

def _oracle_effective_dues(p: Dict[str, Any]) -> Dict[str, float]:
    """oracle 侧折后应得重算：独立于落账的 _effective_dues/haircut_due。
    折发语义同律（floor(Due×bp/10000)、bp=10000 或缺省=无折），但代码自成一路。"""
    raw_h = p.get("due_haircut_bp")
    haircuts: Dict[str, int] = {}
    if raw_h is not None:
        if not isinstance(raw_h, dict):
            raise ValueError(f"param due_haircut_bp 非字典：{raw_h!r}")
        for hk, bp in raw_h.items():
            if hk not in _DUE_KEYS:
                raise ValueError(f"due_haircut_bp 含未知科目 {hk}")
            if isinstance(bp, bool) or not isinstance(bp, int):
                raise ValueError(f"due_haircut_bp[{hk}] 非整数：{bp!r}")
            if not (0 < bp <= 10000):
                raise ValueError(f"due_haircut_bp[{hk}] 须在 (0,10000]：{bp}")
            if bp != 10000:
                haircuts[hk] = bp
    out: Dict[str, float] = {}
    for h in _DUE_KEYS:
        _due = p["Due"]
        d = float(_due.get(h, 0.0)) if isinstance(_due, dict) else 0.0
        bp = haircuts.get(h)
        out[h] = float(math.floor(d * bp / 10000)) if bp is not None else d
    return out

def _oracle_order(p: Dict[str, Any], key: str, default: tuple) -> tuple:
    """oracle 侧序参重算：独立于落账的 _resolve_order_param。"""
    raw = p.get(key)
    if raw is None:
        return tuple(default)
    if isinstance(raw, str) or not isinstance(raw, (list, tuple)):
        raise ValueError(f"param {key} 非 list/tuple")
    if any(not isinstance(item, str) for item in raw):
        raise ValueError(f"param {key} 须为 {default} 的完整无重复排列：{raw!r}")
    items = tuple(raw)
    if len(items) != len(default) or set(items) != set(default) or len(set(items)) != len(items):
        raise ValueError(f"param {key} 须为 {default} 的完整无重复排列：{raw!r}")
    return items

def _resolve_haircut_param(p: Dict[str, Any]) -> Dict[str, int]:
    """#653 折发系数参（p["due_haircut_bp"]）：{科目: 万分数}，域 (0,10000]，越界 fail-loud。
    缺省/空 dict=无折（逐字节默认路径）。"""
    raw = p.get("due_haircut_bp")
    if raw is None:
        return {}
    if not isinstance(raw, dict):
        raise ValueError(f"param due_haircut_bp 非字典：{raw!r}")
    out: Dict[str, int] = {}
    for hk, bp in raw.items():
        if hk not in _DUE_KEYS:
            raise ValueError(f"due_haircut_bp 含未知科目 {hk}")
        if isinstance(bp, bool) or not isinstance(bp, int):
            raise ValueError(f"due_haircut_bp[{hk}] 非整数：{bp!r}")
        if not (0 < bp <= 10000):
            raise ValueError(f"due_haircut_bp[{hk}] 须在 (0,10000]：{bp}")
        if bp != 10000:
            out[hk] = bp
    return out

def _resolve_order_param(p: Dict[str, Any], key: str, default: tuple) -> tuple:
    """#653 override 序参（p[key]）验形：缺省=祖制默认序；在位必须是合法排列，
    否则 ValueError（fail-loud）。返回定长 tuple 供结算与 oracle 同源消费。"""
    raw = p.get(key)
    if raw is None:
        return default
    if isinstance(raw, str) or not isinstance(raw, (list, tuple)):
        raise ValueError(f"param {key} 非 list/tuple")
    if any(not isinstance(item, str) for item in raw):
        raise ValueError(f"param {key} 须为 {default} 的完整无重复排列：{raw!r}")
    if len(raw) != len(default) or set(raw) != set(default) or len(set(raw)) != len(raw):
        raise ValueError(f"param {key} 须为 {default} 的完整无重复排列：{raw!r}")
    return tuple(raw)

def settle_tick(
    st: Dict[str, Any], p: Dict[str, Any], actions: List[Dict[str, Any]]
) -> FiscalTickResult:
    """单省单月财政 tick。st=开账(CASH/CLAIM/官民田/隐田)，p=本月参数(率/额/Due)，
    actions=本月动作(玩家旨意/事件灌入)。返回新末态 + 流水分解；坏输入/守恒破一律 raise。"""
    # ── 容器型验形（最前置）：st/p 非 dict、actions 非 list/tuple → ValueError，否则下方
    #    `sk in st` / `rq in p` / `for a in actions` 抛 TypeError 逃逸调用方隔离（cmr R3 concur）──
    if not isinstance(st, dict):
        raise ValueError("st 非字典")
    if not isinstance(p, dict):
        raise ValueError("p 非字典")
    if not isinstance(actions, (list, tuple)):
        raise ValueError("actions 非 list/tuple")
    # ── 必填参数 presence（缺省不默认 0——火耗率缺省成 0 = 静默改经济学）──
    for rq in ("三饷应征", "火耗率", "逋赋率", "起运定额", "Due"):
        if rq not in p:
            raise ValueError(f"param {rq} 缺失")
    # ── 开账 stock 全面验形（前置于下方 float 构造：float([]) 等非数值会 TypeError 早于守门、
    #    逃逸调用方 (ValueError/守恒破) 隔离炸 pre_settle，cmr ship-pre R1/R2；CLAIM 也拦——
    #    负军饷欠→偿还环凭空生钱）──
    for sk in (*CASH_KEYS, *CLAIM_KEYS, "官民田", "隐田"):
        if sk in st and st[sk] is None:
            raise ValueError(f"开账 stock {sk} 为 None")
        _sraw = st.get(sk, 0)
        if isinstance(_sraw, bool) or not isinstance(_sraw, (int, float)):
            raise ValueError(f"开账 stock {sk} 非数值")
        if not math.isfinite(float(_sraw)):
            raise ValueError(f"开账 stock {sk} 非有限值(NaN/inf)")
        if float(_sraw) < 0:
            raise ValueError(f"开账 stock {sk} 为负")

    cash = {k: float(st.get(k, 0)) for k in CASH_KEYS}
    claim = {k: float(st.get(k, 0)) for k in CLAIM_KEYS}
    官民田 = float(st.get("官民田", 0))
    隐田 = float(st.get("隐田", 0))
    地0 = 官民田 + 隐田  # 土地守恒锚：清丈只重分类，总亩数不变
    cash0 = sum(cash.values())
    C0 = {k: cash[k] for k in CASH_KEYS if k.startswith("C_")}
    claim0 = dict(claim)
    cash_in = cash_out = 0.0
    # Due 在任何折算消费前验形，避免坏容器先逃成 TypeError/AttributeError。
    _due = p["Due"]
    if isinstance(_due, bool) or not isinstance(_due, dict):
        raise ValueError("Due 非字典")
    for hk, dv in _due.items():
        if hk not in _DUE_KEYS:
            raise ValueError(f"Due 含未知科目 {hk}")
        if isinstance(dv, bool) or not isinstance(dv, (int, float)):
            raise ValueError(f"Due[{hk}] 非数值")
        if not math.isfinite(float(dv)):
            raise ValueError(f"Due[{hk}] 非有限值(NaN/inf)")
        if float(dv) < 0:
            raise ValueError(f"Due[{hk}] 为负")

    # ── #653 偿还序 override ＋ Due 折发系数（ADR 0090）：缺省=祖制默认序、无折 ──
    due_order = _resolve_order_param(p, "due_order", _DUE_KEYS)
    arrears_order = _resolve_order_param(p, "arrears_order", _ARREARS_KEYS)
    _haircut_bp = _resolve_haircut_param(p)  # 验形 fail-loud；实际折算走 _effective_dues
    eff_due = _effective_dues(p)

    r: Dict[str, Any] = dict(
        实征=0, 火耗实收=0, 清欠=0, 拨付gross=0, 起运到京=0, 实付=0, 偿旧欠=0, 行政补饷=0,
        漂没=0, 中饱=0, 民欠新增=0, 蠲免=0, unmet_relief=0,
        NewDebt={"军饷欠": 0, "官俸欠": 0, "宗禄欠": 0},
        Repaid={"军饷欠": 0, "官俸欠": 0, "宗禄欠": 0},
        action还={"军饷欠": 0},
        # #653 流水分解新字段：per-科目实付分账（TSV 断言实付序）＋折发免除额
        实付分账={h: 0.0 for h in _DUE_KEYS},
        **{f"haircut_{h}": _raw_due(p, h) - eff_due[h] for h in _DUE_KEYS},
    )

    def xfer_internal(frm: str, to: str, amount: float, eff: float = 1.0) -> float:
        """CASH 内部 3-way 转移：source 减 = target 增 + C_eff损耗 增。"""
        actual = min(amount, cash[frm])
        cash[frm] -= actual
        got = actual * eff
        loss = actual * (1 - eff)
        cash[to] += got
        if loss > 0:
            cash["C_eff损耗"] += loss

def _fiscal_config_rate(db: GameDB, key: str) -> float:
    cfg = db.get_fiscal_config()
    minimum = db.fiscal_config_minimum_value(key)
    if key not in cfg and (
        minimum is not None or db.fiscal_config_loss_rate_pair(key) is not None
    ):
        raise ValueError(f"fiscal_config.{key} 缺失")
    raw = cfg.get(key, 0)
    if isinstance(raw, bool):
        raise ValueError(f"fiscal_config.{key} 非法：{raw!r}")
    try:
        value = float(raw)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"fiscal_config.{key} 非数值：{raw!r}") from exc
    if not math.isfinite(value) or value < 0 or value > 100:
        raise ValueError(f"fiscal_config.{key} 越界：{raw!r}")
    if minimum is not None and value < minimum:
        raise ValueError(f"fiscal_config.{key} 低于结构地板 {minimum}：{raw!r}")
    return value / 100.0

def _fixed_flow_scalars_are_numeric(region_id: str, fiscal: dict) -> bool:
    for key in _FIXED_FLOW_NUMERIC_FIELDS:
        if key not in fiscal:
            continue
        value = fiscal[key]
        try:
            finite_number = (
                not isinstance(value, bool)
                and isinstance(value, (int, float))
                and math.isfinite(float(value))
            )
        except OverflowError:
            finite_number = False
        if not finite_number:
            tlog(f"[province-fiscal] {region_id} fiscal.{key} 非数字，本{TURN_UNIT}固定税收出列")
            return False
    return True

def _apply_bandit_absorptions(
    db: GameDB,
    state: GameState,
    absorptions: object,
    *,
    commit: bool = True,
) -> Tuple[List[Dict[str, object]], List[Dict[str, object]], List[Dict[str, object]]]:
    """#652/0087：流民投贼吸收原子 applier。

    LLM 只产 typed 请求；本核：actual=min(requested, 省池)→扣流民池（无农民对端，
    0087 兵源出口单侧出池）→仅 actual>0 允许实力正增（δ=actual//换算率，0–100 clamp
    走 apply_power_deltas）。超池/非法 id/零池正请求 → 逐项拒收留痕。
    返回 (applied_absorptions, rejections, power_changes)。
    """
    should_commit = bool(commit) and db.owns_transaction()
    applied: List[Dict[str, object]] = []
    rejected: List[Dict[str, object]] = []
    power_changes: List[Dict[str, object]] = []
    items = absorptions if isinstance(absorptions, list) else []
    # 仅 substrate 人口径新档开环；legacy 不误开（对齐 #649/#650）。
    if db.population_unit != POPULATION_UNIT_PERSONS:
        for item in items:
            rejected.append({
                "rejected": True, "category": "invalid_enum",
                "reason": "bandit_absorptions 仅适用于 population_unit='人' 的人口池档",
                "item": item if isinstance(item, dict) else {"raw_value": item},
            })
        return applied, rejected, power_changes

    for item in items:
        if not isinstance(item, dict):
            rejected.append({
                "rejected": True, "category": "invalid_shape",
                "reason": "bandit_absorptions 项必须是 object(dict)",
                "item": {"raw_value": item},
            })
            continue

        def _reject(category: str, reason: str) -> None:
            rejected.append({
                "rejected": True, "category": category,
                "reason": reason, "item": item,
            })

        extra = sorted(set(item) - BANDIT_ABSORPTION_FIELDS)
        if extra:
            _reject(
                "invalid_enum",
                f"bandit_absorptions 白名单外字段 {extra}"
                f"（合法字段：region_id/power_id/requested_count/origin_ref）",
            )
            continue

        region_id = str(item.get("region_id") or "").strip()
        power_id = str(item.get("power_id") or "").strip()
        origin_ref = str(item.get("origin_ref") or "").strip()
        if not region_id:
            _reject("missing_ref", "bandit_absorptions 缺 region_id")
            continue
        region_row = db.conn.execute(
            "SELECT controlled_by FROM regions WHERE id=?", (region_id,)
        ).fetchone()
        if region_row is None:
            _reject("missing_ref", f"bandit_absorptions 未知 region_id：{region_id!r}")
            continue
        if str(region_row["controlled_by"] or "") != "ming":
            _reject("missing_ref", f"bandit_absorptions 非明省不可吸收：{region_id!r}")
            continue
        if not power_id or not _is_bandit_power_id(power_id):
            _reject(
                "invalid_enum",
                f"bandit_absorptions power_id 须为流寇股（bandits/bandit_*）：{power_id!r}",
            )
            continue
        power_row = db.conn.execute(
            "SELECT id FROM powers WHERE id=?", (power_id,)
        ).fetchone()
        if power_row is None:
            _reject("hallucinated_id", f"bandit_absorptions 引用未入库势力 '{power_id}'")
            continue

