def legacy_reasoning_strength(data: Dict[str, object]) -> str:
    candidates = []
    if str(data.get("advanced_model") or "").strip():
        candidates.append(data.get("advanced_thinking_level"))
    candidates.append(data.get("thinking_level"))
    for value in candidates:
        legacy = str(value or "").strip().lower()
        if legacy in {"minimal", "disabled", "none"}:
            return "off"
        strength = normalize_reasoning_strength(legacy)
        if strength:
            return strength
    return ""

def normalize_reasoning_strength(value: object) -> str:
    strength = str(value or "").strip().lower()
    return strength if strength in {"off", "low", "medium", "high"} else ""

def supports_openai_reasoning_effort(model: str) -> bool:
    # #1461：任意 OpenAI 兼容配置可能带 provider 前缀（openai/gpt-5.x）
    model_id = openai_model_id_without_provider(model)
    return model_id.startswith(("o1", "o3", "o4", "gpt-5"))

def _openai_reasoning_effort(model: str, reasoning_strength: str, thinking_level: str, enable_thinking: bool) -> str:
    if reasoning_strength == "off":
        model_id = openai_model_id_without_provider(model)
        # 关思考：按族默认，禁止再续 gpt-5.x 版本清单（#1452 gpt-5.6 曾掉表外→minimal）。
        # o1/o3/o4 只认 minimal（#1461：o3/o4 发 none 会被不支持的 provider 拒）；
        # gpt-5* 及未知新族默认 none。
        if model_id.startswith(("o1", "o3", "o4")):
            return "minimal"
        return "none"
    if reasoning_strength:
        return _OPENAI_REASONING_BY_STRENGTH.get(reasoning_strength, "")
    if thinking_level:
        return thinking_level
    if enable_thinking:
        return "medium"
    return ""

def _require_agno() -> None:
    from packaging.requirements import Requirement
    from packaging.utils import canonicalize_name
    from packaging.version import Version
    from ming_sim.constants import ROOT_DIR

    for raw in Path(ROOT_DIR, "requirements.txt").read_text(encoding="utf-8").splitlines():
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue
        req = Requirement(line)
        if canonicalize_name(req.name) != "agno":
            continue
        installed = installed_distribution_version(req.name)
        if Version(installed) not in req.specifier:
            raise DependencyMismatch(
                f"installed {req.name} {installed} does not satisfy {line}",
                package=req.name,
                requirement=line,
            )
        return
    raise DependencyMismatch(
        "requirements.txt has no declaration for agno",
        package="agno",
        requirement="",
    )

