def _run_output_status_is_error(run_output: object) -> bool:
    """agno Agent.run 失败时 status=RunStatus.error（值 'ERROR'），content=str(exc)。

    #1299/#1310：此 status 是 runner/provider 失败的权威信号；不得把 content 当叙事放行。
    """
    status = getattr(run_output, "status", None)
    if status is None:
        return False
    raw = getattr(status, "value", status)
    return str(raw).strip().upper() in {"ERROR", "FAILED"}

def run_error_event_failure(
    content: object = None, status_code: object = None,
) -> ClassifiedFailure:
    """RunErrorEvent → 分类唯一构造。无 typed status 时不洗成瞬断（#1452）。"""
    pmsg = str(content or "").strip() or "stream error"
    status_i = _coerce_status(status_code)
    if status_i is None:
        return ClassifiedFailure(
            retryable=False,
            code="llm_stream_error",
            status_code=None,
            provider_message=pmsg,
            message=f"LLM 流式调用失败：{pmsg}",
        )
    return ClassifiedFailure(
        retryable=_status_retryable(status_i),
        code=f"llm_http_{status_i}",
        status_code=status_i,
        provider_message=pmsg,
        message=f"LLM 流式调用失败：{pmsg}",
    )

def _unique_aliases(aliases: List[str]) -> List[str]:
    unique: List[str] = []
    seen: set = set()
    for alias in aliases:
        key = compact_name(alias)
        if not key or key in seen:
            continue
        seen.add(key)
        unique.append(alias)
    return unique

def army_identity_aliases(army: Army) -> List[str]:
    """军队身份别名：id / 军名 / 受控别名。不含驻地/战区/将领上下文。"""
    aliases = [army.id, army.name, compact_name(army.name)]
    for part in re.split(r"\s*/\s*|\s*／\s*", army.name):
        if part.strip():
            aliases.append(part.strip())
    aliases.extend(ARMY_SPECIAL_ALIASES.get(army.id, ()))
    return _unique_aliases(aliases)

def canonical_army_id_exact(
    raw: object, armies: Dict[str, Army],
) -> Optional[str]:
    """协饷等写缝专用：仅 compact 精确等值（id/军名/受控身份别名）。

    空串 → ''；未知非空 → None（调用方 fail-loud）。
    禁止子串/模糊；不调用 match_army_id_from_text；不吃 theater 等上下文。
    """
    if raw is None:
        return ""
    text = str(raw).strip()
    if not text:
        return ""
    text = _strip_controlled_namespace(text, "army")
    key = compact_name(text)
    if not key:
        return ""
    for army in armies.values():
        for alias in army_identity_aliases(army):
            if compact_name(alias) == key:
                return army.id
    return None

def canonical_region_id_exact(
    raw: object, regions: Optional[Dict[str, Region]] = None,
) -> Optional[str]:
    """location 写缝专用：仅 compact 精确等值（id/name/region_aliases）。

    空串 → ''；未知非空 → None（调用方 fail-loud）。
    禁止子串/模糊；不调用 match_region_id_from_text。
    """
    if raw is None:
        return ""
    text = str(raw).strip()
    if not text:
        return ""
    text = _strip_controlled_namespace(text, "region")
    special = resolve_special_region_alias(text)
    if special is not None:
        return special
    key = compact_name(text)
    if not key:
        return ""
    for region in (regions or {}).values():
        candidates = [region.id, region.name, *region_aliases(region)]
        for alias in candidates:
            if compact_name(alias) == key:
                return region.id
    return None

def region_aliases(region: Region) -> List[str]:
    aliases = [region.id, region.name, compact_name(region.name)]
    for part in re.split(r"\s*/\s*|\s*／\s*", region.name):
        if part.strip():
            aliases.append(part.strip())
    aliases.extend(REGION_SPECIAL_ALIASES.get(region.id, ()))
    unique: List[str] = []
    seen: set = set()
    for alias in aliases:
        key = compact_name(alias)
        if not key or key in seen:
            continue
        seen.add(key)
        unique.append(alias)
    return unique

