def _scene_opening_text(
    state: Any,
    present_rows: Sequence[tuple[str, str]],
    spoken: str,
    handling_by_person: Sequence[tuple[str, Sequence[tuple[str, str]]]],
    pending_audience_facts: Sequence[str] = (),
) -> str:
    """场景 LLM 开场最小集（ADR 0155）：在场、日期、正经手、本场已说、当前待裁场面。"""
    if present_rows:
        present_line = "、".join(
            f"{name}（{office}）" if office else name for name, office in present_rows
        )
    else:
        present_line = "（尚无）"
    parts = [
        f"在场：{present_line}",
        f"日期：{int(state.year)}年{int(state.period)}月",
    ]
    # 各在场人正经手事务（名字 + 当前情况一句）；无人经手则标（无）。
    parts.append("正经手事务：")
    any_handling = False
    for name, affairs in handling_by_person:
        if not affairs:
            continue
        any_handling = True
        parts.append(f"{name}：")
        parts.extend(f"- {title}：{situation}" for title, situation in affairs)
    if not any_handling:
        parts.append("（无）")
    parts.append("本场已说的话：")
    parts.append(spoken if spoken.strip() else "（尚无）")
    # #1838 reopen / ADR 0155：当前待裁场面（到期复命、暗渠摊派暴露/缺口重开）
    parts.append("当前待裁场面：")
    if pending_audience_facts:
        parts.extend(str(line) for line in pending_audience_facts)
    else:
        parts.append("（无）")
    parts.append(
        "在场诸人各自材料在 人物/<名>/ 下（人物档料、经历、公事档案、朝臣名册、事务、公开说法）。"
        "根目录 INDEX 一行一项。其余想读自己读。"
    )
    return "\n".join(parts)

def _scene_pending_audience_facts(db: Any, state: Any) -> list[str]:
    """#1838 reopen：待裁场面原样事实（到期复命 / 暗渠摊派暴露与缺口重开 / 谏催）。

    原喂开夜旁白；现并入场景开场最小集。结构化事实原样，不加措辞模板。
    """
    from ming_sim.audience_night import list_unsettled_summons
    from ming_sim.due_review import list_due_review_scenes
    from ming_sim.urge_lever import list_urge_audience_scenes

    lines: list[str] = []
    for scene in list(list_due_review_scenes(db, state)) + list(
        list_urge_audience_scenes(db, state)
    ):
        if not isinstance(scene, dict):
            continue
        lines.append(json.dumps(scene, ensure_ascii=False, sort_keys=True))
    for summon in list_unsettled_summons(db):
        facts = {key: summon[key] for key in ("person_name", "kind", "travel_tone") if key in summon}
        lines.append(json.dumps(facts, ensure_ascii=False, sort_keys=True))
    return lines

def _write_world_textual_fact_files(
    tmp: Path, db: Any, include_fact: Any = None,
) -> list[str]:
    """World directory: character/army/region textual facts once from store.

    affair facts already ride 事务/*/当前情况.txt — do not mint a second carrier.
    """
    store = getattr(db, "textual_facts", None)
    if store is None or not hasattr(db, "conn"):
        return []
    rows = db.conn.execute(
        "SELECT DISTINCT subject_kind, subject_id FROM textual_facts "
        "WHERE subject_kind IN ('character', 'army', 'region') "
        "ORDER BY subject_kind, subject_id"
    ).fetchall()
    index: list[str] = []
    for row in rows:
        kind = str(row["subject_kind"] or "").strip()
        subject_id = str(row["subject_id"] or "").strip()
        if not kind or not subject_id:
            continue
        facts = store.readable_materials(subject_kind=kind, subject_id=subject_id)
        body = "\n".join(
            str(fact.body or "")
            for fact in facts
            if _keep_fact(fact, include_fact)
        )
        if not body:
            continue
        label = subject_id
        if kind == "region" and hasattr(db, "region_rows"):
            for region in db.region_rows():
                if str(region["id"] or "") == subject_id:
                    label = str(region["name"] or subject_id)
                    break
        elif kind == "army" and hasattr(db, "army_rows"):
            for army in db.army_rows():
                if str(army["id"] or "") == subject_id:
                    label = str(army["name"] or subject_id)
                    break
        rel = f"{_FACT_DIR}/{kind}-{_safe_segment(label)}.txt"
        _write_text(tmp / rel, body)
        index.append(rel)
    return index

def candidate_supply(
    db: Any, state: Any, *, exclude_dossier_ids: Optional[set[int]] = None,
) -> dict[str, list]:
    """#1893：本月可供模型挑选的人物事件与弹劾潮候选（只供事实，不代选）。

    人物事件候选走既有 ``gather_candidate_events`` 硬门（时间窗 / 状态门 /
    已发·避过·过期终态 / auto_trigger 均已在读侧排除），弹劾潮候选走既有
    ``gather_impeachment_surge_candidates`` 硬门（旨外变形暴露 × 派系 leverage）。
    两条门只给资格与结构化事实；选不选、发不发难仍由同一次月末世界段里的
    模型决定（ADR 0014 / 0091 / P6）。
    """
    from ming_sim.issues import (
        gather_candidate_events,
        gather_impeachment_surge_candidates,
    )

    events = [_candidate_event_fact(ev) for ev in gather_candidate_events(state, db)]
    excluded = set(exclude_dossier_ids or ())
    surge = [
        dict(item)
        for item in gather_impeachment_surge_candidates(state, db)
        if int(item.get("dossier_id") or 0) not in excluded  # type: ignore[arg-type]
    ]
    return {"events": events, "impeachment_surge": surge}

def character_office_archive_text(db: Any, state: Any, character: Any, knowledge: dict) -> str:
    """本衙门公事档案：职位底账 + 可见案卷。与目录 公事档案.txt 同一份。"""
    from ming_sim.decree_vocabulary import render_referenceable_dossier_brief

    name = str(getattr(character, "name", "") or "")
    world = dict(knowledge.get("world") or {})
    office_lines = [
        f"{key}：{value}"
        for key, value in world.items()
        if key in _LEDGER_KEYS and str(value or "").strip()
    ]
    if hasattr(db, "list_referenceable_dossiers"):
        brief = render_referenceable_dossier_brief(
            db.list_referenceable_dossiers(name, state.turn),
        )
        if brief:
            office_lines.append(brief)
    return "\n".join(office_lines) or "（无）"

def current_root() -> Path:
    value = root() if callable(root) else root
    text = str(value or "").strip()
    if not text:
        # Empty/cleared MaterialsRoot must not resolve Path("") → CWD.
        raise ValueError("材料目录未就绪")
    return Path(text)

def _class_effect_has_work(raw: object) -> bool:
    if not isinstance(raw, dict):
        return False
    for value in raw.values():
        if not isinstance(value, dict):
            continue
        if any(
            field in ("satisfaction", "leverage") and _nonzero_int(delta)
            for field, delta in value.items()
        ):
            return True
    return False

def _entity_delta_has_work(
    raw: object,
    *,
    aliases: Dict[str, str],
    numeric_fields: tuple[str, ...],
    text_fields: tuple[str, ...] = (),
) -> bool:
    if not isinstance(raw, dict):
        return False
    numeric = set(numeric_fields)
    text = set(text_fields)
    for changes in raw.values():
        if not isinstance(changes, dict):
            continue
        for raw_field, value in changes.items():
            field = aliases.get(str(raw_field).strip(), str(raw_field).strip())
            if field in numeric and _nonzero_int(value):
                return True
            if field in text and _nonempty_text(value):
                return True
    return False

def _faction_effect_has_work(raw: object) -> bool:
    if not isinstance(raw, dict):
        return False
    for value in raw.values():
        if isinstance(value, dict):
            if any(
                field in ("satisfaction", "leverage") and _nonzero_int(delta)
                for field, delta in value.items()
            ):
                return True
        elif _nonzero_int(value):
            return True
    return False

def _new_armies_effect_has_work(raw: object) -> bool:
    if not isinstance(raw, list):
        return False
    for item in raw:
        if not isinstance(item, dict):
            continue
        mapped = {ARMY_FIELD_ALIASES.get(str(k).strip(), str(k).strip()): v for k, v in item.items()}
        if _nonempty_text(mapped.get("id")) and _nonzero_int(mapped.get("manpower")):
            return True
    return False

def _person_effect_has_work(raw: object) -> bool:
    if not isinstance(raw, list):
        return False
    for item in raw:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name") or item.get("人物") or "").strip()
        action = str(item.get("动作") or item.get("action") or "").strip()
        if not name or action not in PERSON_ACTIONS:
            continue
        if action == "评定":
            loyalty = item.get("loyalty")
            if (
                not isinstance(loyalty, bool)
                and isinstance(loyalty, int)
                and loyalty != 0
            ):
                return True
            continue
        if action == "性情":
            style = item.get("style")
            if isinstance(style, str) and style.strip():
                return True
            continue
        return True
    return False

def _apply_decided_triad(
    db: Any, state: Any, row: Dict[str, object], choice: Dict[str, object], *, content: Any,
) -> None:
    event_id = str(row.get("event_id") or "")
    raw_id = event_id.split(":", 1)[1] if ":" in event_id else ""
    if not raw_id.isdigit():
        return
    dossier_id = int(raw_id)
    dossier = db.get_decree_dossier(dossier_id)
    if dossier is None or not dossier.get("rescript_pending"):
        return
    decision = str(
        choice.get("dossier_decision") or choice.get("action") or ""
    ).strip()
    if decision not in {"force_promulgated", "withdrawn", "hold"}:
        return
    db.apply_dossier_promulgation(
        state, dossier_id, decision, content=content,
    )

def _collect_disclosures_from_result(chain: Optional[Dict[str, Any]], result: Any) -> None:
    if chain is None or result is None:
        return
    pending = chain.setdefault("pending_disclosures", [])
    effects = getattr(result, "effects", None)
    applied = getattr(effects, "applied", []) if effects is not None else []
    for report in applied:
        if not isinstance(report, dict):
            continue
        for update in report.get("secret_order_updates") or []:
            if isinstance(update, dict) and update.get("disclosed"):
                item = {
                    "order_id": int(update["order_id"]),
                    "sim_note": str(update.get("sim_note") or ""),
                }
                if item not in pending:
                    pending.append(item)

def _consume_rescript_answers(
    session: Any, chain: Dict[str, Any], *, source: Provenance,
) -> None:
    """把已裁批红接回案卷 / 请旨续推；幂等，已落不动。

    同一旨 / 同一世界段多问须全部答完才续推一次（ADR 0157 步骤 4）。
    """
    db, state = session.db, session.state
    turn = int(state.turn)
    from ming_sim.rescript_draft import consume_memorial_answers
    consume_memorial_answers(session, chain, source=source)
    rows = db.list_pending_decisions(turn)
    decided = [r for r in rows if str(r.get("status") or "") == "decided"]
    if not decided:
        return

    def _answer_from_row(row: Dict[str, object]) -> Dict[str, object]:
        choice = row.get("choice") if isinstance(row.get("choice"), dict) else {}
        return {
            **row, "choice": dict(choice),
            "label": str(choice.get("label") or ""),
            "hint": str(choice.get("hint") or ""),
            "note": str(choice.get("note") or ""),
            "context": str(row.get("context") or ""),
            "event_id": str(row.get("event_id") or ""),
            "title": str(row.get("title") or ""),
        }

    for row in decided:
        event_id = str(row.get("event_id") or "")
        if event_id.startswith("deliberation:"):
            from ming_sim.rescript_actions import apply_imperial_deliberation_push
            original = db.get_decree_dossier(int(event_id.partition(":")[2]))
            if (row["choice"] or {}).get("action") == "imperial_push" and (original["payload"] or {}).get("deliberation_state") == "stalled":
                with atomic(db):
                    apply_imperial_deliberation_push(
                        db, state, target_dossier_id=int(original["id"]),
                        decision_key=row["decision_key"],
                        decree_text=(row.get("choice") or {}).get("note", ""),
                    )
            continue
        if not event_id.startswith("dossier:"):
            continue
        choice = row.get("choice") if isinstance(row.get("choice"), dict) else {}
        _apply_decided_triad(db, state, row, choice, content=session.content)

    world_rows = [
        r for r in rows
        if str(r.get("event_id") or "").startswith(_WORLD_QUESTION_PREFIX)
        and int(str(r["event_id"]).rsplit(":", 1)[1]) >= int(chain.get("world_question_offset", 0))
    ]
    if (
        world_rows
        and all(str(r.get("status") or "") == "decided" for r in world_rows)
        and chain.get("world_questions")
    ):
        _record_world_question_event_choices(db, state, chain, world_rows, turn=turn)
        continue_world_after_answers(
            session, chain,
            answers=[_answer_from_row(r) for r in sorted(world_rows, key=lambda r: r["answer_order"])],
            source=source,
        )

    decree_rows_by_ref: Dict[str, List[Dict[str, object]]] = {}
    for row in rows:
        event_id = str(row.get("event_id") or "")
        if not event_id.startswith(_DECREE_QUESTION_PREFIX):
            continue
        body = event_id[len(_DECREE_QUESTION_PREFIX):]
        ref, _, idx = body.rpartition(":")
        if int(idx) < int((chain.get("decree_question_offsets") or {}).get(ref, 0)):
            continue
        decree_rows_by_ref.setdefault(ref, []).append(row)
    for ref, ref_rows in decree_rows_by_ref.items():
        if not all(str(r.get("status") or "") == "decided" for r in ref_rows):
            continue
        continue_decree_after_answers(
            session, decree_ref=ref, chain=chain,
            answers=[_answer_from_row(r) for r in sorted(ref_rows, key=lambda r: r["answer_order"])],
            source=source,

