def _decree_ref_is_secret(db: Any, decree_ref: str) -> bool:
    from ming_sim.materials import is_secret_order_origin

    if is_secret_order_origin(decree_ref):
        return True
    prefix = "pending-action:"
    if not str(decree_ref).startswith(prefix):
        return False
    raw = str(decree_ref)[len(prefix):].split(":", 1)[0]
    if not raw.isdigit() or not hasattr(db, "conn"):
        return False
    row = db.conn.execute(
        "SELECT kind FROM pending_actions WHERE id=?", (int(raw),),
    ).fetchone()
    return row is not None and str(row["kind"] or "") == "secret_order"

def _feed_identity_names(feed: Mapping[str, Any]) -> List[str]:
    """从 4a 供料里取出该备身份材料的人名（承办人与被查者，去重保序）。

    供料与材料树两处都以这里为准：供料给路径、材料树写正文，名单不同源就会
    出现"给了路径却读不到"或"备了没人指"的对不上。
    """
    names: List[str] = []
    for order in feed.get("active_secret_orders") or []:
        if not isinstance(order, Mapping):
            continue
        for side in ("investigator_identity_materials", "investigation_target_identity_materials"):
            who = str((order.get(side) or {}).get("name") or "").strip()
            if who and who not in names:
                names.append(who)
    return names

def _open_rescript_items(
    db: Any, state: Any, chain: Dict[str, Any],
) -> Dict[str, Any]:
    """本回合待答：打回三选 + 旨意请旨 + 世界段请旨。上月已答项不入。"""
    from ming_sim.decree_forecast import decree_ref_for_dossier

    turn = int(state.turn)
    triad = _this_turn_rescript_dossiers(db, turn)
    decree_questions: List[tuple[str, list]] = []
    seen_refs: set[str] = set()
    for dossier in db.list_decree_dossiers():
        ref = decree_ref_for_dossier(db, dossier)
        if ref in seen_refs:
            continue
        seen_refs.add(ref)
        questions = db.staged_declarations.questions_for(ref)
        if questions:
            # 未答请旨不论案卷创建回合，均须本回合收口（#1847 / 留中回流同审）。
            decree_questions.append((ref, questions))
    world_questions = [
        q for q in (chain.get("world_questions") or []) if isinstance(q, dict)
    ]
    return {
        "triad": triad,
        "decree_questions": decree_questions,
        "world_questions": world_questions,
    }

def _clear_settlement_display_if_orphan(
    db: "GameDB", state: "GameState", *, reason: str,
) -> bool:
    """同谓词 clearer：快照在 ∧ 相位非常态前半段 → 清快照。settling/awaiting 不清。"""
    turn = int(state.turn)
    phase = str(state.turn_phase or "")
    if phase in FRONT_HALF_DONE_PHASES:
        return False
    if db.get_month_open_snapshot(turn) is None:
        return False
    db.clear_month_open_snapshot(turn)
    tlog(f"[month_open_snapshot] {reason} turn={turn} phase={phase}")
    return True

def petition_verdict_grounding(db: Any, state: Any) -> list[dict[str, object]]:
    """已呈皇帝、待亲裁落定结局的三饷事项及其封闭标签集（#1892 / ADR 0143 输入侧）。

    只列事件账里已有请旨答复、终态仍空的事项。到期但尚未上疏的事项不在此列，
    转译器不得把它们写成已批。不声明结局即留中，引擎不写终态。只供事实，不代模型判断。
    """
    from ming_sim.issues import _fiscal_levy_event_by_id, petition_outcome_is_admissible

    out: list[dict[str, object]] = []
    for row in db.list_event_petition_records():
        event_id = str(row.get("event_id") or "")
        if not event_id or any(item["event_id"] == event_id for item in out):
            continue
        if not petition_outcome_is_admissible(state, db, event_id, None):
            continue
        ev = _fiscal_levy_event_by_id(event_id)
        if ev is None:
            continue
        out.append({
            "event_id": event_id,
            "title": ev.title,
            "verdict_labels": list(getattr(ev, "terminal_reason_labels", []) or []),
        })
    return out

def office_leverage_multiplier(office: object, already_normalized: bool = False) -> float:
    """Map an office title to the faction-leverage rank multiplier via offices.json.

    Comma-separated concurrent titles take the highest recognized multiplier. Titles with
    no leverage-bearing stem keep the historical conservative default 1.0.
    """
    del already_normalized  # retained for the historical caller contract
    parts = concurrent_office_titles(office)
    if not parts:
        return DEFAULT_LEVERAGE_MULTIPLIER

    table = _table()
    office_weights: list[float] = []
    for part in parts:
        matches: list[tuple[int, float]] = []
        modifiers: list[float] = []
        for rule in _iter_rank_rules(table):
            if "leverage_multiplier" not in rule:
                continue
            for stem in rule.get("stems") or []:
                token = str(stem or "").strip()
                if not token or token not in part:
                    continue
                weight = float(rule["leverage_multiplier"])
                if token in {"候补", "候用"}:
                    modifiers.append(weight)
                else:
                    matches.append((len(token), weight))
        if matches or modifiers:
            longest = max((length for length, _weight in matches), default=-1)
            base_weights = [weight for length, weight in matches if length == longest]
            # Longest title stem identifies the office; explicit status modifiers then
            # constrain it. This preserves old min-within-title semantics without letting
            # generic substrings (御史 inside 佥都御史) demote the base title.
            office_weights.append(min([*base_weights, *modifiers]))
    # Concurrent offices contribute at the strongest real office, as before.
    return max(office_weights, default=DEFAULT_LEVERAGE_MULTIPLIER)

def is_non_person_participant_name(name: str) -> bool:
    """raw 层：裸机构整词 / 自称泛称集体 → 非人物参与人；带姓称谓别名放行走 canon。"""
    n = str(name or "").strip()
    if not n:
        return True
    if n in NON_PERSON_PARTICIPANT_NAMES:
        return True
    if n in BARE_INSTITUTION_PARTICIPANT_NAMES:
        return True
    return False

def _live(config: Dict[str, int], key: str, turn: int) -> bool:
    """键在位且未到期（伴随键 <完整键名>_until_turn：turn > until → 退出格律）。"""
    if key not in config:
        return False
    until = config.get(str(key) + _UNTIL_SUFFIX)
    if until is not None and turn > int(until):
        return False
    return True

def parse_override_key(key: str) -> ParsedOverrideKey:
    """按 r3 白名单解析 override 键；非法形状 raise PayOrderKeyError（=ValueError）。

    词法：``<family><subject>[@<region_id>][#<source>]``。@ 必须先于 #；
    空词位（悬空 @ / #）、未知 family/subject、priority 族带 #、非军饷带 # 一律非法。
    本函数纯词法，不查 regions 表（region 存在性由物化端校验，防 @SX 类幻影 region）。
    """
    raw = str(key or "")
    body = raw
    source = ""
    if "#" in body:
        body, _, source = body.partition("#")
        if source not in _HAIRCUT_SOURCES:
            raise PayOrderKeyError(f"override 键 {raw!r}：#饷源后缀仅限 province/central")
    region = ""
    if "@" in body:
        body, _, region = body.partition("@")
        if not region:
            raise PayOrderKeyError(f"override 键 {raw!r}：@后 region_id 为空")
    if "@" in region or "#" in region:
        raise PayOrderKeyError(f"override 键 {raw!r}：scope 后缀顺序须为 @region#source")
    for family in (HAIRCUT_FAMILY, *_PRIORITY_FAMILIES):
        if body.startswith(family):
            subject = body[len(family):]
            break
    else:
        raise PayOrderKeyError(f"override 键 {raw!r}：未知键族（须 due_priority_*/arrears_priority_*/due_haircut_bp_*）")
    if family == HAIRCUT_FAMILY:
        if subject not in DUE_SUBJECTS:
            raise PayOrderKeyError(f"override 键 {raw!r}：未知折发科目 {subject!r}")
        if source and subject != "军饷":
            raise PayOrderKeyError(f"override 键 {raw!r}：饷源后缀仅军饷科目合法")
    else:
        legal = DUE_SUBJECTS if family == DUE_PRIORITY_FAMILY else ARREARS_SUBJECTS
        if subject not in legal:
            raise PayOrderKeyError(f"override 键 {raw!r}：{family}*/ 未知科目 {subject!r}")
        if source:
            # r3：序无饷源维度，# 后缀非法
            raise PayOrderKeyError(f"override 键 {raw!r}：priority 键族不允许 #饷源后缀")
    return ParsedOverrideKey(family=family, subject=subject, region=region, source=source)

def prepare_pay_order_entries(
    db: Any, entries: List[Dict[str, Any]],
) -> List[Tuple[str, int, Optional[int]]]:
    """整道旨载荷先验后写（fail-loud、零副作用）：键形白名单、值域、同道重复键、
    幻影 region 一律 ValueError 拒**整道旨**。成案点（create_decree_dossier staging）
    与物化点（materialize_pay_order_decree）共此同一验形，禁两套漂移。"""
    seen: set[str] = set()
    prepared: List[Tuple[str, int, Optional[int]]] = []
    for entry in entries:
        key = str((entry or {}).get("key") or "")
        parsed = parse_override_key(key)  # 非法形状 fail-loud
        if key in seen:
            raise PayOrderKeyError(f"同道旨内重复键 {key!r}")
        seen.add(key)
        value = (entry or {}).get("value")
        validate_override_value(key, value)
        until_raw = (entry or {}).get("until_turn")
        until: Optional[int]
        if until_raw is None:
            until = None
        else:
            if isinstance(until_raw, bool) or not isinstance(until_raw, int) or until_raw <= 0:
                raise PayOrderKeyError(f"override 键 {key!r} 期限 until_turn 须为正整数：{until_raw!r}")
            until = int(until_raw)
        if parsed.region:
            row = db.conn.execute(
                "SELECT 1 FROM regions WHERE id = ?", (parsed.region,)
            ).fetchone()
            if row is None:
                # r4：不新增 alias、不造虚拟 region——幻影 region_id fail-loud 拒写整道旨
                raise PayOrderKeyError(f"override 键 {key!r}：region_id {parsed.region!r} 不存在（禁 alias/虚拟 region）")
        prepared.append((key, int(value), until))
    return prepared

def normalize_title_kind(value: object) -> str:
    """Normalize ADR 0009 title-kind values used for active normalization."""
    raw = str(value or "").strip()
