    raw_source = (
        item["施动者"] if item.get("施动者") is not None else item.get("source")
    )
    if not isinstance(raw_source, str):
        raise ValueError(
            "施动者不能为空" if raw_source is None
            else f"施动者必须为字符串，得 {type(raw_source).__name__}"
        )
