def bind_origin_round(origin: Any, turn: int) -> tuple[str, int]:
    text = str(origin or "").strip()
    if not text:
        raise ValueError("边事件 origin 不能为空")
    match = _ROUND_RE.search(text) or _TURN_RE.search(text)
    if match:
        return text, int(match.group(1))
    round_no = int(turn)
    return f"{text}|round:{round_no}", round_no

def validate_edge_kind(event_kind: Any) -> str:
    kind = str(event_kind or "").strip()
    if kind not in EDGE_KINDS:
        raise ValueError(f"未知边事件类目: {kind!r}")
    return kind

def metric_delta(before: Dict[str, int], after: Dict[str, int]) -> Dict[str, int]:
    keys = list(before.keys())
    for key in after:
        if key not in before:
            keys.append(key)
    return {key: after.get(key, 0) - before.get(key, 0) for key in keys if after.get(key, 0) != before.get(key, 0)}

def _memorial(item: dict, actor: dict) -> dict:
    if not isinstance(item, dict) or not all(isinstance(item.get(k), str) for k in ("title", "context")):
        raise LLMContractError("票拟须提供奏折标题及全文")
    options = item.get("options")
    if not isinstance(options, list) or any(
        not isinstance(o, dict) or not isinstance(o.get("label"), str)
        or not isinstance(o.get("hint", ""), str) for o in options
    ):
        raise LLMContractError("票拟 options 须为拟批与说明的列表")
    return {**item, "actor_name": actor["name"], "actor_office": actor["office"],
            "actor_faction": actor["faction"] or ""}

def _ensure_close_night_confirm_cue(answer: str) -> str:
    """含糊收夜：大臣戏内确认（不出戏），不直接收夜。"""
    text = answer or ""
    ask = "陛下是要退朝么？"
    if ask in text:
        return text or ask
    if not text.strip():
        return ask
    return text + "\n" + ask

def _refuse_if_settling(self) -> None:
    """FRONT_HALF_DONE 冻结诏稿变更：恢复窗口新增/确认的 draft 会被 settle 的
    mark_directives_issued 连带标 issued，而重放 delta 不含它们=幽灵颁布（ship-pre r1）。"""
    if self.state.turn_phase in FRONT_HALF_DONE_PHASES:
        raise ValueError("月末结算进行中（恢复态），请先完成结算再改诏稿。")

def apply_appointment(
    db: GameDB,
    state: GameState,
    content: GameContent,
    data: Optional[Dict[str, object]] = None,
    llm_config: Optional[LLMConfig] = None,
    commit: bool = True,
) -> Tuple[str, str]:
    """诏书任命共用落地：建档入库，本回合即可召见。"""
    if not data:
        return ("", "")
    if "approved" in data and not bool(data.get("approved")):
        return ("", "")
    name = str(data.get("name") or "").strip()
    office = str(data.get("office") or "").strip()
    if not name or not office:
        return ("", "")
    office = normalize_office(office)
    # 显式名分（office_type ∈ PERSON_TITLE_KINDS）在此建 Character 前就得保住：add_character 的
    # 名分守卫看的是 character.office_type，若这里先被 infer 反推成官职（office='诸生'→'生员'），
    # 守卫永远见不到名分、误建 offices/character_offices（#1059 codex l6h）。
    office_type = resolve_office_type_preserving_title(
        office,
        str(data.get("office_type") or "").strip(),
        "待铨",
        llm_config or db.llm_config,
    )
    if office_type == "后宫":
        return ("", "")

    # ── 查重：精确名 + aliases 命中即拒，不重复建档 ──────────
    # 身份归一认识未仕/宗藩——在册者（含史可法诸生）由此拒新建，走 apply_office_appointment。
    if name in content.characters:
        return ("", "")
    existing = _find_existing_minister(content, name, db)
    if existing is not None:
        return ("", "")

    # ── 职位替换：腾缺现任者 → dismissed ───────────────────────────
    displaced = ""
    replaces = str(data.get("replaces") or "").strip()
    if replaces and replaces in content.characters:
        old = content.characters[replaces]
        if old.status == "active":
            db.set_character_status(
                state, replaces, "dismissed",
                reason=f"{office}改授{name}，原任去职",
                content=content,
                commit=commit,
            )
            displaced = replaces

    person_fields = canonical_new_appointment_person_fields(
        content, data.get("faction"),
    )
    character = Character(
        name=name,
        office=office,
        office_type=office_type,
        aliases=[],
        personal_skills=[],
        power_id="ming",
        status="active",
        office_region=str(
            data.get("office_region") or data.get("region_id") or ""
        ).strip(),
        **person_fields,
    )
    content.characters[name] = character
    db.add_character(state, character, llm_config=llm_config, commit=commit)
    # add_character 已写入并分配 portrait_id，回写到内存对象
    row = db.conn.execute(
        "SELECT portrait_id FROM characters WHERE name=?", (name,)
    ).fetchone()
    if row:
        character.portrait_id = str(row["portrait_id"])
    return (name, displaced)

