    raise ValueError(f"人物未建档：{clean_name}")

def normalize_commitment_stages(raw: object) -> List[Dict[str, object]]:
    """Normalize structured stages payload → durable list.

    Accepts list/tuple of dicts, or a JSON array string. Non-JSON free text
    returns [] here (读侧宽容面)；写侧由 ``stages_to_json`` 响亮拒绝。

    分段承诺是机械事实（到期判账），只认显式结构化字段。引擎不得从 LLM 自由
    散文正则反推语义（ADR 0142 / 锚定宪法「机器只咬契约，不咬呈现」；owner
    2026-09-30「肯定不能让代码去扣」）。原 ``parse_staged_year_promise`` 的
    中文数词年诺捕获已随该裁定删除，无任何接缝再从散文抠年份。
    """
    if raw in (None, "", [], ()):
        return []
    data = raw
    if isinstance(raw, str):
        text = raw.strip()
        if not text or text in ("[]", "{}"):
            return []
        try:
            data = json.loads(text)
        except (TypeError, ValueError):
            return []
    if not isinstance(data, (list, tuple)):
        return []
    out: List[Dict[str, object]] = []
    for idx, item in enumerate(data):
        if not isinstance(item, dict):
            continue
        try:
            due_turn = int(item.get("due_turn") or 0)
        except (TypeError, ValueError):
            continue
        if due_turn <= 0:
            continue
        try:
            stage_idx = int(item.get("stage_idx", idx))
        except (TypeError, ValueError):
            stage_idx = idx
        criterion = str(
            item.get("criterion_text") or item.get("criterion") or ""
        )
        origin_context = str(
            item.get("origin_context") or item.get("origin") or criterion or ""
        )
        if not criterion and origin_context:
            criterion = origin_context
        if not criterion:
            continue
        out.append({
            "stage_idx": stage_idx,
            "due_turn": due_turn,
            "criterion_text": criterion,
            "origin_context": origin_context or criterion,
        })
    out.sort(key=lambda s: (int(s["stage_idx"]), int(s["due_turn"])))
    return out

def _scope_was_explicit(raw: Mapping[str, object]) -> bool:
    for key in ("locality_scope", "施行范围"):
        if key not in raw:
            continue
        if _as_str(raw.get(key)).strip():
            return True
    return False

def assemble_structured_decree(
    raw: Mapping[str, object],
    *,
    conn: Any = None,
    regions_content: Optional[Mapping[str, Any]] = None,
    validate: bool = True,
) -> Dict[str, object]:
    """原始入口字段 → canonical 结构；不按 target_kind 覆盖已给 locality。"""
    src = transport_keys_to_canonical(raw)
    explicit_scope = _scope_was_explicit(raw) or _scope_was_explicit(src)

    action = _as_str(src.get("action_type") or "").strip()
    target_kind = _as_str(src.get("target_kind") or "").strip()
    target_id = _as_str(src.get("target_id") or "").strip()
    region_id = _as_str(src.get("region_id") or "").strip()
    if target_kind == "region":
        from ming_sim.matching import canonical_region_id_exact

        regions = dict(regions_content or {})
        canonical_target = canonical_region_id_exact(target_id, regions)
        canonical_region = canonical_region_id_exact(region_id or target_id, regions)
        if canonical_target is not None:
            target_id = canonical_target
        if canonical_region is not None:
            region_id = canonical_region

    out: Dict[str, object] = dict(src)
    if action:
        out["action_type"] = action
        if not _as_str(out.get("dossier_action_type")).strip():
            out["dossier_action_type"] = action
