def is_reported_actual_fork(
    *,
    reported_bands: Sequence[object],
    beyond_intent: bool,
    execution_outcome: object,
) -> bool:
    """#622/#627 fork 判据单源：有奏报且奏报与旨外实况或偏离执行格分叉。"""
    bands = [
        str(b).strip()
        for b in (reported_bands or ())
        if str(b or "").strip()
    ]
    outcome = str(execution_outcome or "").strip()
    return bool(bands) and (
        bool(beyond_intent) or outcome not in {"", "fulfilled", "executing"}
    )

def parse_report_origin(origin: object) -> Tuple[str, Tuple[str, ...]]:
    """拆 origin → (base_without_marks, marks_tuple)。"""
    raw = str(origin or "").strip()
    if not raw:
        return "", ()
    # namespace 前缀后的 body 才可带 mark
    ns = "dossier-report:"
    if not raw.startswith(ns):
        return raw, ()
    body = raw[len(ns):]
    if not body:
        return raw, ()
    parts = [p for p in body.split(ORIGIN_MARK_SEP) if p]
    if not parts:
        return raw, ()
    base = ns + parts[0]
    marks = tuple(parts[1:])
    return base, marks

def derive_opportunity_band(durable_effects: object) -> str:
    """由 economy/fiscal 流水派生可乘之利档（不依赖未落地 0119）。"""
    rows = list(durable_effects or [])
    if not rows:
        return "none"
    total_abs = 0
    for row in rows:
        if not isinstance(row, dict):
            continue
        for key in ("delta", "amount", "new_value", "old_value"):
            if key in row and row.get(key) is not None:
                try:
                    if key == "old_value":
                        continue
                    total_abs += abs(int(row.get(key) or 0))
                except (TypeError, ValueError):
                    pass
                break
        else:
            # fiscal change: |new-old|
            try:
                nv = int(row.get("new_value") or 0)
                ov = int(row.get("old_value") or 0)
                total_abs += abs(nv - ov)
            except (TypeError, ValueError):
                pass
    if total_abs <= 0:
        return "none"
    if total_abs >= _OPPORTUNITY_HIGH_ABS:
        return "high"
    return "low"

def normalize_axes(raw: object) -> list[str]:
    if raw is None:
        return []
    if isinstance(raw, str):
        items: list[object] = [raw]
    elif isinstance(raw, (list, tuple)):
        items = list(raw)
    else:
        return []
    out: list[str] = []
    seen: set[str] = set()
    for item in items:
        axis = normalize_axis(item)
        if axis is None or axis in seen:
            continue
        seen.add(axis)
        out.append(axis)
    return out

